export const course = {"id":"preset-ielts6","title":"学习雅思6分水平所需的语法知识","description":"学习雅思6分水平所需的语法知识，以真实考试的题型为准","goal":"学习雅思6分水平所需的语法知识，以真实考试的题型为准","cefr":"B2","syllabus":[{"title":"Simple Tenses and Time Expressions","skills":["simple_present_usage","simple_past_usage","simple_future_usage","time_expressions","tense_identification"],"description":"掌握一般现在时、一般过去时和一般将来时的基本用法及常见时间表达"},{"title":"Continuous and Perfect Tenses","skills":["present_continuous","past_continuous","present_perfect","past_perfect","tense_contrast"],"description":"学习进行时态与完成时态的构成与使用场景，区分各时态间的差异"},{"title":"Passive Voice","skills":["passive_formation","passive_tense_variations","passive_vs_active","passive_in_academic_writing"],"description":"掌握被动语态在不同时态中的构成方式及雅思写作和阅读中的常见用法"},{"title":"Modal Verbs","skills":["ability_modals","possibility_modals","obligation_modals","advice_modals","modal_perfect_forms"],"description":"学习情态动词的语义功能，包括可能性、必要性、能力与建议的表达"},{"title":"Conditional Sentences","skills":["zero_conditional","first_conditional","second_conditional","third_conditional","mixed_conditionals"],"description":"掌握零条件句、第一条件句、第二条件句及第三条件句的结构与应用"},{"title":"Relative Clauses","skills":["defining_relative_clauses","non_defining_relative_clauses","relative_pronouns","relative_adverbs","omitting_relative_pronouns"],"description":"学习限制性与非限制性定语从句的构成，以及关系代词和关系副词的正确使用"},{"title":"Noun Phrases and Articles","skills":["definite_article_usage","indefinite_article_usage","zero_article_rules","noun_phrase_structure","quantifiers"],"description":"深入理解名词短语结构、冠词用法规则及量词表达，提升学术写作的准确性"},{"title":"Comparison Structures","skills":["comparative_adjectives","superlative_adjectives","comparative_adverbs","as_as_structures","comparison_in_data_description"],"description":"掌握比较级与最高级的构成规则及雅思图表描述中常用的比较句型"},{"title":"Complex Sentences and Subordinate Clauses","skills":["time_clauses","reason_clauses","result_clauses","concession_clauses","purpose_clauses"],"description":"学习状语从句的类型与连接词用法，包括时间、原因、结果、让步与目的从句"},{"title":"Reported Speech","skills":["reported_statements","reported_questions","reported_commands","tense_backshift","reporting_verbs"],"description":"掌握间接引语的结构与时态回移规则，适用于雅思听力摘要与阅读理解场景"},{"title":"Cohesion and Linking Devices","skills":["additive_linkers","contrast_linkers","cause_effect_linkers","reference_devices","discourse_markers"],"description":"学习连接词、过渡语及指代关系的运用，提升写作与口语的连贯性和逻辑性"},{"title":"Academic Grammar for IELTS Tasks","skills":["infinitive_phrases","participial_phrases","gerund_structures","inversion_for_emphasis","hedging_language"],"description":"综合运用雅思学术类写作Task 1与Task 2所需的高级语法结构，包括非谓语动词与倒装句"}],"unitsData":{"1":{"levels":{"1":[{"type":"choice","options":["go","goes","went","will go"],"sentence":"She ___ to school every day.","subSkill":"simple_present_usage","explanation":"'every day' 表示每天的习惯，用一般现在时。主语是 she（第三人称单数），动词加 -s，所以用 goes。","instruction":"选择正确的动词形式，完成一般现在时句子。","correctIndex":1},{"type":"choice","options":["read","reads","will read","readed"],"sentence":"I ___ a book yesterday.","subSkill":"simple_past_usage","explanation":"'yesterday' 是过去时间标志词，用一般过去时。read 的过去式也是 read（不规则动词）。","instruction":"选择正确的时态，完成句子。","correctIndex":0},{"type":"choice","options":["go","goes","went","will go"],"sentence":"We ___ to the park tomorrow.","subSkill":"simple_future_usage","explanation":"'tomorrow' 是将来时间标志词，用一般将来时 will + 动词原形，所以选 will go。","instruction":"选择正确的时态，完成句子。","correctIndex":3},{"type":"choice","options":["一般现在时","一般过去时","一般将来时","现在进行时"],"sentence":"Tom played soccer last Saturday.","subSkill":"tense_identification","explanation":"'last Saturday' 是过去时间标志词，表示上周六，句子使用一般过去时。","instruction":"找出句子中的时间表达词，选出它所对应的时态。","correctIndex":1},{"type":"choice","options":["make","makes","made","will make"],"sentence":"My father ___ breakfast every morning.","subSkill":"simple_present_usage","explanation":"'every morning' 表示每天早晨的习惯，用一般现在时。主语 my father 是第三人称单数，动词加 -s，用 makes。","instruction":"选择正确的时态形式。","correctIndex":1},{"type":"choice","options":["build","built","builds","will build"],"sentence":"They ___ a new school next year.","subSkill":"simple_future_usage","explanation":"'next year' 是将来时间标志词，用一般将来时 will + 动词原形，所以选 will build。","instruction":"选择正确的时态，完成句子。","correctIndex":3},{"type":"choice","options":["finish","finishes","will finish","finished"],"sentence":"She ___ her homework two hours ago.","subSkill":"simple_past_usage","explanation":"'two hours ago' 是过去时间标志词，用一般过去时。finish 的过去式是 finished。","instruction":"选择正确的时态，完成句子。","correctIndex":3},{"type":"choice","options":["一般现在时","一般过去时","一般将来时","过去进行时"],"sentence":"The birds sing beautifully every spring.","subSkill":"tense_identification","explanation":"'every spring' 是重复性时间表达，句子描述每年春天都会发生的事情，使用一般现在时。","instruction":"判断下面句子使用了哪种时态。","correctIndex":0}],"2":[{"type":"choice","options":["have","has","had","will have"],"sentence":"The students ___ an English test last Friday.","subSkill":"simple_past_usage","explanation":"'last Friday' 是过去时间标志词，用一般过去时。have 的过去式是 had。","instruction":"选择正确的时态形式。","correctIndex":2},{"type":"fill","sentence":"My dog (bark) ___ at strangers.","subSkill":"simple_present_usage","explanation":"描述狗的习惯行为，用一般现在时。my dog 是第三人称单数，bark 加 -s，写 barks。","instruction":"用括号中动词的正确形式填空（一般现在时）。","acceptableAnswers":["barks"]},{"type":"choice","options":["yesterday","last night","two days ago","tomorrow"],"sentence":"I will call you ___.","subSkill":"time_expressions","explanation":"句子用了 will，是一般将来时，只有 tomorrow（明天）是将来时间标志词，其他三个都是过去时间表达。","instruction":"选出正确的时间表达词，使句子意思完整。","correctIndex":3},{"type":"fill","sentence":"We (visit) ___ the Great Wall last summer.","subSkill":"simple_past_usage","explanation":"'last summer' 是过去时间标志词，用一般过去时。visit 是规则动词，加 -ed，写 visited。","instruction":"用括号中动词的正确形式填空（一般过去时）。","acceptableAnswers":["visited"]},{"type":"choice","options":["eat","ate","eats","will eat"],"sentence":"Lions ___ meat. They never eat vegetables.","subSkill":"simple_present_usage","explanation":"描述狮子的本性和习性，用一般现在时。主语 lions 是复数，动词不加 -s，用 eat。","instruction":"选择正确的时态形式。","correctIndex":0},{"type":"fill","sentence":"She (travel) ___ to Beijing next month.","subSkill":"simple_future_usage","explanation":"'next month' 是将来时间标志词，用一般将来时 will + 动词原形，写 will travel。","instruction":"用括号中动词的正确形式填空（一般将来时）。","acceptableAnswers":["will travel"]},{"type":"choice","options":["tomorrow","next week","last night","usually"],"sentence":"He went to bed early ___.","subSkill":"time_expressions","explanation":"句子用了 went（go 的过去式），是一般过去时，只有 last night（昨晚）是过去时间标志词。","instruction":"选出正确的时间表达词，使句子意思完整。","correctIndex":2},{"type":"fill","sentence":"The baby (cry) ___ all night yesterday.","subSkill":"simple_past_usage","explanation":"'yesterday' 是过去时间标志词，用一般过去时。cry 是辅音 + y 结尾，去 y 加 -ied，写 cried。","instruction":"根据提示，用正确的时态填写动词。","acceptableAnswers":["cried"]}],"3":[{"type":"fill","sentence":"My parents (fly) ___ to Shanghai three days ago.","subSkill":"simple_past_usage","explanation":"'three days ago' 是过去时间标志词，用一般过去时。fly 是不规则动词，过去式是 flew。","instruction":"用括号中动词的正确形式填空，注意时态。","acceptableAnswers":["flew"]},{"type":"reorder","words":["usually","after","dinner","takes","she","a walk"],"subSkill":"simple_present_usage","explanation":"一般现在时句子结构：主语 + 频率副词 + 动词 + 其他。she 是第三人称单数，take 加 -s 变 takes。","instruction":"将单词重新排列，组成正确的英语句子（一般现在时）。","correctSentence":"She usually takes a walk after dinner."},{"type":"fill","sentence":"They (not go) ___ to school on weekends.","subSkill":"simple_present_usage","explanation":"描述周末的习惯，用一般现在时否定式。主语是 they（复数），用 don't + 动词原形，写 don't go。","instruction":"用括号中动词的正确形式填空，注意时态。","acceptableAnswers":["don't go","do not go"]},{"type":"reorder","words":["Tom","a","last","found","treasure","week"],"subSkill":"simple_past_usage","explanation":"一般过去时句子结构：主语 + 动词过去式 + 其他 + 时间。find 的过去式是 found（不规则动词）。","instruction":"将单词重新排列，组成正确的英语句子（一般过去时）。","correctSentence":"Tom found a treasure last week."},{"type":"fill","sentence":"The weather (be) ___ very cold last winter.","subSkill":"simple_past_usage","explanation":"'last winter' 是过去时间标志词，用一般过去时。be 动词过去式：the weather 是单数用 was。","instruction":"用括号中动词的正确形式填空，注意时态。","acceptableAnswers":["was"]},{"type":"reorder","words":["will","we","a","have","party","tomorrow","big"],"subSkill":"simple_future_usage","explanation":"一般将来时句子结构：主语 + will + 动词原形 + 其他 + 时间状语。","instruction":"将单词重新排列，组成正确的英语句子（一般将来时）。","correctSentence":"We will have a big party tomorrow."},{"type":"fill","sentence":"He (study) ___ French next semester.","subSkill":"simple_future_usage","explanation":"'next semester' 是将来时间标志词，用一般将来时 will + 动词原形，写 will study。","instruction":"用括号中动词的正确形式填空，注意时态。","acceptableAnswers":["will study"]},{"type":"reorder","words":["not","did","she","the","answer","question"],"subSkill":"simple_past_usage","explanation":"一般过去时否定句结构：主语 + did not（didn't）+ 动词原形 + 其他。注意否定句中动词恢复原形。","instruction":"将单词重新排列，组成正确的英语句子（一般过去时否定句）。","correctSentence":"She did not answer the question."}],"4":[{"type":"error","words":["He","goed","to","the","library","yesterday"],"subSkill":"simple_past_usage","correction":"went","errorIndex":1,"explanation":"'yesterday' 表示过去，需要用一般过去时。go 是不规则动词，过去式是 went，不能写成 goed。","instruction":"找出句子中的错误单词，并写出正确答案。"},{"type":"fill","sentence":"The class (begin) ___ at 8 o'clock every morning.","subSkill":"simple_present_usage","explanation":"描述每天的时间安排，用一般现在时。the class 是第三人称单数，begin 加 -s，写 begins。","instruction":"用括号中动词的正确形式填空，注意时态和主谓一致。","acceptableAnswers":["begins"]},{"type":"choice","options":["write","writes","wrote","will write"],"sentence":"In the past, people ___ letters, but now they use email.","subSkill":"tense_identification","explanation":"'In the past' 是过去时间标志词，描述过去的习惯用一般过去时。write 的过去式是 wrote（不规则动词）。","instruction":"选出最恰当的时态形式，使全句意思连贯。","correctIndex":2},{"type":"error","words":["My","sister","will","visited","us","next","Sunday"],"subSkill":"simple_future_usage","correction":"visit","errorIndex":3,"explanation":"句子已有 will，表示一般将来时，will 后面必须跟动词原形。visited 是过去式，应改为原形 visit。","instruction":"找出句子中的错误单词，并写出正确答案。"},{"type":"fill","sentence":"We (not see) ___ any sharks at the aquarium last week.","subSkill":"simple_past_usage","explanation":"'last week' 是过去时间标志词，否定用 didn't + 动词原形。注意否定句中动词不能用过去式，写 didn't see。","instruction":"用括号中动词的正确形式填空，注意否定句结构。","acceptableAnswers":["didn't see","did not see"]},{"type":"error","words":["The","sun","rise","in","the","east"],"subSkill":"simple_present_usage","correction":"rises","errorIndex":2,"explanation":"描述自然规律，用一般现在时。the sun 是第三人称单数，rise 要加 -s，写 rises。","instruction":"找出句子中的错误单词，并写出正确答案。"},{"type":"choice","options":["two years ago","last year","in two years","the day before yesterday"],"sentence":"She will graduate from primary school ___.","subSkill":"time_expressions","explanation":"句子用了 will，是一般将来时，只有 'in two years'（两年后）表示将来时间，其他三个都是过去时间表达。","instruction":"选择正确的时间表达词，使句子时态正确。","correctIndex":2},{"type":"fill","sentence":"___ you (visit) ___ the museum next weekend?","subSkill":"simple_future_usage","explanation":"一般将来时疑问句结构：Will + 主语 + 动词原形？将 will 提到主语前面，动词用原形 visit。","instruction":"用括号中动词的正确形式填空，完成一般将来时疑问句。","acceptableAnswers":["Will you visit"]}],"5":[{"type":"error","words":["Yesterday","she","don't","eat","breakfast"],"subSkill":"simple_past_usage","correction":"didn't","errorIndex":2,"explanation":"'Yesterday' 是过去时间标志词，否定句应用 didn't（did not），不能用 don't（现在时）。","instruction":"找出句子中的错误单词，并写出正确答案。"},{"type":"fill","sentence":"My grandfather (be) ___ a doctor. He (retire) ___ ten years ago, but he still (give) ___ free advice to neighbors now.","subSkill":"tense_identification","explanation":"三种时态同用：was（过去职业，过去时）/ retired（ten years ago，过去时）/ gives（now，现在时，单数加-s）。","instruction":"综合运用三种时态，用括号中动词的正确形式填空。","acceptableAnswers":["was","retired","gives"]},{"type":"reorder","words":["will","where","spend","you","the","summer","holiday"],"subSkill":"simple_future_usage","explanation":"特殊疑问句结构：疑问词 + will + 主语 + 动词原形 + 其他。Where 放在最前面，will 提前，动词用原形。","instruction":"将单词重新排列，组成正确的一般将来时疑问句。","correctSentence":"Where will you spend the summer holiday?"},{"type":"choice","options":["holds / won","held / wins","will hold / won","holds / win"],"sentence":"Every year, our school ___ a sports day. Last year, I ___ first place in the 100-meter race.","subSkill":"tense_identification","explanation":"'Every year' 用一般现在时，主语 our school 为单数，holds 正确；'Last year' 用一般过去时，won 正确（win 的不规则过去式）。","instruction":"阅读短文，选出空格处正确的时态形式。","correctIndex":0},{"type":"fill","sentence":"___ your parents (speak) ___ English at home?","subSkill":"simple_present_usage","explanation":"一般现在时一般疑问句：Do/Does + 主语 + 动词原形？your parents 是复数，用 Do，动词用原形 speak。","instruction":"用括号中动词的正确形式填空（一般现在时一般疑问句）。","acceptableAnswers":["Do your parents speak"]},{"type":"error","words":["Two","months","ago","we","buyed","a","new","house"],"subSkill":"simple_past_usage","correction":"bought","errorIndex":4,"explanation":"'Two months ago' 用一般过去时。buy 是不规则动词，过去式是 bought，不能写成 buyed。","instruction":"找出句子中的错误单词，并写出正确答案。"},{"type":"reorder","words":["homework","didn't","he","last","night","finish","his"],"subSkill":"simple_past_usage","explanation":"一般过去时否定句：主语 + didn't + 动词原形 + 其他 + 时间状语。didn't 后动词用原形 finish，not 过去式。","instruction":"将单词重新排列，组成正确的一般过去时否定句。","correctSentence":"He didn't finish his homework last night."},{"type":"fill","sentence":"Scientists say the world's oceans (become) ___ warmer in the future. In 1900, the average temperature (be) ___ much lower than it (be) ___ today.","subSkill":"tense_identification","explanation":"in the future 用将来时 will become；In 1900 用过去时 was；today 描述现状用现在时 is（第三人称单数）。","instruction":"综合运用时态，根据语境用正确形式填空。","acceptableAnswers":["will become","was","is"]}]},"mission":{"title":"My Three-Time Story","scenario":"想象你正在为班级壁报写一篇自我介绍短文，要让同学们了解你的过去、现在和未来。试着用上时间表达词，让你的文章更清晰、更生动！","scaffolds":[{"hint":"描述你每天的一个习惯或者爱好（一般现在时）","prefix":"Every day, I","suffix":".","example":"Every day, I read for 30 minutes before bed.","grammarCheck":"simple_present_usage"},{"hint":"描述上周或上个月发生的一件有趣的事（一般过去时，注意动词过去式）","prefix":"Last","suffix":".","example":"Last weekend, I visited my grandma and learned to make dumplings.","grammarCheck":"simple_past_usage"},{"hint":"写出你下周或未来的一个计划或期待（一般将来时，用 will）","prefix":"Next","suffix":".","example":"Next summer, I will travel to Yunnan with my family.","grammarCheck":"simple_future_usage"}],"description":"综合运用三种一般时态（一般现在时、一般过去时、一般将来时），写一篇关于自己的短文，描述你的日常生活习惯、过去发生的一件趣事，以及你未来的一个计划。","grammarType":"tense_identification"},"discover":{"tip":"三种一般时态的判断口诀：看到 every day / always / usually → 一般现在时；看到 yesterday / last week / ago → 一般过去时；看到 tomorrow / next week / will → 一般将来时。时间表达词是判断时态的关键线索！","story":{"text":"Tom is a student in Grade 4. Every day, he goes to school at 7:30 in the morning. He studies hard and always does his homework after school. Yesterday, Tom had a special day. He went to the science museum with his class. They saw many amazing robots and learned about space travel. Tom was very excited. He talked about it all evening. Tomorrow, Tom will visit his grandparents in the countryside. He will help them in the garden and feed the chickens. On Sunday, he will come back home. Tom always says, 'Every week is a new adventure!' Last week, he played soccer with his friends and won the game. Next week, he will start a new art class. Tom loves his busy life. He never gets bored because there is always something new to do, something old to remember, and something exciting to look forward to.","title":"A Busy Week for Tom","highlights":["every day","yesterday","tomorrow","always","last week","next week","goes","went","will visit","played","will start"]},"questions":[{"options":["He visits the museum.","He goes to school at 7:30.","He feeds the chickens.","He plays soccer."],"question":"What does Tom do every day?","explanation":"文章中说 'Every day, he goes to school at 7:30'，使用一般现在时描述每天的习惯动作。","correctIndex":1},{"options":["He started an art class.","He visited his grandparents.","He went to the science museum.","He played soccer."],"question":"What did Tom do yesterday?","explanation":"'Yesterday' 是过去时间标志词，文章说 'He went to the science museum'，使用一般过去时。","correctIndex":2},{"options":["He will go to the museum.","He will feed the chickens.","He will visit grandparents.","He will start a new art class."],"question":"What will Tom do next week?","explanation":"'Next week' 是将来时间标志词，文章说 'he will start a new art class'，使用一般将来时。","correctIndex":3}]}},"2":{"levels":{"1":[{"type":"choice","options":["play","plays","are playing","played"],"sentence":"Look! The children ___ in the park.","subSkill":"present_continuous","explanation":"Look!提示动作正在发生，主语是复数the children，所以用are playing（现在进行时）。","instruction":"选择正确的现在进行时形式：","correctIndex":2},{"type":"choice","options":["watch","watches","is watching","was watching"],"sentence":"At 8 pm last night, my dad ___ the news.","subSkill":"past_continuous","explanation":"At 8 pm last night表示过去某个具体时刻，主语my dad是单数，用was watching（过去进行时）。","instruction":"选择正确的过去进行时形式：","correctIndex":3},{"type":"choice","options":["see","saw","have seen","am seeing"],"sentence":"I ___ this movie three times.","subSkill":"present_perfect","explanation":"three times表示到目前为止的经历次数，用现在完成时have seen。","instruction":"选择正确的现在完成时形式：","correctIndex":2},{"type":"choice","options":["already left","has already left","had already left","already leaves"],"sentence":"When I arrived, the train ___.","subSkill":"past_perfect","explanation":"火车离开发生在我到达之前，需要用过去完成时had already left表示过去的过去。","instruction":"选择正确的过去完成时形式：","correctIndex":2},{"type":"choice","options":["一般现在时","现在进行时","现在完成时","过去进行时"],"subSkill":"present_continuous","explanation":"is doing是be动词+现在分词的结构，表示现在正在进行的动作，是现在进行时。","instruction":"选出句子中使用的时态：She is doing her homework right now.","correctIndex":1},{"type":"choice","options":["play","have played","were playing","had played"],"sentence":"They ___ soccer when it started to rain.","subSkill":"past_continuous","explanation":"when it started to rain表示过去某时，踢球是那时正在进行的背景动作，用过去进行时were playing。","instruction":"选择正确答案：","correctIndex":2},{"type":"choice","options":["has / eaten","have / eat","is / eating","was / eating"],"sentence":"She ___ never ___ sushi before.","subSkill":"present_perfect","explanation":"never表示截至现在的经历，主语She是第三人称单数，用has eaten（现在完成时）。","instruction":"选择正确的现在完成时形式：","correctIndex":0},{"type":"choice","options":["bakes","is baking","has baked","had baked"],"sentence":"By the time the guests arrived, Mary ___ the cake.","subSkill":"past_perfect","explanation":"By the time the guests arrived说明蛋糕已在客人到来前烤好，需要过去完成时had baked。","instruction":"选择正确答案：","correctIndex":3}],"2":[{"type":"choice","options":["Did / lose","Have / lost","Are / losing","Were / losing"],"sentence":"___ you ___ your keys? I can't find mine either.","subSkill":"present_perfect","explanation":"问题涉及过去的动作对现在的影响（现在还没找到），用现在完成时Have you lost。","instruction":"选择正确的时态：","correctIndex":1},{"type":"fill","sentence":"Be quiet! The baby (sleep) ___.","subSkill":"present_continuous","explanation":"Be quiet!暗示动作正在发生，主语The baby是单数，现在进行时为is sleeping。","instruction":"用括号内动词的现在进行时填空：","acceptableAnswers":["is sleeping"]},{"type":"choice","options":["take","took","was taking","have taken"],"sentence":"While I ___ a shower, someone knocked at the door.","subSkill":"past_continuous","explanation":"knocked是过去发生的动作，而洗澡是那时正在进行的背景动作，用过去进行时was taking。","instruction":"选择正确答案：","correctIndex":2},{"type":"fill","sentence":"She was tired because she (not sleep) ___ well the night before.","subSkill":"past_perfect","explanation":"睡眠不好发生在她感到疲倦之前，用过去完成时的否定形式hadn't slept。","instruction":"用括号内动词的过去完成时填空：","acceptableAnswers":["hadn't slept"]},{"type":"choice","options":["lived","lives","has lived","was living"],"sentence":"My brother ___ in London for five years. He loves it there.","subSkill":"present_perfect","explanation":"for five years与现在完成时连用，表示从过去持续到现在的状态，用has lived。","instruction":"选出正确句子：","correctIndex":2},{"type":"fill","sentence":"This time yesterday, we (drive) ___ to Beijing.","subSkill":"past_continuous","explanation":"This time yesterday表示过去某个时刻，主语we是复数，过去进行时为were driving。","instruction":"用括号内动词的过去进行时填空：","acceptableAnswers":["were driving"]},{"type":"choice","options":["take","were taking","have taken","had taken"],"sentence":"The students ___ a test when the fire alarm went off.","subSkill":"past_continuous","explanation":"考试是过去火警响起时正在进行的动作，用过去进行时were taking。","instruction":"选择正确答案：","correctIndex":1},{"type":"fill","sentence":"I (already finish) ___ my report. Can I go home now?","subSkill":"present_perfect","explanation":"动作已完成且与现在请求有关，用现在完成时have already finished。","instruction":"用括号内动词的现在完成时填空：","acceptableAnswers":["have already finished"]}],"3":[{"type":"fill","sentence":"By 10 o'clock this morning, the workers (already build) ___ three walls.","subSkill":"past_perfect","explanation":"By 10 o'clock this morning说明是在过去某时间点之前完成的，用过去完成时had already built。","instruction":"用括号内动词的适当时态填空：","acceptableAnswers":["had already built"]},{"type":"reorder","words":["been","has","She","France","to","never"],"subSkill":"present_perfect","explanation":"现在完成时结构：主语 + has/have + 副词 + 过去分词，never放在has和been之间。","instruction":"将单词排列成正确的句子：","correctSentence":"She has never been to France."},{"type":"fill","sentence":"When I called, she (cook) ___ dinner and the kids (do) ___ their homework.","subSkill":"past_continuous","explanation":"两个动作在我打电话时都在同时进行，都用过去进行时：单数was cooking，复数were doing。","instruction":"用括号内动词的适当时态填空：","acceptableAnswers":["was cooking","were doing"]},{"type":"reorder","words":["is","the","crying","why","baby"],"subSkill":"present_continuous","explanation":"现在进行时疑问句结构：疑问词 + be动词 + 主语 + 现在分词。","instruction":"将单词排列成正确的句子：","correctSentence":"Why is the baby crying?"},{"type":"fill","sentence":"I (meet) ___ Tom in 2019. We (be) ___ friends ever since.","subSkill":"tense_contrast","explanation":"in 2019是具体过去时间用一般过去时met；ever since表示从过去持续到现在用现在完成时have been。","instruction":"选择并填写正确时态（现在完成时或一般过去时）：","acceptableAnswers":["met","have been"]},{"type":"reorder","words":["had","the","left","film","already","when","we","arrived","started"],"subSkill":"past_perfect","explanation":"过去完成时表示在arrived之前已经发生的事：主语 + had + already + 过去分词 + when + 过去时从句。","instruction":"将单词排列成正确的句子：","correctSentence":"The film had already started when we arrived."},{"type":"fill","sentence":"Don't disturb him. He (work) ___ on this project for hours.","subSkill":"present_perfect","explanation":"动作从过去开始持续到现在还在进行，用现在完成进行时has been working（属于现在完成时的扩展）。","instruction":"用括号内动词的适当时态填空：","acceptableAnswers":["has been working"]},{"type":"reorder","words":["were","what","at","you","doing","midnight"],"subSkill":"past_continuous","explanation":"过去进行时疑问句：疑问词 + was/were + 主语 + 现在分词 + 时间状语。","instruction":"将单词排列成正确的句子：","correctSentence":"What were you doing at midnight?"}],"4":[{"type":"error","words":["She","have","lived","here","since","2010"],"subSkill":"present_perfect","correction":"has","errorIndex":1,"explanation":"主语She是第三人称单数，现在完成时应用has而不是have，正确形式为has lived。","instruction":"找出句中的错误并改正："},{"type":"fill","sentence":"When the teacher walked in, two students (argue) ___ and one (sleep) ___ at his desk.","subSkill":"past_continuous","explanation":"老师走进来时，这两个动作正在同时进行，都用过去进行时。复数主语用were arguing，单数主语用was sleeping。","instruction":"根据语境用正确时态填空：","acceptableAnswers":["were arguing","was sleeping"]},{"type":"choice","options":["check / realize","checked / realized","have checked / realized","was checking / have realized"],"sentence":"I ___ my phone and then ___ that I had 20 new messages.","subSkill":"tense_contrast","explanation":"两个动作按顺序发生在过去，都用一般过去时checked和realized，而非进行时或完成时。","instruction":"选出最恰当的句子（注意时态对比）：","correctIndex":1},{"type":"error","words":["He","was","sleeping","when","his","phone","has","rung"],"subSkill":"tense_contrast","correction":"had","errorIndex":6,"explanation":"此句需要描述过去某时已发生的事，应用had rung（过去完成时）或直接用rang（一般过去时），has rung（现在完成时）不符合过去语境。","instruction":"找出句中的错误并改正："},{"type":"fill","sentence":"By the end of last year, they (complete) ___ the building, which (stand) ___ empty for a decade.","subSkill":"past_perfect","explanation":"两个动作都发生在过去某时间点之前，用过去完成时had completed；空置持续的状态用过去完成进行时had been standing。","instruction":"用括号内动词的正确时态填空：","acceptableAnswers":["had completed","had been standing"]},{"type":"error","words":["I","am","knowing","her","for","ten","years"],"subSkill":"present_perfect","correction":"have known","errorIndex":1,"explanation":"know是状态动词，不用进行时。for ten years与现在完成时连用，正确形式为I have known her for ten years。","instruction":"找出句中的错误并改正："},{"type":"choice","options":["waited / arrived","had been waiting / arrived","were waiting / had arrived","have waited / arrives"],"sentence":"We ___ for the bus for 30 minutes before it finally ___.","subSkill":"tense_contrast","explanation":"等待是持续到另一过去动作发生的动作，用过去完成进行时had been waiting；公交车到来用一般过去时arrived。","instruction":"选择最正确的时态用法：","correctIndex":1},{"type":"error","words":["She","was","cook","dinner","when","I","arrived"],"subSkill":"past_continuous","correction":"cooking","errorIndex":2,"explanation":"过去进行时结构是was/were + 现在分词（动词-ing形式），cook应改为cooking。","instruction":"找出句中的错误并改正："}],"5":[{"type":"error","words":["By","the","time","Jack","arrives","we","had","finished","dinner"],"subSkill":"tense_contrast","correction":"arrived","errorIndex":4,"explanation":"By the time引导的从句若指过去，应用一般过去时arrived，而非一般现在时arrives；主句的过去完成时had finished与之搭配。","instruction":"找出并改正这段话中的时态错误："},{"type":"fill","sentence":"The scientist (work) ___ on the experiment all morning. She (not eat) ___ anything yet, and when her assistant (enter) ___ the lab, she (still stare) ___ at the data.","subSkill":"tense_contrast","explanation":"has been working表示上午持续到现在的动作；hasn't eaten表示尚未完成；entered是过去具体动作；was still staring是助手进入时正在进行的动作。","instruction":"综合运用时态，用括号内动词的正确形式填空：","acceptableAnswers":["has been working","hasn't eaten","entered","was still staring"]},{"type":"reorder","words":["had","she","realized","her","lost","had","she","wallet","that","when"],"subSkill":"past_perfect","explanation":"从句结构：When + 主语 + 过去时动词；主句中had lost是过去完成时，表示发现之前已经丢失。注意：这是一个从句，完整句需要主句。","instruction":"将单词排列成完整正确的句子：","correctSentence":"When she realized she had lost her wallet."},{"type":"choice","options":["will leave","am leaving","will have left","have left"],"sentence":"By the time you read this letter, I ___ to Canada. Please don't forget me.","subSkill":"tense_contrast","explanation":"By the time you read this表示未来某时刻，离开发生在那之前，用将来完成时will have left，表示届时已经完成的动作。","instruction":"选出最符合语境的选项（综合时态判断）：","correctIndex":2},{"type":"error","words":["While","they","had","discussed","the","plan,","someone","stole","their","bags"],"subSkill":"past_continuous","correction":"were","errorIndex":2,"explanation":"discuss是while从句中的背景动作，应用过去进行时were discussing，而非过去完成时had discussed。while通常引导过去进行时表示同时进行的背景动作。","instruction":"找出并改正句中所有时态错误（只选最主要的一个）："},{"type":"fill","sentence":"Mark told me that he (see) ___ that film before and he (not want) ___ to watch it again.","subSkill":"past_perfect","explanation":"间接引语中，看过电影发生在说话之前，用过去完成时had seen；didn't want是过去时与told保持一致。","instruction":"用动词的正确时态完成句子（注意时态逻辑）：","acceptableAnswers":["had seen","didn't want"]},{"type":"reorder","words":["just","have","for","I","the","waiting","been","an","hour","bus"],"subSkill":"present_perfect","explanation":"现在完成进行时结构：主语 + have/has + been + 现在分词，for an hour表示持续时长，整句表示一直等了一个小时（现在仍在等）。","instruction":"将单词排列成完整且时态正确的句子：","correctSentence":"I have been waiting for the bus for an hour."},{"type":"choice","options":["She was reading a book at 9 pm.","She had read the book before the exam.","She has read the book, so she can help you.","She reads books every evening."],"sentence":"Which sentence best describes a past action that affected the present situation?","subSkill":"present_perfect","explanation":"现在完成时（has read）表示过去的动作对现在产生影响——她读过这本书，所以现在能帮你。这是现在完成时的核心用法：过去动作与现在结果相关联。","instruction":"选出描述最恰当的句子（时态含义辨析）：","correctIndex":2}]},"mission":{"title":"My Amazing Journey","scenario":"想象你刚刚结束了一次难忘的旅行，现在正在用日记记录这次经历。请描述：旅途中你在做什么、你去过哪些地方、在到达某地之前已经发生了什么。尽量使用至少三种不同的时态。","scaffolds":[{"hint":"描述到达时的心情，用过去进行时和过去完成时","prefix":"When I arrived in","suffix":", I was feeling very excited because I had never been there before.","example":"When I arrived in Tokyo, I was feeling very excited because I had never been there before.","grammarCheck":"past_perfect"},{"hint":"用过去进行时描述当时正在做的事，用过去完成时描述之前发生的情况","prefix":"While I was","suffix":", I suddenly realized that I had already forgotten to bring my camera.","example":"While I was exploring the market, I suddenly realized that I had already forgotten to bring my camera.","grammarCheck":"past_continuous"},{"hint":"用现在完成时总结旅行中已完成的经历","prefix":"Now I have returned home. I have","suffix":"and I will never forget this amazing trip.","example":"Now I have returned home. I have visited ten cities and made many new friends, and I will never forget this amazing trip.","grammarCheck":"present_perfect"}],"description":"运用本单元学习的进行时和完成时，写一段关于你（或一个虚构角色）旅行经历的短文。描述旅途中正在发生的事情、已经完成的经历，以及在某个时刻之前发生的事。","grammarType":"tense_contrast"},"discover":{"tip":"记住四种时态的核心区别：现在进行时（is/are + doing）表示现在正在发生；过去进行时（was/were + doing）表示过去某时正在发生；现在完成时（have/has + done）表示过去动作对现在的影响；过去完成时（had + done）表示过去某时之前已完成的动作。","story":{"text":"It is 3 o'clock in the afternoon. Emma is studying at the library. She has been sitting there for two hours. When her friend Leo arrived at noon, Emma was already reading her third book. By the time Leo sat down, Emma had finished her homework and was starting a new chapter. Leo looked around. Some students were whispering quietly in the corner. Others had fallen asleep over their textbooks. Emma looked up and smiled. 'I have read five books this week,' she said proudly. Leo was amazed. He had never read so many books in one week. 'I was planning to watch TV today,' Leo admitted, 'but now I have changed my mind.' He pulled out his notebook and began to write. Outside, the rain was falling softly. The librarian had already closed the windows before the storm arrived. Now everything was quiet and warm inside. Both Emma and Leo were working hard, and the afternoon was passing quickly around them.","title":"A Busy Day at the Library","highlights":["is studying","has been sitting","was already reading","had finished","were whispering","had fallen","have read","had never read","was planning","have changed","was falling","had closed"]},"questions":[{"options":["She was sleeping.","She was reading a book.","She was writing homework.","She was talking to the librarian."],"question":"When Leo arrived, what was Emma doing?","explanation":"文中说Leo到达时，Emma正在读她的第三本书（was already reading her third book），这是过去进行时，表示过去某时刻正在进行的动作。","correctIndex":1},{"options":["She was starting a new chapter.","Emma is studying at the library.","I have read five books this week.","The rain was falling softly."],"question":"Which sentence uses the present perfect tense?","explanation":"'I have read five books this week' 使用了现在完成时（have + 过去分词），表示截至现在已经完成的动作，与本周内的经历相关。","correctIndex":2},{"options":["She had opened the doors.","She had closed the windows.","She had turned off the lights.","She had left the library."],"question":"What had the librarian done before the storm arrived?","explanation":"文中说'The librarian had already closed the windows before the storm arrived'，这是过去完成时（had + 过去分词），表示在过去某个时间点之前已经完成的动作。","correctIndex":1}]}},"3":{"levels":{"1":[{"type":"choice","options":["is","was","were","be"],"sentence":"The letter ___ written by Mary yesterday.","subSkill":"passive_formation","explanation":"yesterday 表明这是过去时，被动语态过去时用 'was/were + 过去分词'。主语 'the letter' 是单数，所以用 'was'。","instruction":"选择正确的被动语态句子。","correctIndex":1},{"type":"choice","options":["is","are","was","been"],"sentence":"English ___ spoken in many countries.","subSkill":"passive_formation","explanation":"描述现在普遍存在的事实用一般现在时被动语态。'English' 是单数不可数名词，用 'is spoken'。","instruction":"选择正确的被动语态形式。","correctIndex":0},{"type":"choice","options":["cleans","is cleaned","are cleaned","cleaning"],"sentence":"The windows ___ cleaned every week.","subSkill":"passive_formation","explanation":"'Windows' 是复数名词，一般现在时被动语态用 'are + 过去分词'，所以答案是 'are cleaned'。","instruction":"选出正确的被动语态句子。","correctIndex":2},{"type":"choice","options":["is","are","was","were"],"sentence":"A new hospital ___ built in our city last year.","subSkill":"passive_tense_variations","explanation":"'last year' 表明用过去时。'a new hospital' 是单数，所以被动语态用 'was built'。","instruction":"选择正确答案完成句子。","correctIndex":2},{"type":"choice","options":["is","does","has","did"],"sentence":"The cake ___ eaten by the children.","subSkill":"passive_formation","explanation":"被动语态结构为 'be + 过去分词'。这里表示现在的状态，用 'is eaten'。注意 'eaten' 是 'eat' 的过去分词。","instruction":"哪个选项正确描述了被动语态的结构？","correctIndex":0},{"type":"choice","options":["will announce","will be announced","are announced","were announced"],"sentence":"The results ___ announced tomorrow.","subSkill":"passive_tense_variations","explanation":"'tomorrow' 表示将来时。将来时被动语态结构为 'will be + 过去分词'，所以答案是 'will be announced'。","instruction":"选择正确的被动语态。","correctIndex":1},{"type":"choice","options":["grows","is grown","is grow","are grown"],"sentence":"Rice ___ grown in southern China.","subSkill":"passive_formation","explanation":"描述一般事实用一般现在时。'Rice' 是不可数单数名词，被动语态用 'is grown'。注意不能用 'is grow'，必须用过去分词 'grown'。","instruction":"选出正确的被动语态句子。","correctIndex":1},{"type":"choice","options":["returned","was returned","were returned","are return"],"sentence":"The books ___ returned to the library by the students.","subSkill":"passive_formation","explanation":"'books' 是复数，动作发生在过去（结合语境），所以用 'were returned'。'are return' 错误，因为必须用过去分词 'returned'。","instruction":"选择正确的句子。","correctIndex":2}],"2":[{"type":"choice","options":["designed","was designed","is designed","has designed"],"sentence":"This bridge ___ by a famous engineer in 1890.","subSkill":"passive_tense_variations","explanation":"'in 1890' 表明是过去时。被动语态过去时用 'was/were + 过去分词'。主语 'this bridge' 单数用 'was designed'。","instruction":"选择正确的被动语态完成句子。","correctIndex":1},{"type":"fill","sentence":"The data (collect) ___ by researchers every month.","subSkill":"passive_in_academic_writing","explanation":"'data' 在此处视为单数（学术写作中常见），一般现在时被动语态用 'is + 过去分词' → 'is collected'。","instruction":"用括号中动词的正确被动语态形式填空（一般现在时）。","acceptableAnswers":["is collected"]},{"type":"choice","options":["was","is","were","had"],"sentence":"The experiment ___ conducted three times before a conclusion was reached.","subSkill":"passive_in_academic_writing","explanation":"句子描述过去的实验，'experiment' 是单数，过去时被动语态用 'was conducted'。","instruction":"判断哪个句子是正确的被动语态。","correctIndex":0},{"type":"fill","sentence":"The survey results (publish) ___ next month.","subSkill":"passive_tense_variations","explanation":"'next month' 表示将来时，将来时被动语态结构为 'will be + 过去分词' → 'will be published'。","instruction":"用括号中动词的正确被动语态形式填空（一般将来时）。","acceptableAnswers":["will be published"]},{"type":"fill","sentence":"Several new species (discover) ___ in this region.","subSkill":"passive_tense_variations","explanation":"现在完成时被动语态结构：'have/has been + 过去分词'。'species' 这里是复数，用 'have been discovered'。","instruction":"将括号内的动词变为正确的被动语态（现在完成时）填入空白处。","acceptableAnswers":["have been discovered"]},{"type":"choice","options":["we selected","were selected","selected","selecting"],"sentence":"In this study, 200 participants ___.","subSkill":"passive_in_academic_writing","explanation":"在学术写作中，被动语态 'were selected' 更正式客观，避免使用第一人称 'we'，符合雅思学术写作规范。","instruction":"选择最适合学术写作的被动语态句子。","correctIndex":1},{"type":"fill","sentence":"The ancient temple (build) ___ over two thousand years ago.","subSkill":"passive_tense_variations","explanation":"'over two thousand years ago' 表示过去时，'temple' 是单数，过去时被动语态用 'was built'。'build' 的过去分词是 'built'。","instruction":"用动词的正确被动语态形式（过去时）填空。","acceptableAnswers":["was built"]},{"type":"fill","sentence":"Patients (treat) ___ with a new medication in this hospital.","subSkill":"passive_in_academic_writing","explanation":"'Patients' 是复数，一般现在时被动语态用 'are + 过去分词' → 'are treated'。这种表达在医学报告中十分常见。","instruction":"用括号中动词的正确被动语态形式（一般现在时）填空。","acceptableAnswers":["are treated"]}],"3":[{"type":"fill","sentence":"A new policy (develop) ___ by the government at the moment.","subSkill":"passive_tense_variations","explanation":"现在进行时被动语态结构：'is/are being + 过去分词'。'policy' 单数用 'is being developed'，表示目前正在进行的被动动作。","instruction":"用动词的正确被动语态（现在进行时）填空。","acceptableAnswers":["is being developed"]},{"type":"reorder","words":["the","report","written","was","by","the","team"],"subSkill":"passive_formation","explanation":"被动语态结构：主语（the report）+ was + 过去分词（written）+ by + 施动者（the team）。过去时单数主语用 'was'。","instruction":"将以下单词排列成正确的被动语态句子。","correctSentence":"The report was written by the team."},{"type":"fill","sentence":"By the time the inspector arrived, all the evidence (remove) ___.","subSkill":"passive_tense_variations","explanation":"过去完成时被动语态结构：'had been + 过去分词'。表示在另一个过去动作（inspector arrived）之前已经完成的被动动作。","instruction":"用动词的正确被动语态（过去完成时）填空。","acceptableAnswers":["had been removed"]},{"type":"reorder","words":["It","estimated","is","that","40%","of","species","are","threatened"],"subSkill":"passive_in_academic_writing","explanation":"'It is + 过去分词 + that从句' 是雅思学术写作中非常常见的被动结构，用于客观陈述数据或研究结论，避免主观判断。","instruction":"将单词排列成正确的学术被动语态句子。","correctSentence":"It is estimated that 40% of species are threatened."},{"type":"fill","sentence":"Scientists have discovered a new planet. → A new planet ___ by scientists.","subSkill":"passive_vs_active","explanation":"主动句是现在完成时（have discovered），被动句对应结构为 'has/have been + 过去分词'。主语 'a new planet' 是单数，用 'has been discovered'。","instruction":"主动句变被动句：将以下句子改写为被动语态（保留时态）。","acceptableAnswers":["has been discovered"]},{"type":"reorder","words":["The","bridge","will","repaired","be","next","year"],"subSkill":"passive_tense_variations","explanation":"将来时被动语态结构：主语 + will be + 过去分词。注意 'will be' 不能写成 'will is'，'be' 在这里是固定搭配。","instruction":"将单词排列成正确的将来时被动语态句子。","correctSentence":"The bridge will be repaired next year."},{"type":"fill","sentence":"When we arrived, the road (repair) ___.","subSkill":"passive_tense_variations","explanation":"过去进行时被动语态结构：'was/were being + 过去分词'。'road' 是单数，用 'was being repaired'，表示过去某时刻正在进行的被动动作。","instruction":"用动词的正确被动语态填空（过去进行时）。","acceptableAnswers":["was being repaired"]},{"type":"reorder","words":["have","measures","introduced","Several","been","new"],"subSkill":"passive_in_academic_writing","explanation":"现在完成时被动语态：主语（Several new measures）+ have been + 过去分词（introduced）。这种结构在学术报告和新闻中非常普遍。","instruction":"将单词排列成正确的现在完成时被动语态句子。","correctSentence":"Several new measures have been introduced."}],"4":[{"type":"error","words":["The","report","is","write","by","the","committee"],"subSkill":"passive_formation","correction":"written","errorIndex":3,"explanation":"被动语态结构必须用 'be + 过去分词'。'write' 是原形，应改为过去分词 'written'。正确句子：'The report is written by the committee.'","instruction":"找出句子中的错误并改正。"},{"type":"fill","sentence":"Workers produce steel here. → Steel ___ here by ___.","subSkill":"passive_vs_active","explanation":"一般现在时主动句变被动：主动句的宾语（steel）变主语，动词用 'is produced'，原主语（workers）放在 'by' 之后。","instruction":"主动句变被动句，用正确时态填写两个空格。","acceptableAnswers":["is produced","workers"]},{"type":"choice","options":["We found that pollution levels were increased.","The findings indicate that pollution levels have been increased.","It has been found that pollution levels have increased.","Pollution levels are being increased, as found."],"sentence":"The findings show that pollution levels have increased. / ___","subSkill":"passive_in_academic_writing","explanation":"'It has been found that...' 是标准的学术被动表达，客观陈述研究发现，避免第一人称。选项B中 'have been increased' 用法不当（increase 通常是不及物动词，不用被动）。","instruction":"在学术写作语境中，哪个句子更合适？","correctIndex":2},{"type":"error","words":["The","samples","was","analyzed","in","the","laboratory"],"subSkill":"passive_formation","correction":"were","errorIndex":2,"explanation":"'samples' 是复数名词，过去时被动语态应用 'were'，而非单数形式 'was'。正确句子：'The samples were analyzed in the laboratory.'","instruction":"找出被动语态中的错误并改正。"},{"type":"fill","sentence":"Significant progress (make) ___ in the field of renewable energy over the past decade.","subSkill":"passive_in_academic_writing","explanation":"现在完成时被动语态：'has/have been + 过去分词'。'progress' 是不可数单数名词，用 'has been made'。'over the past decade' 是现在完成时的典型时间标志。","instruction":"用括号内动词的正确被动语态（现在完成时）填空，使句子符合学术写作规范。","acceptableAnswers":["has been made"]},{"type":"error","words":["It","is","believed","that","the","climate","is","effect","by","human","activity"],"subSkill":"passive_vs_active","correction":"affected","errorIndex":7,"explanation":"'is effect' 错误，'effect' 是名词，这里需要动词 'affect' 的过去分词 'affected'。正确结构：'is affected by'（被动语态）。","instruction":"找出句子中的语法错误并改正。"},{"type":"choice","options":["New laws are introducing by the government.","New laws have been introduced by the government.","New laws were introduced by the government.","New laws will be introduced by the government."],"sentence":"The government has introduced new laws.","subSkill":"passive_vs_active","explanation":"主动句用了现在完成时 'has introduced'，对应的被动语态应为 'have been introduced'（现在完成时被动）。选项C是过去时被动，时态不符。","instruction":"选出主动句与被动句含义对应正确的选项。","correctIndex":1},{"type":"fill","sentence":"They are testing the product now, and they will release it next week. → The product ___ now, and it ___ next week.","subSkill":"passive_tense_variations","explanation":"第一空：现在进行时被动 'is being tested'；第二空：将来时被动 'will be released'。注意两个空对应不同时态的被动结构。","instruction":"将句子改写为被动语态，用两处被动结构填空。","acceptableAnswers":["is being tested","will be released"]}],"5":[{"type":"fill","sentence":"These results (must / verify) ___ before they are published.","subSkill":"passive_in_academic_writing","explanation":"情态动词被动语态结构：'情态动词 + be + 过去分词'。'must be verified' 表示必须被核实，是学术写作中表达必要性的常见被动形式。","instruction":"用括号内动词的正确被动语态填空（情态动词被动）。","acceptableAnswers":["must be verified"]},{"type":"reorder","words":["It","widely","is","believed","that","urbanisation","has","been","accelerated","by","industrialisation"],"subSkill":"passive_in_academic_writing","explanation":"'It is widely believed that...' 结合 'has been accelerated'（现在完成时被动）是雅思学术写作的高分句型，能体现客观性和复杂句式能力。","instruction":"将单词排列成完整正确的学术被动语态句子。","correctSentence":"It is widely believed that urbanisation has been accelerated by industrialisation."},{"type":"error","words":["The","hypothesis","has","been","support","by","three","independent","studies"],"subSkill":"passive_tense_variations","correction":"supported","errorIndex":4,"explanation":"现在完成时被动语态需要 'have/has been + 过去分词'。'support' 是动词原形，应改为过去分词 'supported'。","instruction":"找出学术句子中被动语态的错误并改正。"},{"type":"fill","sentence":"Researchers had already collected the data when the earthquake struck. → The data ___ already ___ when the earthquake struck.","subSkill":"passive_tense_variations","explanation":"过去完成时被动结构：'had been + 过去分词'。注意 'already' 放在 'had' 和 'been' 之间，表示在地震发生前数据已经被收集完毕。","instruction":"将以下主动语态句子改写为被动语态（保持时态和语义不变），填入正确形式。","acceptableAnswers":["had","been collected"]},{"type":"choice","options":["A sharp increase in oil production can be seen in the graph.","We can see that oil production sharply increased.","Oil production was being sharply increased.","The graph is seen a sharp increase in oil production."],"sentence":"The graph shows changes in oil production between 2000 and 2020.","subSkill":"passive_vs_active","explanation":"'can be seen' 是情态动词被动语态，客观描述图表，符合学术写作规范。选项B使用第一人称，不够正式；选项C时态和语义均有误；选项D结构完全错误。","instruction":"选出最适合雅思学术写作语境的句子（描述图表趋势）。","correctIndex":0},{"type":"reorder","words":["have","The","long-term","ignored","by","effects","been","policymakers"],"subSkill":"passive_vs_active","explanation":"现在完成时被动语态：主语（The long-term effects）+ have been + 过去分词（ignored）+ by + 施动者（policymakers）。此结构在议论文和报告中频繁出现。","instruction":"排列单词，构成含有 'by' 短语的完整被动语态句子。","correctSentence":"The long-term effects have been ignored by policymakers."},{"type":"error","words":["The","participants","are","been","asked","to","complete","a","questionnaire"],"subSkill":"passive_formation","correction":"being","errorIndex":3,"explanation":"现在进行时被动语态结构应为 'are being + 过去分词'。'been' 是过去分词，不能接在 'are' 后直接构成进行时被动；应改为 'being'，即 'are being asked'。","instruction":"找出句子中不恰当使用主动语态（应使用被动）或被动语态错误，并改正关键词。"},{"type":"fill","sentence":"According to the findings, more resources (should / allocate) ___ to climate research.","subSkill":"passive_in_academic_writing","explanation":"情态动词被动语态：'should be + 过去分词'。'should be allocated' 表示应该被分配，是雅思写作Task 2中提出建议的正式学术表达。","instruction":"用括号内的词语构成正确的被动语态（should 情态动词），使句子符合学术写作要求。","acceptableAnswers":["should be allocated"]}]},"mission":{"title":"Describe a Manufacturing Process","scenario":"你正在为一份雅思Task 1写作练习准备内容。图表展示了塑料瓶的生产过程，共包含以下环节：原料采集 → 加热熔化 → 模具成型 → 冷却 → 质量检测 → 包装出货。请写一段80-120词的英文描述，重点使用被动语态，体现不同时态变化，并保持学术写作风格。","scaffolds":[{"hint":"用一般现在时被动语态描述原料来源（extract）","prefix":"The process of making plastic bottles involves several stages. First, raw materials","suffix":"from natural gas or petroleum.","example":"First, raw materials are extracted from natural gas or petroleum.","grammarCheck":"passive_formation"},{"hint":"用一般现在时被动语态描述加热过程（heat）","prefix":"Once the materials have been collected, they","suffix":"at extremely high temperatures to form a liquid state.","example":"Once the materials have been collected, they are heated at extremely high temperatures to form a liquid state.","grammarCheck":"passive_tense_variations"},{"hint":"用一般现在时被动语态描述检测环节（inspect），并注意 'before' 引导的时间状语从句中也使用被动","prefix":"Finally, each bottle","suffix":"for quality before it is packaged and shipped to consumers.","example":"Finally, each bottle is inspected for quality before it is packaged and shipped to consumers.","grammarCheck":"passive_in_academic_writing"}],"description":"使用被动语态描述一个制造或生产流程。想象你是一名工业报告撰写人，需要客观介绍产品从原材料到成品的全过程。","grammarType":"passive_in_academic_writing"},"discover":{"tip":"被动语态的核心公式：be动词（随时态变化）+ 过去分词（past participle）。主动句变被动句时，原来的宾语变成新的主语，原来的主语可以用 'by + 施动者' 表示，也可以省略。在学术写作和流程描述中，被动语态使语言更客观、更正式。","story":{"text":"Every morning, millions of cups of coffee are enjoyed by people around the world. But have you ever wondered how coffee is made? First, coffee beans are grown in tropical regions such as Brazil and Ethiopia. After they are harvested by farmers, the beans are carefully sorted and dried in the sun. Then, the dried beans are shipped to processing plants in different countries. At the plant, the beans are roasted at high temperatures to develop their rich flavor. Once they have been roasted, the beans are ground into a fine powder. Finally, hot water is passed through the ground coffee, and a fresh cup is produced. The entire process is controlled by both machines and skilled workers. It is estimated that over two billion cups of coffee are consumed every single day. The next time you drink a cup of coffee, remember that it has been transformed by many hands and many processes before it reached you.","title":"How Coffee Is Made","highlights":["are enjoyed","is made","are grown","are harvested","are shipped","are roasted","have been roasted","are ground","is passed","is produced","is controlled","is estimated","are consumed","has been transformed"]},"questions":[{"options":["Coffee grows in Brazil.","Coffee is grown in Brazil.","Coffee growing in Brazil.","Coffee was grow in Brazil."],"question":"Which sentence uses the passive voice correctly?","explanation":"被动语态的基本结构是 'be动词 + 过去分词'。选项B 'is grown' 正确使用了 be + past participle 结构，表示咖啡被种植在巴西。选项A是主动语态，选项C缺少be动词，选项D的过去分词形式错误。","correctIndex":1},{"options":["The beans are being roasted right now.","The beans were roasted and the action is relevant to the present.","The beans will be roasted in the future.","Someone roasted the beans a long time ago with no connection to now."],"question":"In the story, what does 'have been roasted' indicate?","explanation":"'Have been roasted' 是现在完成时被动语态（have/has been + 过去分词），表示豆子已经被烘焙完毕，且这个动作与现在有关联——烘焙完成之后才能进行下一步。这体现了完成时被动语态的典型用法。","correctIndex":1},{"options":["Because the writer does not know who performs the actions.","Because passive voice is easier to write than active voice.","Because the focus is on the process and the coffee, not on who does each action.","Because passive voice is only used in stories about food."],"question":"Why does the story use passive voice so frequently?","explanation":"在描述工艺流程或科学过程时，被动语态非常常见，因为重点在于'发生了什么'（咖啡是如何被制作的），而不是'谁做了这件事'。这也是雅思写作Task 1流程图描述中被动语态的核心用途。","correctIndex":2}]}},"4":{"levels":{"1":[{"type":"choice","options":["must","could","should","might"],"sentence":"When she was five, she ___ read simple books.","subSkill":"ability_modals","explanation":"'Could' 表示过去的能力，意思是她五岁时能够阅读简单的书籍。","instruction":"选择正确的情态动词完成句子（表示能力）。","correctIndex":1},{"type":"choice","options":["must","can","should","might"],"sentence":"You look tired. You ___ get some rest.","subSkill":"advice_modals","explanation":"'Should' 用来给出建议，表示你应该去休息一下。","instruction":"选择正确的情态动词（表示建议）。","correctIndex":2},{"type":"choice","options":["might","could","should","must"],"sentence":"Students ___ wear a uniform at this school.","subSkill":"obligation_modals","explanation":"'Must' 表示规定或强制性要求，学生必须穿校服。","instruction":"选择正确的情态动词（表示义务或必要性）。","correctIndex":3},{"type":"choice","options":["must","might","should","can"],"sentence":"It ___ rain this afternoon. The sky looks very dark.","subSkill":"possibility_modals","explanation":"'Might' 表示某事有可能发生，但不确定，这里说今天下午可能会下雨。","instruction":"选择正确的情态动词（表示可能性）。","correctIndex":1},{"type":"choice","options":["must","can","should","might"],"sentence":"He has studied hard, so now he ___ speak French quite well.","subSkill":"ability_modals","explanation":"'Can' 表示现在具备的能力，他努力学习后现在能说法语了。","instruction":"选择正确的选项（表示现在的能力）。","correctIndex":1},{"type":"choice","options":["should","must not","might not","could not"],"sentence":"You ___ use your phone during the exam.","subSkill":"obligation_modals","explanation":"'Must not' 表示禁止，意思是考试期间不允许使用手机。","instruction":"选择正确的情态动词（表示禁止）。","correctIndex":1},{"type":"choice","options":["might","could","must","should"],"sentence":"She has worked for 12 hours. She ___ be exhausted.","subSkill":"possibility_modals","explanation":"'Must' 在这里表示基于证据的强烈推测，她工作了12小时，一定非常疲惫。","instruction":"选择正确的情态动词（表示推测——几乎肯定）。","correctIndex":2},{"type":"choice","options":["must not","could not","should","might"],"sentence":"You ___ eat more vegetables. They are good for your health.","subSkill":"advice_modals","explanation":"'Should' 表示给出建议，意思是你应该多吃蔬菜，对健康有好处。","instruction":"选择正确的情态动词（表示建议或应当）。","correctIndex":2}],"2":[{"type":"choice","options":["could","was able to","must","should"],"sentence":"After months of training, he ___ finally run a full marathon.","subSkill":"ability_modals","explanation":"'Was able to' 常用于表示在特定场合成功完成了某事，指他终于成功跑完了一场马拉松。","instruction":"选择正确的情态动词（表示过去的能力）。","correctIndex":1},{"type":"fill","sentence":"You (ought to) ___ apologize to her for what you said.","subSkill":"advice_modals","explanation":"'Ought to' 与 'should' 意思相近，表示建议或道义上应当做某事，形式上不变。","instruction":"用括号中情态动词的正确形式填空（表示建议）。","acceptableAnswers":["ought to"]},{"type":"choice","options":["must","may","should","had to"],"sentence":"I'm not sure where Tom is. He ___ be at the library.","subSkill":"possibility_modals","explanation":"'May' 表示较弱的可能性，说明说话者不确定 Tom 的位置，他可能在图书馆。","instruction":"选择正确的选项（表示弱可能性）。","correctIndex":1},{"type":"fill","sentence":"She (have to) ___ leave early because her train departs at 6 a.m.","subSkill":"obligation_modals","explanation":"当主语是第三人称单数时，'have to' 变为 'has to'，表示客观上的必要性。","instruction":"用情态动词 'have to' 的正确形式填空（表示必要性）。","acceptableAnswers":["has to"]},{"type":"choice","options":["didn't have to","must not","couldn't","shouldn't"],"sentence":"The meeting was cancelled, so we ___ prepare any slides.","subSkill":"obligation_modals","explanation":"'Didn't have to' 表示过去没有必要做某事，会议取消了所以不需要准备幻灯片。注意与 'must not'（禁止）的区别。","instruction":"选择正确答案（表示过去没有必要做某事）。","correctIndex":0},{"type":"fill","sentence":"I ___ swim very well, but I hurt my arm last week, so now I ___ barely move it.","subSkill":"ability_modals","explanation":"第一空表示现在的能力用 'can'；第二空在 'now' 的语境下也用 'can'，表示现在（受伤后）的状态。","instruction":"根据语境，用 'can' 或 'could' 填入正确形式。","acceptableAnswers":["can","can"]},{"type":"choice","options":["Must","Should","Could","Might"],"sentence":"___ you please pass me the salt?","subSkill":"ability_modals","explanation":"'Could you please...' 是一种礼貌的请求方式，比 'Can you' 更正式客气。","instruction":"选择最合适的情态动词（礼貌请求）。","correctIndex":2},{"type":"fill","sentence":"The lights are all off and the car is gone. They ___ be at home.","subSkill":"possibility_modals","explanation":"'Can't be' 用于否定推测，表示根据证据几乎可以肯定某事不是真的——灯关了、车没了，他们肯定不在家。","instruction":"用情态动词填空，表示根据证据推测（几乎肯定）。","acceptableAnswers":["can't"]}],"3":[{"type":"fill","sentence":"She didn't answer the phone. She (must / go out) ___ ___.","subSkill":"modal_perfect_forms","explanation":"'Must have + 过去分词' 表示对过去事情的强烈推测——她没接电话，一定是出去了。","instruction":"用情态完成时填空（表示对过去情况的推测）。","acceptableAnswers":["must have","gone out"]},{"type":"reorder","words":["should","before","You","more","sleep","the","exam","get"],"subSkill":"advice_modals","explanation":"'Should + 动词原形' 表示建议，句子结构为：主语 + should + 动词原形 + 其他成分。","instruction":"将单词排列成正确的句子（使用情态动词表示建议）。","correctSentence":"You should get more sleep before the exam."},{"type":"fill","sentence":"I feel sick now. I (should / not eat) ___ ___ so much cake.","subSkill":"modal_perfect_forms","explanation":"'Shouldn't have + 过去分词' 表示过去不应该做但做了的事，带有遗憾或后悔的语气。","instruction":"用情态完成时填空（表示对过去行为的遗憾）。","acceptableAnswers":["shouldn't have","eaten"]},{"type":"reorder","words":["able","wasn't","He","to","the","solve","problem"],"subSkill":"ability_modals","explanation":"'Was/were able to' 表示过去的能力，否定形式为 'wasn't/weren't able to'。","instruction":"将单词排列成正确的句子（表示过去的能力）。","correctSentence":"He wasn't able to solve the problem."},{"type":"fill","sentence":"When I was a child, I (have to) ___ go to bed at 8 o'clock every night.","subSkill":"obligation_modals","explanation":"'Had to' 是 'have to' 的过去式，表示过去的义务或必要性，那时候每晚必须8点睡觉。","instruction":"用情态动词填空，表示过去的义务（现在不再适用）。","acceptableAnswers":["had to"]},{"type":"reorder","words":["might","There","be","a","mistake","have","in","report","the"],"subSkill":"modal_perfect_forms","explanation":"'Might have been' 是情态完成时的一种，表示过去某事有可能发生——报告中可能有错误。","instruction":"将单词排列成正确的句子（表示可能性）。","correctSentence":"There might have been a mistake in the report."},{"type":"fill","sentence":"Visitors ___ take photographs inside the museum. It is strictly forbidden.","subSkill":"obligation_modals","explanation":"'Must not / cannot' 都可以表示规定上的禁止，博物馆内严格禁止拍照。","instruction":"用合适的情态动词填空，表示规定上的禁止。","acceptableAnswers":["must not","mustn't","cannot","can't"]},{"type":"reorder","words":["have","left","She","could","her","keys","at","office","the"],"subSkill":"modal_perfect_forms","explanation":"'Could have + 过去分词' 表示对过去可能发生的事情的推测，她钥匙可能是落在办公室了。","instruction":"将单词排列成正确的句子（情态完成时表示推测）。","correctSentence":"She could have left her keys at the office."}],"4":[{"type":"choice","options":["must","could","should","can"],"sentence":"The roads are completely blocked. The journey ___ take several hours longer than planned.","subSkill":"possibility_modals","explanation":"'Could' 在这里表示一种可能但不确定的预测，道路堵塞，行程可能会比计划多花几个小时。","instruction":"选择最能体现句子含义的情态动词（区分推测强度）。","correctIndex":1},{"type":"error","words":["He","must","forgotten","to","lock","the","door"],"subSkill":"modal_perfect_forms","correction":"must have","errorIndex":1,"explanation":"表示对过去情况的推测，情态动词后需加 'have'，正确形式为 'must have forgotten'。","instruction":"找出句中的错误并改正（情态完成时）。"},{"type":"fill","sentence":"You (could / warn) ___ ___ me earlier! Now it's too late to change the plan.","subSkill":"modal_perfect_forms","explanation":"'Could have + 过去分词' 表示过去本来有机会做某事但没有做，带有责备的语气。","instruction":"用情态完成时填空（表示过去本可以做但没做）。","acceptableAnswers":["could have","warned"]},{"type":"error","words":["You","don't","must","park","here.","It's","illegal."],"subSkill":"obligation_modals","correction":"must not","errorIndex":2,"explanation":"'Must not' 表示禁止，不能用 'don't must' 这种形式，情态动词本身已经是助动词，前面不加 do/don't。","instruction":"找出并改正句中情态动词的使用错误。"},{"type":"fill","sentence":"This painting looks brand new. It ___ be 500 years old.","subSkill":"possibility_modals","explanation":"'Can't / cannot be' 表示根据证据强烈否定某种可能性，画看起来全新，不可能有500年历史。","instruction":"用情态动词填空，表示基于证据的否定推测。","acceptableAnswers":["can't","cannot"]},{"type":"choice","options":["must not","should not","don't have to","cannot"],"sentence":"The entry is free, so you ___ buy a ticket.","subSkill":"obligation_modals","explanation":"'Don't have to' 表示没有必要，门票免费所以不需要买票；'must not' 表示禁止，意思完全不同。","instruction":"选择最恰当的选项（区分 'must not' 和 'don't have to'）。","correctIndex":2},{"type":"error","words":["She","should","to","practice","more","often"],"subSkill":"advice_modals","correction":"（删除 to）","errorIndex":2,"explanation":"情态动词（如 should, must, can 等）后面直接接动词原形，不加 'to'，正确形式为 'should practice'。","instruction":"找出句中的错误并改正（情态动词后接动词形式）。"},{"type":"fill","sentence":"Nobody saw him leave, but his coat and bag are gone. He (must / leave) ___ ___ while everyone was in the meeting.","subSkill":"modal_perfect_forms","explanation":"'Must have + 过去分词' 表示对过去事件的强烈推测，根据证据判断他一定是在开会时离开的。","instruction":"结合语境，选用适当情态动词填空（表示过去强烈推测）。","acceptableAnswers":["must have","left"]}],"5":[{"type":"error","words":["The","team","should","have","prepare","better","for","the","presentation"],"subSkill":"modal_perfect_forms","correction":"prepared","errorIndex":4,"explanation":"'Should have' 之后必须接过去分词，'prepare' 是动词原形，应改为 'prepared'。正确句子：The team should have prepared better for the presentation.","instruction":"找出并改正这句话中情态动词的错误（情态完成时）。"},{"type":"fill","sentence":"With proper funding, the scientists (might / discover) ___ ___ a cure much sooner.","subSkill":"modal_perfect_forms","explanation":"'Might have + 过去分词' 表示过去本可能发生但没发生的事，如果当时有资金支持，科学家可能早就发现了疗法。","instruction":"用适当的情态动词填空，表示过去可能发生但未发生的情况（带有遗憾意味）。","acceptableAnswers":["might have","discovered"]},{"type":"reorder","words":["have","ought","to","They","informed","the","authorities","immediately"],"subSkill":"modal_perfect_forms","explanation":"'Ought to have + 过去分词' 与 'should have + 过去分词' 类似，表示过去本应该做某事但没做，带有批评含义。","instruction":"将以下单词排列成一个语法正确、意思完整的句子（情态完成时，表示对过去的批评）。","correctSentence":"They ought to have informed the authorities immediately."},{"type":"choice","options":["must / could","may / might","should / must","could / can"],"sentence":"A: 'Why isn't Anna at the meeting?' B: 'I'm not sure. She ___ have missed the bus, or she ___ just have forgotten about it.'","subSkill":"modal_perfect_forms","explanation":"'May have' 和 'might have' 都表示对过去情况的不确定推测，两者都合适且强度相当，符合说话者表示不确定的语境。","instruction":"选择最恰当的选项，完成这段对话（区分情态动词的细微差别）。","correctIndex":1},{"type":"fill","sentence":"The ancient ruins ___ have been built over 2,000 years ago, but no one knows for certain.","subSkill":"modal_perfect_forms","explanation":"表示对过去可能性的推测，可用 'could / may / might have been built'，此处为情态完成时的被动语态。","instruction":"用合适的情态动词填空，注意语境中的被动结构。","acceptableAnswers":["could","may","might"]},{"type":"error","words":["Despite","the","difficulty,","she","could","finish","the","race","yesterday"],"subSkill":"ability_modals","correction":"was able to","errorIndex":4,"explanation":"描述在特定场合（昨天）成功完成的具体事件时，应用 'was able to' 而不是 'could'。'Could' 通常表示一般性的过去能力，不用于描述某次具体的成功。","instruction":"找出句子中的错误并改正（能力情态动词的用法）。"},{"type":"reorder","words":["must","The","reported","be","accident","to","police","the","immediately"],"subSkill":"obligation_modals","explanation":"情态动词 + 被动语态结构：情态动词 + be + 过去分词。表示事故必须立即上报给警方。","instruction":"将单词排列成正确的句子（情态动词被动式）。","correctSentence":"The accident must be reported to the police immediately."},{"type":"fill","sentence":"The witness described the suspect as very tall and wearing a red jacket. The police said it ___ be the same man seen near the bank earlier that day.","subSkill":"possibility_modals","explanation":"根据语境推测，'could / may / might' 表示较大可能性，'must' 表示几乎确定，此处均可接受，关键是表达基于证据的推测。","instruction":"阅读语境并用情态动词填空，表达合理的推测或判断。","acceptableAnswers":["could","may","might","must"]}]},"mission":{"title":"A Letter of Advice to a Friend","scenario":"你需要在信中：① 给出至少两条具体建议（用 should / ought to / had better）；② 对他可能遇到的情况进行推测（用 might / may / could）；③ 提醒他必须或不能做的事情（用 must / must not / have to）；④ 可选：提及他本来应该做的准备（用 should have）。","scaffolds":[{"hint":"用 'might / may' 开始，对他的感受或可能的情况进行推测。","prefix":"Dear Li Wei, I know you might feel nervous, but","suffix":"","example":"Dear Li Wei, I know you might feel nervous, but you may find it easier than you expect once you arrive.","grammarCheck":"possibility_modals"},{"hint":"用 'should / ought to' 给出一条具体建议，例如加入学生社团、提前联系导师等。","prefix":"You should","suffix":"because it will really help you settle in.","example":"You should join some student clubs because it will really help you settle in and make new friends.","grammarCheck":"advice_modals"},{"hint":"用 'must' 提醒一件重要的必须做的事，用 'must not' 提醒一件不可以做的事（例如遵守当地法律规定）。","prefix":"Remember, you must","suffix":"and you must not","example":"Remember, you must register with a local doctor when you arrive, and you must not forget to bring all your official documents.","grammarCheck":"obligation_modals"}],"description":"你的朋友 Li Wei 即将第一次独自去英国留学，他感到非常紧张，向你寻求建议。请用英文给他写一封信（80-120字），使用情态动词提供至少三条建议，并对他可能面临的情况进行推测或分析。","grammarType":"advice_modals"},"discover":{"tip":"情态动词（modal verbs）放在主动词前面，本身不加 -s/-ed。不同情态动词表达不同含义：must/have to 表必要性，can/could/be able to 表能力，may/might/could 表可能性，should/ought to 表建议，should have/must have 等加过去分词表示对过去情况的推断或评价。","story":{"text":"Marco had been hiking for hours when he realized he was completely lost in the forest. He looked at his map, but he couldn't understand it. 'I must stay calm,' he told himself. 'I should follow the river downstream — that might lead me to a village.' He knew he had to find shelter before dark because the temperature could drop dangerously low at night. He tried calling for help on his phone, but there was no signal. 'Someone might hear me if I shout,' he thought. He called out loudly several times. Then he noticed a narrow path through the trees. It could be a trail made by local farmers. 'I may have taken a wrong turn earlier,' he admitted to himself. He decided he must not panic. He followed the path carefully and, after thirty minutes, he was able to see lights in the distance. He should have checked the weather forecast before setting off, but at least now he could see a way out. He must have looked very relieved when he finally reached the village and found warm food and shelter.","title":"The Lost Traveler","highlights":["couldn't","must","should","might","had to","could","may have","must not","was able to","should have","must have"]},"questions":[{"options":["Because someone told him to stay calm.","Because staying calm was necessary for him in that situation.","Because he always stays calm when hiking.","Because he could not feel any emotions."],"question":"Why did Marco say 'I must stay calm'?","explanation":"'Must' 在这里表示强烈的必要性，Marco 认为在迷路的情况下保持冷静是必须要做的事情。","correctIndex":1},{"options":["The path was definitely made by farmers.","The path was impossible to use.","The path was possibly made by farmers, but Marco was not certain.","Marco had already asked the farmers about the path."],"question":"What does 'It could be a trail made by local farmers' tell us?","explanation":"'Could be' 在这里表示推测和可能性，说明 Marco 不确定，只是认为这条路有可能是农民走出来的小道。","correctIndex":2},{"options":["He checked the weather forecast successfully.","He will check the weather forecast next time.","Checking the weather forecast was a good idea, but he did not do it.","He should check the weather forecast right now."],"question":"What does 'He should have checked the weather forecast' mean?","explanation":"'Should have + 过去分词' 表示对过去行为的遗憾或批评，意思是他本来应该做某事，但实际上没有做。","correctIndex":2}]}},"5":{"levels":{"1":[{"type":"choice","options":["melted","will melt","melts","would melt"],"sentence":"If you heat ice, it ___ into water.","subSkill":"zero_conditional","explanation":"零条件句描述自然规律：if + 一般现在时，主句也用一般现在时。冰加热融化是客观事实，所以用melts。","instruction":"选择正确答案，完成零条件句。","correctIndex":2},{"type":"choice","options":["would","will","had","would have"],"sentence":"If Mei finishes her homework early tonight, she ___ watch a film.","subSkill":"first_conditional","explanation":"第一条件句表示将来真实可能发生的情况：if + 一般现在时，主句用will + 动词原形。今晚完成作业是有可能发生的事，所以用will。","instruction":"选择正确答案，完成第一条件句。","correctIndex":1},{"type":"choice","options":["is","were","has been","will be"],"sentence":"If the father ___ a pilot, he could fly the family to the coast.","subSkill":"second_conditional","explanation":"第二条件句表示与现在事实相反的假设：if从句用过去式，be动词正式书面语用were。父亲并不是飞行员，这是假设情况。","instruction":"选择正确答案，完成第二条件句。","correctIndex":1},{"type":"choice","options":["would not have had","will not have","would not have","had not had"],"sentence":"If Mei had remembered the tent, the family ___ this problem.","subSkill":"third_conditional","explanation":"第三条件句表示与过去事实相反的假设：主句用would + have + 过去分词。Mei没有记得带帐篷是已发生的事实，所以主句用would not have had。","instruction":"选择正确答案，完成第三条件句。","correctIndex":0},{"type":"choice","options":["First conditional","Zero conditional","Second conditional","Third conditional"],"sentence":"If plants do not get enough sunlight, they grow slowly.","subSkill":"zero_conditional","explanation":"这句话描述的是植物生长的客观规律——缺乏阳光则生长缓慢。两个从句都用一般现在时，这是零条件句的典型结构。","instruction":"判断句子类型：选出正确的条件句类型。","correctIndex":1},{"type":"choice","options":["is","were","will be","would be"],"sentence":"If the weather ___ good this weekend, the family will go camping.","subSkill":"first_conditional","explanation":"第一条件句的if从句必须用一般现在时，不能用will。'这个周末天气好'是真实可能发生的条件，所以用is。","instruction":"选择正确答案，完成第一条件句。","correctIndex":0},{"type":"choice","options":["will","would","would have","had"],"sentence":"If the mother had more free time, she ___ cook a special meal for the trip.","subSkill":"second_conditional","explanation":"第二条件句主句用would + 动词原形，表示与现在事实相反的假设结果。母亲现在没有足够的空闲时间，所以这是假设情况。","instruction":"选择正确答案，完成第二条件句。","correctIndex":1},{"type":"choice","options":["would avoid","avoided","will have avoided","would have avoided"],"sentence":"If the family had left earlier, they ___ the traffic jam.","subSkill":"third_conditional","explanation":"第三条件句主句用would + have + 过去分词，表示过去没有发生的假设结果。家人没有早些出发是过去的事实，所以用would have avoided。","instruction":"选择正确答案，完成第三条件句。","correctIndex":3}],"2":[{"type":"choice","options":["got","will get","get","would get"],"sentence":"If you mix red and blue paint, you ___ purple.","subSkill":"zero_conditional","explanation":"混合红蓝颜料得到紫色是普遍事实，属于零条件句。if + 一般现在时，主句也用一般现在时，所以选get。","instruction":"选择正确答案完成句子。注意if从句中的时态。","correctIndex":2},{"type":"fill","sentence":"If the brother (save) ___ enough money this month, he will buy a new camera.","subSkill":"first_conditional","explanation":"第一条件句if从句用一般现在时，即使主句是将来时。'这个月存够钱'是可能发生的真实条件，所以用saves。","instruction":"用括号中动词的正确形式填空，完成第一条件句。","acceptableAnswers":["saves"]},{"type":"choice","options":["is","has been","were","will be"],"sentence":"If Mei ___ taller, she could reach the top shelf easily.","subSkill":"second_conditional","explanation":"第二条件句表示与现在事实相反的假设，if从句的be动词在正式书面语中用were。Mei现在并不高，这是假设情况。","instruction":"选出第二条件句的正确形式。","correctIndex":2},{"type":"fill","sentence":"If the family (check) ___ the map more carefully, they would have found the campsite easily.","subSkill":"third_conditional","explanation":"第三条件句if从句用had + 过去分词。家人没有仔细查看地图是过去发生的事实，所以用had checked表示与过去事实相反的假设。","instruction":"用括号中动词的正确形式填空，完成第三条件句。","acceptableAnswers":["had checked"]},{"type":"choice","options":["If it snows tomorrow, we will cancel the trip.","If it snowed tomorrow, we will cancel the trip.","If it had snowed tomorrow, we will cancel the trip.","If it snow tomorrow, we will cancel the trip."],"sentence":"If it will snow tomorrow, we will cancel the trip.","subSkill":"first_conditional","explanation":"第一条件句的if从句不能用will，必须用一般现在时。'明天下雪'是将来可能发生的真实条件，if从句应为if it snows。","instruction":"找出句子中的错误并选出正确版本。","correctIndex":0},{"type":"fill","sentence":"If the father (be) ___ younger, he would climb the mountain with the children.","subSkill":"second_conditional","explanation":"第二条件句if从句中be动词用were，无论主语是单数还是复数。父亲现在年龄较大，这是与现实相反的假设。","instruction":"用括号中动词的正确形式填空，完成第二条件句。","acceptableAnswers":["were"]},{"type":"fill","sentence":"The children might see dolphins. This can only happen if the sea (be) ___ calm.","subSkill":"first_conditional","explanation":"第一条件句if从句用一般现在时表示将来的真实条件。'大海平静'是将来可能发生的条件，所以if从句用is。","instruction":"改写句子，保持意思不变，使用第一条件句结构填入空白。","acceptableAnswers":["is"]},{"type":"choice","options":["If she packs a raincoat, she will not get wet.","If she had packed a raincoat, she would not have got wet.","If she packed a raincoat, she would not get wet.","If she packs a raincoat, she does not get wet."],"sentence":"Which conditional sentence best expresses this idea?","subSkill":"third_conditional","explanation":"原句描述的是过去已发生的事实：没带雨衣所以淋湿了。对过去事实的假设用第三条件句：if + had packed，would + have got。","instruction":"选出与下面句子意思最接近的选项。原句：She did not pack a raincoat, so she got wet.","correctIndex":1}],"3":[{"type":"fill","sentence":"If Mei had joined the school geography club last year, she (know) ___ more about reading maps now.","subSkill":"mixed_conditionals","explanation":"混合条件句：if从句用第三条件句结构表示过去没有发生的事，主句用第二条件句结构(would + 动词原形)表示对现在的影响。Mei过去没有参加地理社团，所以现在地图阅读能力不足。","instruction":"用括号中动词的正确形式填空，完成混合条件句。","acceptableAnswers":["would know"]},{"type":"reorder","words":["could","If","a","have","she","guitar","played","the","she","concert"],"subSkill":"second_conditional","explanation":"第二条件句结构：If + 主语 + 过去式，主语 + could/would + 动词原形。这里描述与现在事实相反的假设——她不会弹吉他，所以无法举办音乐会。","instruction":"将以下单词重新排列，组成一个正确的第二条件句。","correctSentence":"If she played the guitar, she could have a concert."},{"type":"fill","sentence":"The brother (not lose) ___ his ticket if he (put) ___ it in his bag.","subSkill":"third_conditional","explanation":"第三条件句：主句用would + have + 过去分词，if从句用had + 过去分词。哥哥丢了票是过去的事实，两个动词形式都体现对过去事实的反向假设。","instruction":"用括号中动词的正确形式填空，完成第三条件句。两个空格对应两个空白处。","acceptableAnswers":["would not have lost","had put"]},{"type":"reorder","words":["the","rented","had","they","If","car","bigger","a","would","comfortable","now","be","they","more"],"subSkill":"mixed_conditionals","explanation":"混合条件句：if从句用had + 过去分词(过去没发生的事)，主句用would + 动词原形 + now(对现在的影响)。过去没租大车，导致现在不舒适。","instruction":"将以下单词重新排列，组成一个正确的混合条件句。","correctSentence":"If they had rented a bigger car, they would be more comfortable now."},{"type":"fill","sentence":"If the family (take) ___ the map, they (not be) ___ lost now.","subSkill":"mixed_conditionals","explanation":"混合条件句：if从句用had + 过去分词描述过去没有发生的事，主句用would + 动词原形 + now描述对现在的影响。这与第三条件句不同——主句不加have，因为结果是现在时间的状态。","instruction":"改写句子，保持意思不变。原句：The family did not take the map, so they are lost now. 使用混合条件句改写。","acceptableAnswers":["had taken","would not be"]},{"type":"fill","sentence":"Everyone knows that if coastal air (be) ___ salty, it is good for the lungs. The family hopes that if the trip (go) ___ well, they will return next summer.","subSkill":"zero_conditional","explanation":"第一个空是零条件句，描述海边空气的客观事实，if从句用一般现在时is。第二个空是第一条件句，描述将来真实可能的计划，if从句也用一般现在时goes，不能用will go。","instruction":"用括号中动词的正确形式填空，完成零条件句和第一条件句各一处。","acceptableAnswers":["is","goes"]},{"type":"reorder","words":["the","earlier","booked","had","If","hotel","they","have","got","a","would","they","better","room"],"subSkill":"third_conditional","explanation":"第三条件句结构：If + 主语 + had + 过去分词，主语 + would + have + 过去分词。他们没有提前预订是过去的事实，现在只能假设如果当时预订了会怎样。","instruction":"将以下单词重新排列，组成一个正确的第三条件句。","correctSentence":"If they had booked the hotel earlier, they would have got a better room."},{"type":"fill","sentence":"If I (have) ___ wings, I (fly) ___ over the mountains.","subSkill":"second_conditional","explanation":"第二条件句：if从句用一般过去式had表示与现在事实相反的假设，主句用could/would + 动词原形。我没有翅膀是现实，这里用假设来表达不可能的愿望。","instruction":"改写句子，保持意思不变，使用第二条件句。原句：I do not have wings, so I cannot fly over the mountains.","acceptableAnswers":["had","could fly"]}],"4":[{"type":"choice","options":["practiced","had practiced","would practice","has practiced"],"sentence":"If Lisa ___ harder, she would have passed the exam.","subSkill":"third_conditional","explanation":"第三条件句表示与过去事实相反的假设，if从句用过去完成时（had + 过去分词），主句用would have + 过去分词。Lisa实际上没有努力练习，所以用had practiced。","instruction":"选择正确的选项完成第三条件句。Lisa练习得不够努力，所以她没有通过考试。","correctIndex":1},{"type":"choice","options":["will travel","travels","would travel","traveled"],"sentence":"If Tom had a million dollars, he ___ around the world.","subSkill":"second_conditional","explanation":"第二条件句表示与现在事实相反的假设，if从句用过去简单时，主句用would + 动词原形。Tom实际上没有一百万美元，所以用would travel表示假设结果。","instruction":"选择正确的选项完成第二条件句。Tom实际上没有一百万美元，这只是一个假设。","correctIndex":2},{"type":"choice","options":["would be","would have been","will be","is"],"sentence":"If she had studied medicine, she ___ a doctor now.","subSkill":"mixed_conditionals","explanation":"这是混合条件句：if从句用过去完成时表示与过去事实相反，主句用would + 动词原形表示对现在的影响。她现在不是医生是现在的状态，所以主句用would be而非would have been。","instruction":"选择正确的选项完成混合条件句。她过去没有学医，所以她现在不是医生。","correctIndex":0},{"type":"choice","options":["rains","will rain","rained","had rained"],"sentence":"If it ___ tomorrow, the outdoor concert will be cancelled.","subSkill":"first_conditional","explanation":"第一条件句表示将来真实可能的条件，if从句用现在简单时（不用will），主句用will + 动词原形。明天可能下雨是真实可能的情况，所以用rains。","instruction":"选择正确的选项完成第一条件句。这是关于将来可能发生的真实条件。","correctIndex":0},{"type":"fill","sentence":"If they (leave) ___ earlier, they would not have missed the train.","subSkill":"third_conditional","explanation":"第三条件句if从句需要用过去完成时had + 过去分词，表示与过去事实相反的假设。他们实际上没有早出发，所以用had left。","instruction":"用括号中动词的正确形式填空，完成第三条件句。他们没有早点出发，结果误了火车。","acceptableAnswers":["had left"]},{"type":"fill","sentence":"If she (live) ___ in Paris, she would visit the Louvre every week.","subSkill":"second_conditional","explanation":"第二条件句if从句用过去简单时表示与现在事实相反的假设。她实际上不住在巴黎，所以用lived（过去简单时形式）而非lives。","instruction":"用括号中动词的正确形式填空，完成第二条件句。她实际上不住在巴黎，这只是假设。","acceptableAnswers":["lived"]},{"type":"error","words":["If","he","studied","more","carefully,","he","would","have","passed","the","test."],"subSkill":"third_conditional","correction":"had studied","errorIndex":2,"explanation":"第三条件句表示与过去事实相反的假设，if从句必须用过去完成时（had + 过去分词），而不是过去简单时。studied应改为had studied。","instruction":"下面句子中有一个错误，找出错误的单词并改正。这是一个第三条件句。"},{"type":"error","words":["If","you","will","arrive","late,","the","teacher","will","mark","you","absent."],"subSkill":"first_conditional","correction":"arrive","errorIndex":2,"explanation":"第一条件句中if从句不能使用will，必须用现在简单时表示将来的条件。will arrive应改为arrive。主句中的will保留不变。","instruction":"下面句子中有一个错误，找出错误的单词并改正。这是一个第一条件句，表示将来真实可能的情况。"}],"5":[{"type":"fill","sentence":"If he (save) ___ money when he was young, he (be) ___ wealthy now.","subSkill":"mixed_conditionals","explanation":"这是混合条件句：if从句用过去完成时had saved表示与过去事实相反，主句用would + 动词原形be表示对现在状态的影响。他现在贫穷是现在的结果，所以用would be而非would have been。","instruction":"用括号中动词的正确形式填空，完成混合条件句。他年轻时没有存钱，所以他现在很穷。","acceptableAnswers":["had saved","would be"]},{"type":"fill","sentence":"If she ___ an umbrella, she ___ wet.","subSkill":"third_conditional","explanation":"原句表示过去已发生的事，改写为第三条件句表示与过去相反的假设：if从句用had + 过去分词，主句用would not have + 过去分词。got和gotten均可接受（英式/美式）。","instruction":"保持句意不变，用条件句改写下面的句子，填入空白处。She did not bring an umbrella, so she got wet.","acceptableAnswers":["had brought","would not have got","would not have gotten"]},{"type":"reorder","words":["she","would","be","famous","now","if","she","had","entered","the","competition"],"subSkill":"mixed_conditionals","explanation":"混合条件句中，主句（she would be famous now）表示现在的假设结果，用would + 动词原形；if从句（if she had entered the competition）表示过去未发生的事，用过去完成时。","instruction":"将下列单词重新排列，组成一个正确的混合条件句。（提示：过去的原因，现在的结果）","correctSentence":"She would be famous now if she had entered the competition."},{"type":"error","words":["If","he","had","taken","the","job","offer,","he","would","have","been","rich","now."],"subSkill":"mixed_conditionals","correction":"be","errorIndex":10,"explanation":"这是混合条件句：if从句用过去完成时（had taken）表示过去未发生的事，主句应用would + 动词原形（would be）表示对现在的影响。now说明结果是现在的状态，所以不用would have been，应改为would be。","instruction":"下面混合条件句中有一个错误，找出并改正。（提示：注意主句时态）"},{"type":"choice","options":["would not be","would not have been","will not be","is not"],"sentence":"If he had emigrated ten years ago, he ___ here with us now.","subSkill":"mixed_conditionals","explanation":"混合条件句中if从句用过去完成时（had emigrated）表示与过去事实相反，主句中now表明结果是现在的状态，所以用would not be（would + 动词原形）而非would not have been。","instruction":"选择正确的选项完成句子。这个句子表示过去的假设对现在产生的影响。他没有移民，所以他现在仍然在这里。","correctIndex":0},{"type":"fill","sentence":"If she ___ a native speaker, she ___ for this position.","subSkill":"second_conditional","explanation":"第二条件句表示与现在事实相反的假设，if从句用过去简单时（were，注意were比was更正式且语法上更规范），主句用could或would be able to + 动词原形表示能力或可能性。","instruction":"保持句意不变，用第二条件句改写下面的句子，填入空白处。She is not a native speaker, so she cannot apply for this position.","acceptableAnswers":["were","could apply","would be able to apply"]},{"type":"reorder","words":["the","team","would","have","won","the","match","if","their","best","player","had","not","been","injured"],"subSkill":"third_conditional","explanation":"第三条件句中，主句用would have + 过去分词（would have won）表示过去未实现的结果，if从句用过去完成时的被动语态（had not been injured）表示与过去事实相反的条件。球队最佳球员实际上受伤了，所以球队没赢。","instruction":"将下列单词重新排列，组成一个正确的第三条件句。","correctSentence":"The team would have won the match if their best player had not been injured."},{"type":"error","words":["Unless","you","will","submit","the","report","by","Friday,","your","manager","will","not","approve","it."],"subSkill":"first_conditional","correction":"submit","errorIndex":2,"explanation":"unless引导的条件从句与if从句规则相同，不能使用will，必须用现在简单时表示将来的条件。will submit应改为submit。主句中的will not approve保留不变。","instruction":"下面第一条件句中有一个错误，找出并改正。注意从句和主句的时态搭配。"}]},"mission":{"title":"旅行计划与回忆","scenario":"你的朋友住在另一个城市，非常好奇你的假期经历。请用四种条件句写一封80-120字的电子邮件，分享你的旅行故事和感想。","scaffolds":[{"hint":"用零条件句描述一个关于夏季海边旅行的普遍规律，主句用一般现在时。","prefix":"As everyone knows, if you travel to the coast in summer,","suffix":".","example":"As everyone knows, if you travel to the coast in summer, the roads get very busy.","grammarCheck":"zero_conditional"},{"hint":"用第一条件句谈论明年真实可能发生的旅行计划，主句用will + 动词原形。","prefix":"If the weather is good next year,","suffix":".","example":"If the weather is good next year, we will leave much earlier to avoid the traffic.","grammarCheck":"first_conditional"},{"hint":"用第三条件句或混合条件句反思过去的遗憾：if从句用had + 过去分词，主句根据结果是过去还是现在选择相应结构。","prefix":"I really regret that Mei forgot the tent. If she had remembered it,","suffix":".","example":"If she had remembered it, we would have slept under the stars on the first night.","grammarCheck":"third_conditional"}],"description":"你是陈家的长子，假期刚刚结束。请写一封电子邮件给你的好朋友，描述这次家庭旅行。在邮件中，你需要：(1)描述一个关于旅行的普遍规律；(2)谈论下次旅行的真实计划；(3)假设如果条件不同，这次旅行会有什么不同；(4)对某件过去遗憾的事情进行反思。","grammarType":"first_conditional"},"discover":{"tip":"条件句四种类型对比：\n\n【零条件句】if/when + 一般现在时，主句 + 一般现在时 → 表示普遍真理或习惯规律。例：If water reaches 100°C, it boils.\n\n【第一条件句】if + 一般现在时，主句 + will/can/may + 动词原形 → 表示真实可能发生的将来情况。例：If it rains tomorrow, we will stay home.\n\n【第二条件句】if + 一般过去式(be动词用were)，主句 + would/could/might + 动词原形 → 表示与现在事实相反的假设。例：If I had more time, I would travel more.\n\n【第三条件句】if + had + 过去分词，主句 + would/could/might + have + 过去分词 → 表示与过去事实相反的假设，常含遗憾。例：If she had studied harder, she would have passed.\n\n【混合条件句】if从句用第三条件句结构(过去的假设)，主句用第二条件句结构(对现在的影响)。例：If he had taken that job, he would be rich now.\n\n常见错误：\n1. 第一条件句中if从句不能用will：错误写法 — If it will rain... → 正确 — If it rains...\n2. 第二条件句中be动词应用were而非was(正式书面语)：错误写法 — If I was you... → 正确 — If I were you...","story":{"text":"Every summer, the Chen family drives to the coast for a holiday. They know that if it rains, the mountain roads become dangerous — that is simply how those roads work. This year, the father looked at the forecast and said that if the weather stays fine tomorrow, they will leave at dawn and arrive before lunch. However, the mother was more cautious. She told the children that if she had a bigger car, she would pack all their camping gear without any trouble. The youngest daughter, Mei, felt guilty because she had left the tent in her friend's garage the previous week. Her older brother pointed out that if Mei had remembered to bring the tent home, they would not have this problem now. In the end, the family decided to rent a larger vehicle. The father smiled and reminded everyone that if you plan carefully, things usually go smoothly. By the following morning, the car was loaded, the sun was shining, and the whole family was ready for an adventure they would never forget.","title":"The Weather and the Journey","highlights":["if it rains","if the weather stays fine","they will leave","if she had a bigger car","she would pack","if Mei had remembered","would not have this problem now","if you plan carefully","things usually go smoothly"]},"questions":[{"options":["First conditional — a real future plan","Zero conditional — a general scientific or habitual truth","Second conditional — an imaginary present situation","Third conditional — a regret about the past"],"question":"In the sentence 'if it rains, the mountain roads become dangerous', what type of conditional is used?","explanation":"零条件句用于描述普遍规律或习惯性事实，if从句和主句都使用一般现在时。这里'下雨→道路变危险'是一个客观规律，所以是零条件句。","correctIndex":1},{"options":["She does have a big car and will pack everything.","She will buy a bigger car before the trip.","She does not have a big car right now, so she cannot pack everything easily.","She had a big car in the past but sold it."],"question":"The mother says 'if she had a bigger car, she would pack all their camping gear'. What does this tell us about reality?","explanation":"第二条件句用if + 过去式 + would + 动词原形，表示与现在事实相反的假设。母亲没有大车，所以只能假设'如果有的话'会怎样。","correctIndex":2},{"options":["Zero conditional in the if-clause and first conditional in the main clause","Third conditional in the if-clause and second conditional in the main clause","First conditional in both clauses","Second conditional in the if-clause and third conditional in the main clause"],"question":"The brother says 'if Mei had remembered to bring the tent home, they would not have this problem now'. Which structures are mixed here?","explanation":"这是混合条件句：if从句用第三条件句结构(if + had + 过去分词)表示过去没发生的事，主句用第二条件句结构(would + 动词原形)表示对现在的影响——过去的遗漏导致现在的困境。","correctIndex":1}]}},"6":{"levels":{"1":[{"type":"choice","options":["which","who","whom","whose"],"sentence":"The man ___ lives next door is a doctor.","subSkill":"relative_pronouns","explanation":"关系代词指代人且在从句中作主语时，用'who'。'which'用于物，'whom'用于人但作宾语，'whose'表所属。","instruction":"选择正确的关系代词完成句子。","correctIndex":1},{"type":"choice","options":["who","whom","which","whose"],"sentence":"I read a book ___ was written in 1900.","subSkill":"relative_pronouns","explanation":"'which'用于指代物（这里是'a book'）。人用'who'，'whom'指人且作宾语，'whose'表所属。","instruction":"选择正确的关系代词完成句子。","correctIndex":2},{"type":"choice","options":["when","why","who","where"],"sentence":"This is the school ___ I studied as a child.","subSkill":"relative_adverbs","explanation":"'where'是关系副词，用于指代地点。'when'指时间，'why'指原因，'who'是关系代词指人。","instruction":"选择正确的关系副词完成句子。","correctIndex":3},{"type":"choice","options":["where","which","when","who"],"sentence":"Do you remember the day ___ we first met?","subSkill":"relative_adverbs","explanation":"'when'是关系副词，用于指代时间名词（如day, time, year）。","instruction":"选择正确的词完成句子。","correctIndex":2},{"type":"choice","options":["My mother, who loves cooking, made a cake.","The cake, which she baked, was delicious.","The woman who called you is my teacher.","Paris, which is in France, is beautiful."],"sentence":"___","subSkill":"defining_relative_clauses","explanation":"限制性定语从句不用逗号隔开，它对名词的身份起限定作用。'The woman who called you'中的定语从句说明是哪个女人，是必要信息，故为限制性。","instruction":"判断哪个句子是限制性定语从句。","correctIndex":2},{"type":"choice","options":["who","which","that","whose"],"sentence":"The girl ___ bag was stolen called the police.","subSkill":"relative_pronouns","explanation":"'whose'表示所属关系，相当于'her'。句意：包被偷的那个女孩报了警。","instruction":"选择正确的关系代词完成句子。","correctIndex":3},{"type":"choice","options":["when","where","why","which"],"sentence":"The reason ___ she left is still unknown.","subSkill":"relative_adverbs","explanation":"'why'是关系副词，用于指代原因（reason）。","instruction":"选择正确的词完成句子。","correctIndex":2},{"type":"choice","options":["The film that we watched was exciting.","Students who study hard usually pass.","London, which is the capital of England, is very large.","The house where she lives is old."],"sentence":"___","subSkill":"non_defining_relative_clauses","explanation":"非限制性定语从句用逗号隔开，提供补充信息而非限定名词。'London, which is the capital of England'中，London已是专有名词，定语从句只是补充说明。","instruction":"判断哪个句子是非限制性定语从句。","correctIndex":2}],"2":[{"type":"choice","options":["which","whose","who","whom"],"sentence":"The scientist ___ discovered penicillin was Alexander Fleming.","subSkill":"relative_pronouns","explanation":"关系代词指代人且在从句中作主语，用'who'。Fleming是'发现'这一动作的主体。","instruction":"选择最合适的关系词完成句子。","correctIndex":2},{"type":"fill","sentence":"The hotel ___ we stayed last summer had a beautiful pool.","subSkill":"relative_adverbs","explanation":"'where'作关系副词，指代地点（hotel）。也可以说'in which we stayed'，但'where'更常用。","instruction":"用适当的关系代词或关系副词填空。","acceptableAnswers":["where"]},{"type":"choice","options":["who","whom","which","whose"],"sentence":"The teacher ___ everyone respects is retiring next month.","subSkill":"relative_pronouns","explanation":"关系代词指代人且在从句中作宾语（everyone respects her），正式用法用'whom'。口语中也可用'who'。","instruction":"选择正确的关系代词完成句子（关系代词作宾语）。","correctIndex":1},{"type":"fill","sentence":"The laptop ___ I bought last week has already broken down.","subSkill":"defining_relative_clauses","explanation":"这是限制性定语从句，指代物，可用'that'或'which'。'that'不能用于非限制性定语从句。","instruction":"用'that'或'which'填空（注意区分限制性和非限制性从句）。","acceptableAnswers":["that","which"]},{"type":"choice","options":["that","which","who","whose"],"sentence":"My sister, ___ is a nurse, works night shifts.","subSkill":"non_defining_relative_clauses","explanation":"非限制性定语从句中指代人用'who'，不能用'that'。注意逗号的使用。","instruction":"选择正确的选项完成非限制性定语从句。","correctIndex":2},{"type":"fill","sentence":"I know the reason ___ he is always late.","subSkill":"relative_adverbs","explanation":"'why'是关系副词，修饰表原因的名词'reason'。","instruction":"用适当的关系词填空。","acceptableAnswers":["why"]},{"type":"choice","options":["who","which","whose","whom"],"sentence":"The painter ___ works are displayed in the museum died young.","subSkill":"relative_pronouns","explanation":"'whose'表所属，'whose works'即'his/her works'。这里关系代词修饰'works'，表明作品属于那位画家。","instruction":"选择正确的关系词。","correctIndex":2},{"type":"fill","sentence":"2008 was the year ___ the Olympic Games were held in Beijing.","subSkill":"relative_adverbs","explanation":"'when'是关系副词，指代时间名词'year'，表示在那一年。","instruction":"用适当的关系代词或关系副词填空。","acceptableAnswers":["when"]}],"3":[{"type":"fill","sentence":"The colleague ___ I work with most closely is very supportive.","subSkill":"relative_pronouns","explanation":"关系代词在从句中作介词'with'的宾语，正式书面语用'whom'，口语和非正式场合可用'who'或'that'，也可省略。","instruction":"用适当的关系代词填空（注意正式与非正式用法）。","acceptableAnswers":["whom","who","that"]},{"type":"reorder","words":["The","city","where","I","grew","up","has","changed","a","lot"],"subSkill":"relative_adverbs","explanation":"'where I grew up'是关系副词引导的定语从句，修饰'city'，作主句主语的后置定语。","instruction":"将单词重新排列，组成正确的句子。","correctSentence":"The city where I grew up has changed a lot."},{"type":"fill","sentence":"The Great Wall, ___ stretches thousands of kilometres, attracts millions of tourists.","subSkill":"non_defining_relative_clauses","explanation":"非限制性定语从句修饰'The Great Wall'，指代物用'which'，不能用'that'。逗号是非限制性从句的标志。","instruction":"用适当的关系词填空，注意非限制性从句的使用。","acceptableAnswers":["which"]},{"type":"reorder","words":["She","is","the","scientist","whose","research","changed","medicine"],"subSkill":"relative_pronouns","explanation":"'whose research'中'whose'表所属，引导定语从句修饰'the scientist'，'whose research'作从句的主语。","instruction":"将单词重新排列，组成正确的句子。","correctSentence":"She is the scientist whose research changed medicine."},{"type":"fill","sentence":"The film (that) ___ she recommended won three awards.","subSkill":"omitting_relative_pronouns","explanation":"限制性定语从句中，关系代词作宾语时可以省略。这里'that/which'是'recommended'的宾语，可省略。","instruction":"在括号中给出的句子中，省略可以省略的关系代词（如不能省略则保留）。","acceptableAnswers":["that","which",""]},{"type":"reorder","words":["My","father",",","who","is","a","chef",",","cooked","dinner"],"subSkill":"non_defining_relative_clauses","explanation":"非限制性定语从句'who is a chef'用逗号隔开，补充说明父亲的职业，不影响主句意思。","instruction":"将单词重新排列，组成正确的句子（包含非限制性定语从句）。","correctSentence":"My father, who is a chef, cooked dinner."},{"type":"fill","sentence":"The company ___ she works for has offices in twenty countries.","subSkill":"relative_pronouns","explanation":"关系代词指代物（company），在从句中作介词'for'的宾语，可用'which'或'that'，也可省略。","instruction":"用适当的关系词填空。","acceptableAnswers":["which","that"]},{"type":"reorder","words":["This","is","the","reason","why","I","chose","this","career"],"subSkill":"relative_adverbs","explanation":"'why I chose this career'是关系副词'why'引导的定语从句，修饰'the reason'，解释原因。","instruction":"将单词重新排列，组成正确的含有定语从句的句子。","correctSentence":"This is the reason why I chose this career."},{"type":"fill","sentence":"The village ___ my grandparents were born no longer exists.","subSkill":"relative_adverbs","explanation":"'where'引导定语从句修饰地点名词'village'，表示'在那个村子里'。","instruction":"用适当的关系代词或关系副词填空。","acceptableAnswers":["where"]}],"4":[{"type":"error","words":["The","man","which","called","you","is","my","uncle"],"subSkill":"relative_pronouns","correction":"who","errorIndex":2,"explanation":"'which'不能指代人。指代人且在从句中作主语时，应用'who'。","instruction":"找出句子中有错误的单词并改正。"},{"type":"fill","sentence":"Ernest Hemingway, ___ wrote 'The Old Man and the Sea', won the Nobel Prize.","subSkill":"non_defining_relative_clauses","explanation":"Hemingway是专有名词，定语从句是非限制性的，用逗号隔开，指代人用'who'，不能用'that'。","instruction":"用适当的关系词填空，注意是否需要逗号。","acceptableAnswers":["who"]},{"type":"choice","options":["Students, who work hard, always succeed.","Students who work hard always succeed.","Students which work hard always succeed.","Students, that work hard, always succeed."],"sentence":"___","subSkill":"defining_relative_clauses","explanation":"此句表示'努力学习的学生'，是对'students'的限定，应用限制性定语从句（无逗号）。选项A加了逗号变成非限制性，意思变为'所有学生都努力'。选项C用'which'指人错误，选项D的'that'不能用于非限制性从句。","instruction":"选择正确的句子（注意限制性与非限制性定语从句的区别）。","correctIndex":1},{"type":"error","words":["This","is","the","house","where","I","bought","last","year"],"subSkill":"relative_adverbs","correction":"that","errorIndex":4,"explanation":"'where'是关系副词，后接完整句子（不缺少成分）。但'I bought last year'中'bought'缺少宾语，说明关系词在从句中作宾语，应用关系代词'that'或'which'，而非关系副词'where'。","instruction":"找出句子中有错误的单词并改正。"},{"type":"fill","sentence":"I met a professor. Her book won a national prize. → I met a professor ___ book won a national prize.","subSkill":"relative_pronouns","explanation":"'Her book'中的'her'表所属，合并时用'whose'替换，'whose book'作从句的主语。","instruction":"将以下两个句子合并为一个含定语从句的句子，填写所缺的关系词。","acceptableAnswers":["whose"]},{"type":"error","words":["Rome,","that","is","Italy's","capital,","has","a","rich","history"],"subSkill":"non_defining_relative_clauses","correction":"which","errorIndex":1,"explanation":"非限制性定语从句（有逗号）不能使用'that'。指代物的非限制性从句应用'which'。","instruction":"找出句子中有错误的单词并改正。"},{"type":"fill","sentence":"The documentary that we watched last night was fascinating. → The documentary ___ we watched last night was fascinating.","subSkill":"omitting_relative_pronouns","explanation":"限制性定语从句中，'that'作宾语（we watched it）可以省略，直接用'the documentary we watched last night'。","instruction":"改写句子，省略可以省略的关系代词（填入省略后的从句部分）。","acceptableAnswers":[""]},{"type":"choice","options":["which","who","whom","whose"],"sentence":"She is the candidate ___ the committee selected for the position.","subSkill":"relative_pronouns","explanation":"关系代词指代人（candidate）且在从句中作宾语（the committee selected her），正式书面语应用'whom'。口语可用'who'，'which'指物，'whose'表所属，均不正确。","instruction":"选择最正确、最正式的表达方式。","correctIndex":2}],"5":[{"type":"error","words":["The","era","where","people","had","no","smartphones","seems","distant"],"subSkill":"relative_adverbs","correction":"when","errorIndex":2,"explanation":"'where'指地点，'era'是时间名词，应用关系副词'when'。也可用'in which'替代。","instruction":"找出句子中有错误的单词并改正。"},{"type":"reorder","words":["The","report",",","which","took","six","months","to","complete",",","was","finally","published"],"subSkill":"non_defining_relative_clauses","explanation":"非限制性定语从句'which took six months to complete'用逗号隔开，补充说明报告的情况。注意逗号的位置。","instruction":"将单词重新排列，组成一个含非限制性定语从句的正确句子。","correctSentence":"The report, which took six months to complete, was finally published."},{"type":"fill","sentence":"He works for a company. The company exports goods worldwide. → He works for a company ___ exports goods worldwide.","subSkill":"defining_relative_clauses","explanation":"限制性定语从句修饰'a company'，关系代词在从句中作主语，不可省略，可用'that'或'which'。","instruction":"将两个句子合并，使用适当的关系词（可能需要省略关系代词）。","acceptableAnswers":["that","which"]},{"type":"error","words":["The","author","who's","novel","I","read","is","coming","to","our","school"],"subSkill":"relative_pronouns","correction":"whose","errorIndex":2,"explanation":"'who's'是'who is'的缩写，不表所属。表示所属关系应用'whose'，'whose novel'意为'他/她的小说'。","instruction":"找出句子中有错误的单词并改正。"},{"type":"fill","sentence":"The new policy, ___ affects all employees, will be introduced next quarter.","subSkill":"non_defining_relative_clauses","explanation":"非限制性定语从句（有逗号）中，指代物（policy）用'which'，不能用'that'。","instruction":"用适当的关系词填空（注意语境，考虑是否使用非限制性从句）。","acceptableAnswers":["which"]},{"type":"reorder","words":["The","advice","she","gave","me","was","extremely","helpful"],"subSkill":"omitting_relative_pronouns","explanation":"此句省略了关系代词'that/which'，完整形式为'The advice that she gave me...'。'that/which'在从句中作宾语，可以省略。","instruction":"将单词重新排列，组成正确的句子（注意关系代词的省略）。","correctSentence":"The advice she gave me was extremely helpful."},{"type":"choice","options":["The town where I visited last year was charming.","The town which I visited last year was charming.","The town when I visited last year was charming.","The town whose I visited last year was charming."],"sentence":"___","subSkill":"relative_pronouns","explanation":"'I visited the town'中'visited'需要宾语，关系词在从句中作宾语，应用关系代词'which'（或'that'，可省略）。'where'是关系副词，后接的从句不缺少成分；'when'指时间；'whose'表所属，均不适用。","instruction":"选择语法和语义均正确的句子。","correctIndex":1},{"type":"error","words":["He","gave","me","a","book",",","that","I","found","very","inspiring"],"subSkill":"non_defining_relative_clauses","correction":"which","errorIndex":6,"explanation":"非限制性定语从句（有逗号）中不能使用'that'，应用'which'来指代物（book）。","instruction":"找出句子中有错误的单词并改正。"}]},"mission":{"title":"介绍一个对你重要的地方","scenario":"你的外国笔友想了解中国的某个地方，请给他/她写一段80-120字的介绍，说明这个地方的位置、特点，以及它对你的意义。尝试使用定语从句让你的描述更加生动具体。","scaffolds":[{"hint":"用限制性定语从句描述这个地方，使用'where'或'that/which'","prefix":"The place","suffix":"is very special to me.","example":"The place where I grew up is very special to me.","grammarCheck":"defining_relative_clauses"},{"hint":"先描述这个地方的一个特点，然后用非限制性定语从句补充说明","prefix":"","suffix":", which makes it unique.","example":"The park has hundreds of ancient trees, which makes it unique.","grammarCheck":"non_defining_relative_clauses"},{"hint":"用定语从句描述这个地方的人，可以使用'who'或省略关系代词","prefix":"The people","suffix":"are always warm and welcoming.","example":"The people who live there are always warm and welcoming.","grammarCheck":"relative_pronouns"}],"description":"用定语从句写一篇介绍文，描述一个对你有特殊意义的地方（如你的家乡、学校、喜欢的公园等）。要求使用至少两种不同的关系词，并包含至少一个非限制性定语从句。","grammarType":"defining_relative_clauses"},"discover":{"tip":"定语从句分两种：限制性定语从句（无逗号，是识别名词必须的信息）和非限制性定语从句（有逗号，只是补充信息）。关系代词：who/whom指人，which指物，that指人或物（仅限制性），whose表所属；关系副词：where指地点，when指时间，why指原因。当关系代词在从句中作宾语时，限制性定语从句中可省略它。","story":{"text":"Last year, I found a small library that was hidden behind the old post office. The librarian, who had worked there for thirty years, welcomed me warmly. She showed me a reading room where students could study quietly for hours. I borrowed a book whose cover was decorated with golden stars. The author, whom I had never heard of before, wrote beautifully about travel and adventure. There was also a section I particularly loved, filled with maps of ancient cities. The friend I went with that day became a regular visitor too. On Saturdays, the library holds events where local writers share their stories. My favourite event, which takes place every month, features a poet from our neighbourhood. The library that I discovered last year has truly become my second home. I believe every city needs places where people can gather, think, and grow together.","title":"The Library That Changed Everything","highlights":["that","who","where","whose","whom","which"]},"questions":[{"options":["I found a small library that was hidden behind the old post office.","The librarian, who had worked there for thirty years, welcomed me warmly.","There was also a section I particularly loved.","The friend I went with that day became a regular visitor too."],"question":"Which sentence uses a NON-DEFINING relative clause?","explanation":"非限制性定语从句用逗号与主句隔开，补充说明而非限定名词。句子B中'who had worked there for thirty years'是对'The librarian'的补充说明，前后有逗号，是非限制性定语从句。","correctIndex":1},{"options":["The librarian","The library","The book","The author"],"question":"In the sentence 'I borrowed a book whose cover was decorated with golden stars', what does 'whose' refer to?","explanation":"'whose'是关系代词，表示所属关系，在此句中代替'the book's'，说明封面属于这本书。whose用于人或物皆可。","correctIndex":2},{"options":["My favourite event, which takes place every month, features a poet.","She showed me a reading room where students could study quietly.","The friend I went with that day became a regular visitor too.","The author, whom I had never heard of before, wrote beautifully."],"question":"Which sentence contains an OMITTED relative pronoun?","explanation":"在限制性定语从句中，当关系代词作宾语时可以省略。'The friend I went with that day'中省略了关系代词'whom/that'，完整形式为'The friend whom/that I went with that day'。","correctIndex":2}]}},"7":{"levels":{"1":[{"type":"choice","options":["a","an","the","no article"],"sentence":"She bought ___ new laptop yesterday.","subSkill":"indefinite_article_usage","explanation":"'laptop' 以辅音音素 /l/ 开头，且是第一次提到，应用不定冠词 'a'。","instruction":"选择正确的冠词填入空白处。","correctIndex":0},{"type":"choice","options":["a","an","the","no article"],"sentence":"We visited ___ Eiffel Tower when we were in Paris.","subSkill":"definite_article_usage","explanation":"埃菲尔铁塔是世界上唯一的，双方都知道指的是哪座塔，应用定冠词 'the'。","instruction":"选择正确的冠词填入空白处。","correctIndex":2},{"type":"choice","options":["A","An","The","Some"],"sentence":"___ information on the website is not always accurate.","subSkill":"definite_article_usage","explanation":"'the information on the website' 中有 'on the website' 这一限定语，说明是特指该网站上的信息，所以用定冠词 'the'。","instruction":"选择正确的选项。","correctIndex":2},{"type":"choice","options":["A large amount of","A great deal of","A large number of","Much"],"sentence":"___ students in my class come from different countries.","subSkill":"quantifiers","explanation":"'students' 是可数名词复数，应用 'a large number of' 来修饰可数名词。'a great deal of' 和 'a large amount of' 只修饰不可数名词。","instruction":"选择正确的量词。","correctIndex":2},{"type":"choice","options":["She is an honest person.","She is a honest person.","She is the honest person.","She is honest person."],"sentence":"Which sentence uses articles correctly?","subSkill":"indefinite_article_usage","explanation":"'honest' 的发音以元音音素 /ɒ/ 开头（h 不发音），所以用 'an' 而非 'a'。","instruction":"以下哪个句子中冠词使用正确？","correctIndex":0},{"type":"choice","options":["A","The","An","no article"],"sentence":"___ gold is a valuable metal.","subSkill":"zero_article_rules","explanation":"当不可数名词泛指整个类别时，使用零冠词。这里 'gold' 泛指黄金这种物质，不是特指某些黄金。","instruction":"选择正确的选项，注意零冠词的用法。","correctIndex":3},{"type":"choice","options":["a few","several","a little","a number of"],"sentence":"The teacher gave us ___ advice about the exam.","subSkill":"quantifiers","explanation":"'advice' 是不可数名词，'a little' 可修饰不可数名词。'a few'、'several'、'a number of' 只能修饰可数名词。","instruction":"选择正确的选项。","correctIndex":2},{"type":"choice","options":["a / The","the / The","a / A","the / A"],"sentence":"I saw ___ interesting film last night. ___ film was about space exploration.","subSkill":"definite_article_usage","explanation":"第一次提到这部电影是引入新信息，用不定冠词 'a'；第二次提到时读者已知道是哪部电影，改用定冠词 'The'。","instruction":"选择正确的冠词。","correctIndex":0}],"2":[{"type":"choice","options":["a large number of","a great deal of","many","a few"],"sentence":"The factory produced ___ pollution that the local river was badly damaged.","subSkill":"quantifiers","explanation":"'pollution' 是不可数名词，应用 'a great deal of' 来修饰。'many' 和 'a few' 只用于可数名词，'a large number of' 也只用于可数名词。","instruction":"选择最合适的量词完成句子。","correctIndex":1},{"type":"choice","options":["a very old beautiful stone bridge","a beautiful very old stone bridge","a beautiful old stone bridge","beautiful a old stone bridge"],"sentence":"Which noun phrase is correctly formed?","subSkill":"noun_phrase_structure","explanation":"名词短语中形容词的排列顺序为：限定词 + 评价 + 年龄/新旧 + 材料 + 名词。'beautiful'（评价）应在 'old'（年龄）之前。'a beautiful old stone bridge' 符合此规则。","instruction":"以下哪个名词短语结构正确？","correctIndex":2},{"type":"fill","sentence":"There is (a/an) ___ hour-long documentary about climate change on television tonight.","subSkill":"indefinite_article_usage","explanation":"'hour' 的发音以元音音素 /aʊ/ 开头（h 不发音），所以用 'an' 而非 'a'。","instruction":"用括号内词语的正确形式或合适的冠词填空。","acceptableAnswers":["an"]},{"type":"fill","sentence":"Scientists believe that ___ climate change is the most urgent problem facing ___ world today.","subSkill":"zero_article_rules","explanation":"'climate change' 作为泛指的抽象概念使用零冠词；'the world' 中世界是唯一存在的，且有 'today' 限定，应用 'the'。","instruction":"用正确的冠词（a, an, the）或不填（写 X）完成句子。","acceptableAnswers":["X","the"]},{"type":"choice","options":["The","A","An","no article"],"sentence":"___ considerable amount of evidence suggests that regular exercise improves mental health.","subSkill":"quantifiers","explanation":"'a considerable amount of' 是固定搭配，修饰不可数名词 'evidence'，表示相当数量的某物。'amount' 以元音开头但前面有 'considerable' 以辅音开头，所以用 'a'。","instruction":"选择正确的选项完成学术句子。","correctIndex":1},{"type":"fill","sentence":"My sister has just adopted ___ cat. ___ cat has bright green eyes and loves to sleep in the sun.","subSkill":"definite_article_usage","explanation":"第一次提到这只猫是引入新事物，用不定冠词 'a'；第二次提到时已经是特指那只猫，改用定冠词 'The'。","instruction":"用合适的冠词填空，注意名词在文中是泛指还是特指。","acceptableAnswers":["a","The"]},{"type":"fill","sentence":"Many proposals were submitted before the deadline. → ___ proposals were submitted before the deadline.","subSkill":"quantifiers","explanation":"'many' 和 'a large number of' 都修饰可数名词复数，意思相近。'a large number of' 更常见于正式书面语。","instruction":"改写句子，保持意思不变，用 'a large number of' 替换划线部分。","acceptableAnswers":["A large number of"]},{"type":"choice","options":["The happiness is important for everyone.","She plays the piano very well.","He is an university student.","We need a equipment for the project."],"sentence":"Which sentence has NO article error?","subSkill":"definite_article_usage","explanation":"'plays the piano' 中乐器名称前用 'the' 是固定用法，正确。选项A错误（泛指抽象名词用零冠词）；选项C错误（'university' 读音以 /j/ 辅音音素开头，用 'a'）；选项D错误（'equipment' 是不可数名词，不能用 'a'）。","instruction":"选出没有冠词错误的句子。","correctIndex":1}],"3":[{"type":"fill","sentence":"The researchers published (finding/remarkable/their) ___ ___ ___ in an international journal.","subSkill":"noun_phrase_structure","explanation":"名词短语结构为：限定词（their）+ 评价形容词（remarkable）+ 名词（findings）。'findings' 需要用复数形式，因为研究结果通常是多个。","instruction":"用括号中的词语填写正确形式，注意名词短语结构。","acceptableAnswers":["their","remarkable","findings"]},{"type":"fill","sentence":"The project required much careful planning. → The project required ___ careful planning.","subSkill":"quantifiers","explanation":"'much' 和 'a great deal of' 都可修饰不可数名词，意思相近，但 'a great deal of' 更常用于正式书面语。'planning' 是不可数名词，两者均可搭配。","instruction":"改写句子，保持意思不变。将 'much' 改为 'a great deal of'。","acceptableAnswers":["a great deal of"]},{"type":"fill","sentence":"There is ___ growing body of evidence that ___ physical activity reduces stress. ___ evidence comes from studies conducted across ___ number of different countries.","subSkill":"zero_article_rules","explanation":"第一空：'a growing body of' 是固定搭配；第二空：'physical activity' 泛指体育活动这一概念，用零冠词；第三空：'The evidence' 特指上文提到的那些证据，用 'the'；第四空：'a number of' 是固定量词短语，修饰可数名词复数 'countries'。","instruction":"用正确的冠词或量词填空，完成这段学术风格的文字。","acceptableAnswers":["a","X","The","a"]},{"type":"fill","sentence":"In (general/zero article) ___, (the/zero) ___ success of a project depends on (the/zero) ___ clear communication among team members.","subSkill":"definite_article_usage","explanation":"'In general' 是固定短语，'general' 前不加冠词；'the success of a project' 中 'success' 被 'of a project' 限定为特指，需用 'the'；'clear communication' 泛指整体概念，用零冠词。","instruction":"改写下列句子，用 'the' 或零冠词替换括号中的提示，保持意思准确。","acceptableAnswers":["X","the","X"]}],"4":[{"type":"choice","options":["a","an","the","(no article)"],"sentence":"Most historians agree that ___ World War II fundamentally changed the political landscape of Europe.","subSkill":"definite_article_usage","explanation":"专有名词中，当战争名称包含序数词或专有限定词（如 \"World War II\"）时，通常使用定冠词 \"the\"，因为它指的是历史上那场特定的、唯一确定的战争。","instruction":"选择正确的冠词或零冠词形式。","correctIndex":2},{"type":"choice","options":["few","a few","an","a"],"sentence":"The committee received ___ overwhelming number of complaints about the new policy.","subSkill":"quantifiers","explanation":"\"a number of\" 是固定搭配，意为\"许多\"，等同于 \"many\"。此处 \"an overwhelming number\" 中 \"overwhelming\" 以元音音素 /ɒ/ 开头，但整个短语的核心是 \"a number of\"，所以选 \"a\" 配合 \"number\"，即 \"an overwhelming number\" — 注意 \"an\" 修饰 \"overwhelming\"，选项中 \"a\" 不合适，但本题要求补全 \"___ overwhelming number\"，\"overwhelming\" 以元音开头，故选 \"an\"。","instruction":"选择最合适的量词完成句子。","correctIndex":3},{"type":"choice","options":["a","an","the","(no article)"],"sentence":"Researchers have found that ___ regular exercise reduces the risk of cardiovascular disease.","subSkill":"zero_article_rules","explanation":"当泛指一个概念或普遍现象时，不可数名词和复数名词前使用零冠词。\"regular exercise\" 泛指锻炼这一行为概念，不指某次具体的锻炼，因此不加冠词。","instruction":"选择正确的冠词或零冠词形式。","correctIndex":3},{"type":"fill","sentence":"The report highlighted (remarkable / a / in urban areas / decline) ___ in property values.","subSkill":"noun_phrase_structure","explanation":"名词短语的正确结构为：冠词 + 形容词 + 名词 + 介词短语后置修饰语。因此应为 \"a remarkable decline in urban areas\"，形容词 \"remarkable\" 置于名词 \"decline\" 之前，介词短语 \"in urban areas\" 作后置定语。","instruction":"用括号内的词语填写适当的名词短语形式（注意冠词和词序）。","acceptableAnswers":["a remarkable decline in urban areas"]},{"type":"fill","sentence":"Only ___ of the submitted manuscripts met the journal's strict formatting requirements.","subSkill":"quantifiers","explanation":"此处需要一个表示\"少量\"的量词短语，后接 \"of the submitted manuscripts\"（特指已提交的稿件）。常见选项如 \"a handful of\"、\"a small number of\" 或 \"a few of\" 均可表达\"只有少数\"的含义，符合语境。","instruction":"在空白处填入适当的量词，使句子语法正确且符合语境。","acceptableAnswers":["a handful","a minority","a small number","a few"]}],"5":[{"type":"fill","sentence":"The professor recommended (read) ___ a wide range of peer-reviewed literature before (begin) ___ the thesis.","subSkill":"noun_phrase_structure","explanation":"动词 \"recommend\" 后接动名词（-ing 形式）作宾语，而非不定式。同样，介词 \"before\" 后也必须接动名词。因此两个空格均需要动名词形式：\"reading\" 和 \"beginning\"。","instruction":"用所给词的正确形式完成句子，注意名词短语的完整结构。","acceptableAnswers":["reading","beginning"]},{"type":"fill","sentence":"Many people believe that eating too much sugar is harmful. (It is widely believed ___)","subSkill":"zero_article_rules","explanation":"关键词转换：将主动结构 \"Many people believe that\" 改写为被动的非人称结构 \"It is widely believed that\"。名词短语 \"eating too much sugar\" 可保留作为从句的主语，冠词和结构无需改变，零冠词规则适用于泛指的饮食习惯。","instruction":"改写句子，保持原意不变，使用括号中给出的词语开头。注意冠词和名词短语结构的变化。","acceptableAnswers":["It is widely believed that eating too much sugar is harmful","It is widely believed that the consumption of too much sugar is harmful"]},{"type":"choice","options":["a great","a large","a big","an enormous"],"sentence":"The new regulations have generated ___ deal of controversy among leading economists.","subSkill":"quantifiers","explanation":"\"a great deal of\" 是固定搭配，用于修饰不可数名词（如 \"controversy\"），表示大量。\"a large deal\" 和 \"a big deal\" 在这一语境中不用于修饰不可数名词表示数量，\"an enormous deal\" 同样不是标准搭配。学术写作中 \"a great deal of\" 最为规范。","instruction":"选择最符合语境的表达，注意量词与名词搭配的准确性。","correctIndex":0},{"type":"fill","sentence":"According to ___ latest findings, ___ access to quality education remains unequal across different regions.","subSkill":"zero_article_rules","explanation":"第一空：\"the latest findings\" 中用定冠词 \"the\"，因为 \"latest\" 表示最新的、特定的，指称唯一最新的研究发现。第二空：\"access to quality education\" 是泛指概念，\"access\" 为不可数名词且此处为泛指，符合零冠词规则，不加冠词。","instruction":"在空白处填入适当的冠词（a / an / the）或写 X 表示零冠词，完成这段学术文字。","acceptableAnswers":["the","X"]},{"type":"fill","sentence":"Few scholars dispute the importance of peer review in academic publishing. (There is little ___)","subSkill":"noun_phrase_structure","explanation":"关键词转换：\"Few scholars dispute\" 改写为 \"There is little dispute (among scholars)\"，将动词 \"dispute\" 转化为名词，并用量词 \"little\" 修饰不可数名词 \"dispute\"（表示几乎没有）。定冠词 \"the\" 保留在 \"the importance of\" 之前，因其后有 \"of\" 短语使名词特指化。","instruction":"改写句子，保持原意不变，使用括号中的词语。注意冠词和名词短语的相应变化。","acceptableAnswers":["There is little dispute among scholars about the importance of peer review in academic publishing","There is little scholarly dispute about the importance of peer review in academic publishing"]}]},"mission":{"title":"城市规划报告","scenario":"你所在的城市正在考虑改善公共设施。请根据提示写出3句报告内容，描述现状问题和建议措施。每句话都需要包含至少一个量词或冠词用法。","scaffolds":[{"hint":"用一个不可数名词描述城市中心存在的问题（如 traffic congestion, air pollution, noise）","prefix":"There is a considerable amount of","suffix":"in the city centre, which affects the quality of life for residents.","example":"There is a considerable amount of traffic congestion in the city centre, which affects the quality of life for residents.","grammarCheck":"quantifiers"},{"hint":"用 'a + 形容词 + 名词' 的名词短语描述政府新建的设施（如 a modern bus terminal, a large car park）","prefix":"The local government has recently built","suffix":"near the main station to improve public transport.","example":"The local government has recently built a large modern bus terminal near the main station to improve public transport.","grammarCheck":"indefinite_article_usage"},{"hint":"用可数名词复数描述支持该计划的群体（如 residents, business owners, local schools）","prefix":"A large number of","suffix":"have expressed support for the new development plan.","example":"A large number of local residents have expressed support for the new development plan.","grammarCheck":"quantifiers"}],"description":"你是一名城市规划助理，需要用英语撰写一份关于改善城市公共设施的简短报告。报告中需要正确使用定冠词、不定冠词、零冠词以及量词，展示你对名词短语结构的掌握。","grammarType":"noun_phrase_structure"},"discover":{"tip":"【名词短语与冠词核心规则】\n\n**不定冠词 a/an（indefinite article）**：用于可数名词单数，第一次提到某事物，或泛指同类中的任意一个。元音音素开头的词用 an（an important decision, an architect）。\n\n**定冠词 the（definite article）**：用于双方都知道指哪个事物时——(1) 前文已提到；(2) 语境中唯一存在（the government, the harbour）；(3) 最高级或序数词后；(4) 特定修饰语使名词唯一化（the school on the northern side）。\n\n**零冠词（zero article）**：(1) 不可数名词或复数名词表示泛指（research, children, tourists）；(2) 专有名词；(3) 抽象概念总称（public transport, urban planning）。\n\n**量词选择**：可数名词用 a large/great number of, a few, several, many；不可数名词用 a great/good deal of, a large amount of, much, a little。混用是常见错误，如说 a number of research 或 an amount of visitors 均为错误。\n\n**常见错误**：(1) 泛指复数名词前误加 the（误：The children need love → 泛指时应说 Children need love）；(2) 第二次提到事物仍用 a/an；(3) 将 amount of 用于可数名词。","story":{"text":"Ten years ago, a small coastal town had almost no facilities for tourists. There was a single hotel near the harbour, and the hotel was famous for its excellent seafood. A large number of visitors came every summer, but the lack of public transport was a serious problem. The local government made an important decision to invest in infrastructure. They built a new bus station at the edge of town and added a considerable amount of green space along the waterfront. The town also attracted a well-known architect who designed several striking buildings in the centre. Each building had a unique style, and the buildings soon became landmarks. A great deal of research was conducted into the needs of residents, and the findings showed that most people wanted better schools. The authorities therefore constructed a brand-new secondary school on the northern side of town. Today, the school serves hundreds of children from the surrounding area. The transformation of this once-quiet town is regarded as a remarkable example of careful urban planning, and experts from other regions frequently visit to study the model.","title":"A City Transformed","highlights":["a small coastal town","the hotel","a large number of","a considerable amount of","a well-known architect","a great deal of","the school","the transformation","no facilities","public transport"]},"questions":[{"options":["可数名词总是用 'a/an'","第一次提到某事物用不定冠词，之后再提用定冠词","单数名词必须始终用 'the'","'hotel' 是专有名词所以用 'the'"],"question":"故事第一次提到这座酒店时用了 'a single hotel'，后来再次提到时用了 'the hotel'。这说明了什么？","explanation":"不定冠词 'a/an' 用于第一次引入某个事物（读者还不知道），之后再次提到同一事物时，读者已经知道指的是哪个，所以改用定冠词 'the'。","correctIndex":1},{"options":["两者可以互换，没有区别","'number of' 修饰可数名词，'deal of' 修饰不可数名词","'large' 比 'great' 更正式","'number of' 只用于书面语"],"question":"故事中出现了 'a large number of visitors' 和 'a great deal of research'，为什么用了不同的量词？","explanation":"'a large number of' 修饰可数名词复数（如 visitors），'a great deal of' 修饰不可数名词（如 research）。选择量词时必须考虑名词是否可数。","correctIndex":1},{"options":["笔误，应该加 'the'","零冠词用法，泛指抽象概念或不可数名词的总体概念","因为这两个词是形容词所以不需要冠词","美式英语省略冠词的习惯"],"question":"故事中写到 'public transport' 和 'urban planning'，两者都没有冠词。这属于哪种用法？","explanation":"当不可数名词或抽象概念表示泛指（整体概念而非特定事物）时，使用零冠词。'public transport' 和 'urban planning' 都是泛指概念，不指特定的某次交通或某次规划。","correctIndex":1}]}},"8":{"levels":{"1":[{"type":"choice","options":["cold","colder","coldest","more cold"],"sentence":"January is ___ than June in Iceland.","subSkill":"comparative_adjectives","explanation":"单音节形容词 cold 的比较级是 colder，用于比较两个事物（一月和六月），不用 more cold（双重比较是错误的）。","instruction":"选择正确的比较级形式完成句子。","correctIndex":1},{"type":"choice","options":["longer","the longest","the most long","most longest"],"sentence":"The Nile is ___ river in the world.","subSkill":"superlative_adjectives","explanation":"表示在所有河流中最长，需用最高级 the longest。单音节词 long 加 -est 构成最高级，不用 the most long。","instruction":"选择正确的最高级形式完成句子。","correctIndex":1},{"type":"choice","options":["as strong than","as strong as","stronger as","more strong as"],"sentence":"The new bridge is not ___ the old one.","subSkill":"as_as_structures","explanation":"否定的 as...as 结构表示'不如……那么……'，格式固定为 not as + 形容词 + as，表示新桥的强度不及旧桥。","instruction":"选择正确的 as...as 结构完成句子。","correctIndex":1},{"type":"choice","options":["significantly higher","significantly highest","significant higher","significantly more high"],"sentence":"In 2020, sales in Asia were ___ than in Europe.","subSkill":"comparison_in_data_description","explanation":"图表描述中常用副词（significantly）修饰比较级（higher），表示程度差异较大。higher 是 high 的比较级，与 than 搭配。","instruction":"选择正确选项完成图表描述句子。","correctIndex":0},{"type":"choice","options":["more fast","faster","more faster","fastest"],"sentence":"The economy grew ___ in 2019 than in 2018.","subSkill":"comparative_adverbs","explanation":"fast 是单音节副词，比较级直接加 -er，构成 faster than，不需要 more。more faster 是双重比较，是语法错误。","instruction":"选择正确的比较级副词形式完成句子。","correctIndex":1},{"type":"choice","options":["the highest","higher","the most high","more high"],"sentence":"Mount Everest is ___ mountain on Earth.","subSkill":"superlative_adjectives","explanation":"在所有山峰中珠穆朗玛峰最高，用最高级 the highest。high 是单音节词，最高级形式为 the highest，不用 the most high。","instruction":"选择正确选项完成句子。","correctIndex":0},{"type":"choice","options":["as well","as good","as better","as best"],"sentence":"She speaks English ___ as her brother.","subSkill":"as_as_structures","explanation":"as...as 结构中间填副词原级来修饰动词 speaks，well 是 good 的副词形式，表示'她英语说得和她兄弟一样好'。","instruction":"选择正确选项完成句子。","correctIndex":0},{"type":"choice","options":["far lower","far lowest","far low","far more lower"],"sentence":"The proportion of car users was ___ in 1990 than in 2010.","subSkill":"comparison_in_data_description","explanation":"far 修饰比较级 lower，表示差距很大。far + 比较级是图表描述中表达显著差异的常见句型，lower 是 low 的正确比较级形式。","instruction":"选择正确选项完成图表描述句子。","correctIndex":0}],"2":[{"type":"choice","options":["more","much more","the most","most"],"sentence":"This year's report is ___ detailed than last year's.","subSkill":"comparative_adjectives","explanation":"detailed 是多音节形容词，比较级用 more detailed。much 可以加强比较级程度，表示'详细得多'。the most 是最高级，不与 than 搭配。","instruction":"选择正确选项完成句子。","correctIndex":1},{"type":"fill","sentence":"The second machine operates (efficiently) ___ than the first one.","subSkill":"comparative_adverbs","explanation":"efficiently 是多音节副词，比较级用 more + 原形，即 more efficiently，与 than 连用比较两台机器的运转效率。","instruction":"用括号中词的正确比较级副词形式填空。","acceptableAnswers":["more efficiently"]},{"type":"choice","options":["as high as","as higher as","so high than","as high than"],"sentence":"The unemployment rate in City A was almost ___ in City B throughout the decade.","subSkill":"as_as_structures","explanation":"as...as 结构表示程度相近，格式为 as + 形容词原级 + as，almost as high as 表示'几乎和……一样高'，是图表描述中表达近似值的常用表达。","instruction":"选择正确选项完成图表描述句子。","correctIndex":0},{"type":"fill","sentence":"Of all the countries surveyed, Japan had (low) ___ birth rate.","subSkill":"superlative_adjectives","explanation":"在所有被调查国家中比较，用最高级。low 是单音节词，最高级为 the lowest，表示日本的出生率在所有国家中最低。","instruction":"用括号中词的最高级形式填空。","acceptableAnswers":["the lowest"]},{"type":"fill","sentence":"Revenue in Q3 rose (considerably / sharp) ___ ___ than in Q2.","subSkill":"comparison_in_data_description","explanation":"图表描述中 considerably 修饰后面的比较级；sharply 是副词，其比较级为 more sharply，与 than 搭配说明 Q3 收入增速比 Q2 快得多。","instruction":"用括号中词的正确比较级形式填空，完成图表描述。","acceptableAnswers":["considerably","more sharply"]},{"type":"choice","options":["as / as","more / than","so / as","as / than"],"sentence":"The results in 2023 were twice ___ impressive ___ those in 2022.","subSkill":"as_as_structures","explanation":"倍数比较结构为：倍数词 + as + 形容词/副词原级 + as，表示'是……的两倍'，因此填 as...as。","instruction":"选择正确选项，完成含 as...as 的句子。","correctIndex":0},{"type":"fill","sentence":"Among the five candidates, she performed (well) ___ by far.","subSkill":"comparative_adverbs","explanation":"by far 强调最高程度，需搭配最高级。well 的最高级是 the best，表示'她的表现是五位候选人中迄今最好的'。","instruction":"用括号中词的正确比较级或最高级形式填空。","acceptableAnswers":["the best"]},{"type":"fill","sentence":"No other city in the survey was as expensive as Tokyo. → Tokyo was ___ ___ city in the survey.","subSkill":"superlative_adjectives","explanation":"no other...as...as 结构可改写为最高级：no other city was as expensive as Tokyo 等于 Tokyo was the most expensive city。这是图表描述中常见的改写方式。","instruction":"根据句意，用正确形式填空（改写句子，保持意思不变）。","acceptableAnswers":["the most expensive"]}],"3":[{"type":"fill","sentence":"The data shows that renewable energy grew (rapid) ___ in 2022 than in any previous year.","subSkill":"comparative_adverbs","explanation":"rapidly 是多音节副词，比较级用 more rapidly，修饰动词 grew，说明可再生能源在 2022 年的增速比以往任何一年都快。","instruction":"用括号中词的正确形式填空，完成图表描述句子。","acceptableAnswers":["more rapidly"]},{"type":"reorder","words":["the","figure","2015","was","in","significantly","higher","in","than","2010"],"subSkill":"comparison_in_data_description","explanation":"图表描述句型：主语（the figure in 2015）+ 系动词（was）+ 程度副词（significantly）+ 比较级形容词（higher）+ than + 比较对象（in 2010）。","instruction":"将下列词语排列成正确的句子，描述图表数据。","correctSentence":"The figure in 2015 was significantly higher than in 2010."},{"type":"fill","sentence":"Petrol cars are more polluting than electric cars. → Electric cars are not ___ ___ petrol cars.","subSkill":"as_as_structures","explanation":"A is more...than B 可改写为 B is not as...as A。因此 electric cars are not as polluting as petrol cars，两句意思相同，强调电动车污染程度不及燃油车。","instruction":"改写句子，使用 not as...as 结构，保持意思不变。","acceptableAnswers":["as polluting as"]},{"type":"reorder","words":["recorded","2018","the","highest","the","decade","in","level","of","exports"],"subSkill":"superlative_adjectives","explanation":"正确语序：主语（2018）+ 动词（recorded）+ 最高级短语（the highest level of exports）+ 范围说明（in the decade）。the highest 修饰 level，构成最高级名词短语。","instruction":"将下列词语排列成正确的最高级句子，用于图表描述。","correctSentence":"2018 recorded the highest level of exports in the decade."},{"type":"fill","sentence":"Of the three economic sectors, manufacturing experienced (dramatic) ___ decline.","subSkill":"superlative_adjectives","explanation":"dramatic 是多音节形容词，最高级用 the most dramatic，在三个部门中比较，制造业的下降最为剧烈，符合最高级使用条件。","instruction":"用括号中词的正确最高级形式填空。","acceptableAnswers":["the most dramatic"]},{"type":"reorder","words":["nearly","in","Spain","as","was","production","France","high","as","in"],"subSkill":"as_as_structures","explanation":"as...as 结构：主语（production in Spain）+ 系动词（was）+ 程度修饰（nearly）+ as + 形容词原级（high）+ as + 比较对象（in France）。nearly 表示'几乎'，与 as...as 搭配表达程度接近。","instruction":"将下列词语排列成正确的 as...as 比较句子。","correctSentence":"Production in Spain was nearly as high as in France."},{"type":"fill","sentence":"The 2023 figures are far (good) ___ than anyone predicted, making it (successful) ___ year on record.","subSkill":"comparative_adjectives","explanation":"第一空：good 的比较级是 better（不规则变化），far 加强比较级；第二空：on record 表明在所有记录中比较，用最高级 the most successful（多音节形容词）。","instruction":"根据括号提示用正确比较结构填空（每空一词）。","acceptableAnswers":["better","the most successful"]},{"type":"reorder","words":["urban","rural","areas","declined","population","more","in","rapidly","than","in","areas"],"subSkill":"comparative_adverbs","explanation":"注意：正确句序为主语（urban population）+ 动词（declined）+ 比较级副词短语（more rapidly）+ 地点状语（in ... than in rural areas）。more rapidly 修饰 declined，描述城市人口下降速度比农村更快。","instruction":"将下列词语排列成正确句子，使用比较级副词描述变化趋势。","correctSentence":"Urban population declined more rapidly in than in rural areas."},{"type":"fill","sentence":"In 2000, Country A produced three times more steel than Country B. → In 2000, Country A produced ___ ___ ___ steel ___ Country B.","subSkill":"as_as_structures","explanation":"倍数 + as much as 是表示数量倍数比较的标准结构，three times as much steel as Country B 表示'是 B 国的三倍'。注意 much 修饰不可数名词 steel，此处 as much as 合并填入一空作为整体结构的核心部分。","instruction":"改写下列句子，使用倍数 as...as 结构，保持意思不变。","acceptableAnswers":["three times as much as"]}],"4":[{"type":"choice","options":["more high","higher","more higher","highest"],"sentence":"The 2023 sales figures were significantly ___ than those recorded in 2022, rising from 4.2 million to 6.8 million units.","subSkill":"comparative_adjectives","explanation":"单音节形容词 high 的比较级直接加 -er，构成 higher；than 之前用比较级而非最高级；more higher 是双重比较，属于语法错误。","instruction":"选择正确的比较级形式完成句子。","correctIndex":1},{"type":"choice","options":["a higher","the highest","the most high","a most high"],"sentence":"Among the five countries surveyed, Japan had ___ proportion of elderly residents, at 28.4%.","subSkill":"superlative_adjectives","explanation":"最高级用于三者及以上的比较（五个国家），且最高级前需加定冠词 the；单音节词 high 的最高级形式为 highest，而非 most high。","instruction":"选择正确的最高级形式完成句子。","correctIndex":1},{"type":"choice","options":["more rapidly","more rapid","rapidlier","most rapidly"],"sentence":"After the policy change in 2019, the population of the city grew ___ than it had in the previous decade.","subSkill":"comparative_adverbs","explanation":"副词 rapidly 的比较级需借助 more 构成，因为多音节副词不能直接加 -er；than 之前使用比较级，排除 most rapidly。","instruction":"选择正确的比较副词形式完成句子。","correctIndex":0},{"type":"fill","sentence":"In 2020, online shopping was nearly three times (popular) ___ than in-store shopping among consumers aged 18 to 30.","subSkill":"comparative_adjectives","explanation":"多音节形容词 popular 的比较级用 more popular；than 前使用比较级形式，且 three times 倍数结构要求比较级而非最高级。","instruction":"用括号中词语的正确形式填空，完成图表描述句子。","acceptableAnswers":["more popular"]},{"type":"fill","sentence":"The data show that renewable energy expanded (fast) ___ of all energy sources between 2010 and 2020.","subSkill":"comparative_adverbs","explanation":"of all 表示在所有能源类别中进行比较，属于最高级语境；副词 fast 的最高级为 fastest（单音节直接加 -est）。","instruction":"用括号中词语的正确形式填空，完成图表描述句子。","acceptableAnswers":["fastest"]},{"type":"fill","sentence":"Carbon emissions in 2015 were 340 million tonnes. Carbon emissions in 2005 were also 340 million tonnes. In 2015, carbon emissions were (equal level, use as...as) ___ in 2005.","subSkill":"as_as_structures","explanation":"两个年份排放量相同，用 as...as 表示相等程度；完整结构为 as high as those in 2005，其中 those 指代 carbon emissions，避免重复。","instruction":"根据括号中的提示，用 as...as 结构完成句子，使句意不变。","acceptableAnswers":["as high as those"]},{"type":"error","words":["Transport","costs","in","City","A","were","more","cheaper","than","in","City","B","in","2018."],"subSkill":"comparative_adjectives","correction":"cheaper","errorIndex":7,"explanation":"cheap 是单音节形容词，比较级直接加 -er 构成 cheaper；more cheaper 是双重比较，属于语法错误，应删去 more，只保留 cheaper。","instruction":"下列句子中有一处语法错误，找出并改正。"},{"type":"error","words":["The","chart","shows","that","agriculture","was","the","most","largest","sector","in","terms","of","water","usage."],"subSkill":"superlative_adjectives","correction":"largest","errorIndex":8,"explanation":"large 是单音节形容词，最高级为 largest；most largest 是双重最高级，属于语法错误，应删去 most，只保留 largest。","instruction":"下列句子中有一处语法错误，找出并改正。"}],"5":[{"type":"fill","sentence":"The proportion of households owning a car in 2000 was (low) ___ than it became by 2020, when it reached an all-time high of 82%.","subSkill":"comparative_adjectives","explanation":"than 表明此处需要比较级；low 为单音节形容词，比较级直接加 -er 构成 lower；all-time high 确认 2020 年比 2000 年高，方向一致。","instruction":"用括号中词语的正确形式填空，完成雅思图表描述。","acceptableAnswers":["lower"]},{"type":"fill","sentence":"Spending on healthcare in 2010 was 5% of GDP. Spending on education in 2010 was also 5% of GDP. Spending on healthcare in 2010 was ___ spending on education.","subSkill":"as_as_structures","explanation":"两项支出比例相同，用 as + 形容词 + as 表示相等；完整结构为 as high as，修饰百分比数值，表示程度相同而非数量完全相同。","instruction":"保持句意不变，用 as...as 结构改写句子，填入所缺内容。","acceptableAnswers":["as high as"]},{"type":"reorder","words":["the","fastest","growing","sector","was","technology","of","all","industries","surveyed"],"subSkill":"superlative_adjectives","explanation":"最高级 fastest 修饰 growing sector，of all industries surveyed 表示比较范围；主语 technology 置于句首，was 作系动词连接主语和最高级表语。","instruction":"将下列词语排列成一个描述图表数据的正确句子。","correctSentence":"Technology was the fastest growing sector of all industries surveyed."},{"type":"choice","options":["The urban population in 2020 was more higher than in 2000.","The urban population in 2020 was considerably higher than it had been in 2000.","The urban population in 2020 was the highest than in 2000.","The urban population was as higher as possible in 2020."],"sentence":"Between 2000 and 2020, the urban population increased from 45% to 71%. Which sentence describes this trend most accurately using a comparison structure?","subSkill":"comparison_in_data_description","explanation":"选项B正确：considerably higher than 是规范比较级结构，it had been 用过去完成时呼应时间对比，语法和逻辑均正确；A含双重比较错误；C将最高级与 than 混用；D的 as higher as 结构错误。","instruction":"选择最符合图表描述规范的句子。","correctIndex":1},{"type":"error","words":["By","2025,","electric","vehicles","are","predicted","to","outsell","petrol","cars","by","more","than","twice","as","many","as","before."],"subSkill":"as_as_structures","correction":"more than","errorIndex":13,"explanation":"倍数比较结构应为 more than twice as many as，此处 twice 已包含倍数含义，整个短语 more than twice as many as 是正确的强调表达；句中 twice 与 as many as 需连用，中间不能插入额外成分打断结构。实际错误在于 twice as many as 是固定结构，more than 应置于 twice 前，即 more than twice as many as，本句结构已正确，但 twice 与 as 之间不能单独拆分。本题关注点为固定倍数比较句型的整体运用。","instruction":"下列图表描述句子中有一处语法错误，找出并改正。"},{"type":"fill","sentence":"Of all the transport methods tracked from 2000 to 2020, cycling grew (steadily) ___, increasing by an average of 8% per year without any significant decline.","subSkill":"comparative_adverbs","explanation":"of all 表明是在所有交通方式中进行比较，需要使用最高级；副词 steadily 为多音节词，最高级形式为 most steadily。","instruction":"用括号中副词的正确比较级或最高级形式填空，完成图表描述。","acceptableAnswers":["most steadily"]},{"type":"reorder","words":["almost","twice","as","high","as","the","figure","for","2010","the","2020","unemployment","rate","was"],"subSkill":"as_as_structures","explanation":"倍数 as...as 结构：twice as high as 表示两倍高；almost 修饰 twice 表示近似；主语 the 2020 unemployment rate 置于句首，was 作系动词。","instruction":"将下列词语排列成一个完整且符合语法的图表描述句子。","correctSentence":"The 2020 unemployment rate was almost twice as high as the figure for 2010."},{"type":"fill","sentence":"In 1990, the literacy rate was 60%. By 2020, it had risen to 95%. (Use a comparative structure with a quantifier) The literacy rate in 2020 was ___ than it had been in 1990.","subSkill":"comparison_in_data_description","explanation":"图表描述中比较两个时间点的数据时，使用 quantifier + comparative adjective + than 的结构；significantly / considerably / much / far / substantially 等均可修饰比较级，表示差距显著；it had been 用过去完成时指代更早的时间点。","instruction":"保持句意不变，根据括号提示完成第二句，使其使用 comparison_in_data_description 中的规范表达。","acceptableAnswers":["significantly higher","considerably higher","much higher","far higher","substantially higher"]}]},"mission":{"title":"描述图表中的比较数据","scenario":"假设你正在完成一篇雅思学术写作 Task 1。图表显示：2020 年，中国的可再生能源使用量最高，德国次之，巴西最低；但巴西的增长速度最快，德国增长速度最慢。请用至少三种不同的比较结构（比较级形容词、最高级、as...as 或比较级副词）写出 3-4 句描述性句子，准确反映图表中的数据关系。","scaffolds":[{"hint":"用最高级形容词描述中国的可再生能源使用量在三国中的排名。","prefix":"In 2020, China had","suffix":"of the three countries.","example":"In 2020, China had the highest level of renewable energy use of the three countries.","grammarCheck":"superlative_adjectives"},{"hint":"用 not as...as 结构说明巴西的使用量不及某国，再用比较级副词说明其增速。","prefix":"Although Brazil used","suffix":"it grew more rapidly than any other country.","example":"Although Brazil used far less renewable energy than China, it grew more rapidly than any other country.","grammarCheck":"as_as_structures"},{"hint":"用比较级副词或最高级副词描述德国的增长速度与其他国家相比是最慢的。","prefix":"Germany's growth rate was","suffix":"in the period.","example":"Germany's growth rate was considerably slower than Brazil's and was the lowest of the three in the period.","grammarCheck":"comparative_adverbs"}],"description":"在雅思写作 Task 1 中，准确使用比较结构是获得高分的关键。本任务要求你运用本单元学习的比较句型，描述一张关于三个国家能源使用情况的模拟柱状图数据。","grammarType":"comparison_in_data_description"},"discover":{"tip":"【比较结构核心讲解】\n\n**1. 比较级形容词 vs 比较级副词**\n- 比较级形容词修饰名词或接在系动词后：Dubai is hotter than London.（hot → hotter）\n- 比较级副词修饰动词，描述动作的方式或程度：Prices rose more sharply than expected.（sharply → more sharply）\n- 常见错误：混用形容词和副词，如误写 'rose more sharp'（应为 more sharply）。\n\n**2. 最高级：-est vs the most**\n- 单音节/双音节词通常加 -est：the coldest, the highest\n- 多音节词用 the most：the most significant, the most effective\n- 常见错误：双重比较，如误写 'the most coldest'（只能选一种形式）。\n\n**3. as...as 结构**\n- 肯定：London is almost as rainy as Reykjavik.（程度相近）\n- 否定：London is not as cold as Reykjavik.（A 的程度不及 B）\n- 常见错误：否定句中误用 more，如 'London is not more cold as Reykjavik'（应用 as...as）。\n\n**4. 图表描述常用搭配**\n- significantly / considerably / slightly / far + 比较级，用于精确表达差异大小，是雅思写作高分句型。","story":{"text":"A geography student named Li Wei recently compared the climates of three cities: London, Dubai, and Reykjavik. He found that London is wetter than Dubai but much drier than Reykjavik. Dubai is hotter than both other cities, recording the highest average temperature of the three. Reykjavik, on the other hand, is the coldest city in the group and receives the most rainfall annually. Li Wei also noted that temperatures in Dubai rise more sharply in summer than in London. Interestingly, London is not as cold as Reykjavik in winter, but it is almost as rainy. When Li Wei presented his findings, he said that Dubai was significantly warmer than London and that Reykjavik was by far the most extreme in terms of cold weather. He also observed that London grew more polluted than Reykjavik over the last century, though London now handles pollution far more effectively than it did before. Li Wei concluded that no city in his study was as consistently mild as he had initially expected London to be, and he planned to investigate more cities the following year.","title":"Three Cities, Three Climates","highlights":["wetter than","much drier than","hotter than","the highest","the coldest","the most rainfall","more sharply than","not as cold as","almost as rainy","significantly warmer than","the most extreme","more effectively than"]},"questions":[{"options":["as...as structure","superlative adjective","comparative adverb (more sharply than)","comparative adjective with -er"],"question":"In the story, which structure is used to say Dubai's temperature rises faster than London's in summer?","explanation":"句子 'temperatures in Dubai rise more sharply in summer than in London' 用副词比较级 more sharply than 来修饰动词 rise，说明动作发生的程度差异，这是比较副词结构。","correctIndex":2},{"options":["Dubai is hotter than both other cities.","London is not as cold as Reykjavik in winter.","Reykjavik is the coldest city in the group.","London grew more polluted than Reykjavik."],"question":"Which sentence from the story uses an as...as structure to show similarity?","explanation":"'London is not as cold as Reykjavik' 使用了 not as...as 结构，表示两者之间的程度差异——伦敦的寒冷程度不及雷克雅未克，这是 as...as 句型的否定形式。","correctIndex":1},{"options":["It uses a comparative adjective (-er form).","It uses a superlative adjective (the most + noun).","It uses an as...as structure.","It uses a comparative adverb."],"question":"How does the story express that Reykjavik has more rainfall than the other two cities?","explanation":"'receives the most rainfall' 使用了最高级结构 the most + 名词，表示在所有比较对象中降雨量最多，是最高级在数据描述中的典型用法。","correctIndex":1}]}},"9":{"levels":{"1":[{"type":"choice","options":["Because","Although","When","So that"],"sentence":"___ the bell rang, the students ran out of the classroom.","subSkill":"time_clauses","explanation":"'When' 引导时间状语从句，表示'当...的时候'，符合句意。","instruction":"选择正确的连接词完成时间状语从句。","correctIndex":2},{"type":"choice","options":["although","because","so that","as soon as"],"sentence":"She wore a coat ___ it was very cold outside.","subSkill":"reason_clauses","explanation":"'because' 引导原因状语从句，表示穿外套的原因是外面很冷。","instruction":"选择正确的连接词完成原因状语从句。","correctIndex":1},{"type":"choice","options":["Because","When","Although","So that"],"sentence":"___ he was tired, he continued working.","subSkill":"concession_clauses","explanation":"'Although' 引导让步状语从句，表示'尽管'，说明尽管疲惫他仍然继续工作。","instruction":"选择正确的连接词完成让步状语从句。","correctIndex":2},{"type":"choice","options":["because","although","when","so that"],"sentence":"She studied hard ___ she could pass the exam.","subSkill":"purpose_clauses","explanation":"'so that' 引导目的状语从句，表示她努力学习的目的是通过考试。","instruction":"选择正确的连接词完成目的状语从句。","correctIndex":3},{"type":"choice","options":["very","too","so","such"],"sentence":"The bag was ___ heavy that she could not carry it.","subSkill":"result_clauses","explanation":"'so + 形容词 + that' 是结果状语从句的固定结构，表示'如此...以至于...'。","instruction":"选择正确的连接词完成结果状语从句。","correctIndex":2},{"type":"choice","options":["Although","While","Because","So that"],"sentence":"___ I was cooking, my brother was watching TV.","subSkill":"time_clauses","explanation":"'While' 引导时间状语从句，表示两个动作同时发生，'当...的时候'。","instruction":"选择正确的连接词完成时间状语从句。","correctIndex":1},{"type":"choice","options":["Although","Since","So that","When"],"sentence":"___ it was raining, we decided to stay indoors.","subSkill":"reason_clauses","explanation":"'Since' 可以引导原因状语从句，表示'既然/由于'，说明留在室内的原因。","instruction":"选择正确的连接词完成原因状语从句。","correctIndex":1},{"type":"choice","options":["Although","Because","As soon as","So that"],"sentence":"___ she arrives, please tell her to call me.","subSkill":"time_clauses","explanation":"'As soon as' 引导时间状语从句，表示'一...就...'，强调动作发生的即时性。","instruction":"选择正确的连接词完成时间状语从句。","correctIndex":2}],"2":[{"type":"choice","options":["because","although","so that","while"],"sentence":"Tom spoke quietly ___ he would not wake the baby.","subSkill":"purpose_clauses","explanation":"'so that' 引导目的状语从句，Tom 轻声说话的目的是不吵醒婴儿。","instruction":"选择正确的连接词，注意从句类型。","correctIndex":2},{"type":"fill","sentence":"The movie was ___ boring that most people fell asleep.","subSkill":"result_clauses","explanation":"'so boring that' 是结果状语从句结构，'so + 形容词 + that' 表示结果。","instruction":"用括号中的连接词填写适当的从句连接词。","acceptableAnswers":["so"]},{"type":"choice","options":["Even though","Because","So that","When"],"sentence":"___ even though it rained all day, the children played outside.","subSkill":"concession_clauses","explanation":"'Even though' 引导让步状语从句，比 'although' 语气更强，表示'即使'。","instruction":"选择正确的连接词完成让步从句。","correctIndex":0},{"type":"fill","sentence":"___ the lesson ended, the students quickly packed their bags.","subSkill":"time_clauses","explanation":"时间状语从句可用 'when'、'as soon as'、'after' 等连接词，表示课结束后学生立刻收拾书包。","instruction":"用合适的连接词填空，完成时间状语从句。","acceptableAnswers":["When","As soon as","After"]},{"type":"fill","sentence":"___ she had never been to Beijing before, everything looked new and exciting.","subSkill":"reason_clauses","explanation":"'Because'、'Since'、'As' 都可引导原因状语从句，说明一切看起来新奇的原因。","instruction":"用合适的连接词填空，完成原因状语从句。","acceptableAnswers":["Because","Since","As"]},{"type":"choice","options":["so","a","very","too"],"sentence":"It was such ___ long journey that we were all exhausted.","subSkill":"result_clauses","explanation":"'such a + 形容词 + 名词 + that' 也是结果从句结构，注意与 'so + 形容词 + that' 的区别。","instruction":"选择正确答案完成结果状语从句。","correctIndex":1},{"type":"fill","sentence":"___ the test was difficult, Lisa managed to get a good score.","subSkill":"concession_clauses","explanation":"'Although'、'Even though'、'Though' 都可引导让步从句，表示尽管考试难，Lisa 还是考得不错。","instruction":"用合适的连接词填空，完成让步状语从句。","acceptableAnswers":["Although","Even though","Though"]},{"type":"fill","sentence":"He saved money for months ___ he could buy a new laptop.","subSkill":"purpose_clauses","explanation":"'so that' 引导目的状语从句，表示他存钱数月的目的是买一台新笔记本电脑。","instruction":"用合适的连接词填空，完成目的状语从句。","acceptableAnswers":["so that"]}],"3":[{"type":"fill","sentence":"___ (while/because) he was studying abroad, he learned to cook for himself.","subSkill":"time_clauses","explanation":"'While' 引导时间状语从句，表示两件事同时发生，'在他留学期间'。'because' 表原因，不符合句意。","instruction":"用括号中的词语填写正确的连接词，完成时间状语从句。","acceptableAnswers":["While"]},{"type":"reorder","words":["she","because","stayed","home","was","she","ill"],"subSkill":"reason_clauses","explanation":"原因状语从句 'because she was ill' 放在主句之后，说明留在家里的原因。","instruction":"将以下单词重新排列，组成一个含有原因状语从句的正确句子。","correctSentence":"She stayed home because she was ill."},{"type":"fill","sentence":"The music was ___ loud ___ we had to shout to hear each other.","subSkill":"result_clauses","explanation":"'so + 形容词 + that' 构成结果状语从句，表示'音乐如此之响，以至于我们必须大喊才能听到对方说话'。","instruction":"用 'so...that' 结构填写，使句子表达结果关系。","acceptableAnswers":["so","that"]},{"type":"reorder","words":["went","although","tired","she","jogging","was","she"],"subSkill":"concession_clauses","explanation":"让步状语从句 'Although she was tired' 放在句首，后接主句，注意从句放在句首时主句前有逗号。","instruction":"将以下单词重新排列，组成一个含有让步状语从句的正确句子。","correctSentence":"Although she was tired, she went jogging."},{"type":"reorder","words":["left","early","so","that","miss","he","not","he","would","the","bus"],"subSkill":"purpose_clauses","explanation":"目的状语从句 'so that he would not miss the bus' 表示早出发的目的是不错过公交车，常与 'would/could' 搭配。","instruction":"将以下单词重新排列，组成一个含有目的状语从句的正确句子。","correctSentence":"He left early so that he would not miss the bus."},{"type":"fill","sentence":"___ he had studied hard, he failed the exam.","subSkill":"concession_clauses","explanation":"句意为'尽管他努力学习，他还是没通过考试'，需要让步连接词 'although/even though/though'，而非原因连接词。","instruction":"用合适的连接词填空，注意区分原因和让步从句。","acceptableAnswers":["Although","Even though","Though"]},{"type":"reorder","words":["soon","as","as","I","will","you","call","finish","I"],"subSkill":"time_clauses","explanation":"'as soon as' 引导时间状语从句，表示'一...就...'。注意时间从句中用一般现在时代替将来时。","instruction":"将以下单词重新排列，组成一个含有时间状语从句的正确句子。","correctSentence":"I will call you as soon as I finish."},{"type":"fill","sentence":"It was ___ a wonderful concert ___ everyone cheered at the end.","subSkill":"result_clauses","explanation":"'such a + 形容词 + 名词 + that' 是结果从句的另一种结构，意为'如此精彩的音乐会，以至于所有人在最后都欢呼起来'。","instruction":"用 'such...that' 结构填空，完成结果状语从句。","acceptableAnswers":["such","that"]}],"4":[{"type":"error","words":["Because","she","was","talented",",","although","she","won","the","prize"],"subSkill":"reason_clauses","correction":"she","errorIndex":5,"explanation":"句子已经有 'Because' 引导原因从句，不能再用 'although' 引导让步从句。正确句子应为：'Because she was talented, she won the prize.'","instruction":"找出句子中的错误并改正。"},{"type":"fill","sentence":"The teacher spoke slowly ___ the students could understand every word.","subSkill":"purpose_clauses","explanation":"'so that' 引导目的状语从句，表示老师说话慢的目的是让学生能理解每个词。","instruction":"用合适的连接词填空，注意时态和从句类型。","acceptableAnswers":["so that"]},{"type":"choice","options":["so that / that","so / that","such / that","very / that"],"sentence":"He ran ___ fast ___ nobody could catch him.","subSkill":"result_clauses","explanation":"'so + 副词 + that' 构成结果状语从句，'He ran so fast that nobody could catch him.' 表示他跑得如此快以至于没人能追上他。","instruction":"选择正确的句子结构，区分 'so that' 和 'so...that'。","correctIndex":1},{"type":"error","words":["Although","he","is","rich",",","but","he","is","not","happy"],"subSkill":"concession_clauses","correction":"he","errorIndex":5,"explanation":"'Although' 引导让步从句后，主句不能再用 'but'，这是中文思维的干扰。正确句子：'Although he is rich, he is not happy.'","instruction":"找出句子中的语法错误并改正。"},{"type":"fill","sentence":"___ (when/while) I arrived at the party, everyone was already dancing.","subSkill":"time_clauses","explanation":"'When I arrived' 表示在我到达派对的那一刻，用 'when' 引导时间点；'while' 用于表示持续动作。此处强调到达的时间点，选 'when'。","instruction":"用括号中正确的连接词填空，注意时态。","acceptableAnswers":["When"]},{"type":"error","words":["She","studied","hard","so","that","she","can","pass","the","exam"],"subSkill":"purpose_clauses","correction":"could","errorIndex":6,"explanation":"目的状语从句 'so that' 后面跟随过去时主句时，从句中的情态动词应用过去式 'could' 而非 'can'，保持时态一致。","instruction":"找出句子中的错误并改正。"},{"type":"fill","sentence":"___ she didn't like vegetables, she ate them anyway ___ her mother told her to.","subSkill":"concession_clauses","explanation":"第一空用 'although' 引导让步从句，第二空用 'because' 引导原因从句，表示'尽管她不喜欢蔬菜，她还是吃了，因为她妈妈让她吃'。","instruction":"用合适的连接词填空，完成含有让步和原因关系的复杂句。","acceptableAnswers":["Although","because"]},{"type":"error","words":["Since","the","weather","was","bad",",","we","went","out","anyway"],"subSkill":"concession_clauses","correction":"Although","errorIndex":0,"explanation":"'Since' 表示原因，而句意为'尽管天气不好，我们还是出去了'，表达让步关系，应使用 'Although'。","instruction":"找出句子中的语法错误并改正。"}],"5":[{"type":"fill","sentence":"___ the project deadline was approaching, the team worked through the night ___ they could finish on time.","subSkill":"purpose_clauses","explanation":"第一空用 'Because' 引导原因从句，第二空用 'so that' 引导目的从句，表示'因为项目截止日期临近，团队通宵工作以便能按时完成'。","instruction":"用合适的从句连接词填空，使句子表达完整、逻辑清晰。","acceptableAnswers":["Because","so that"]},{"type":"reorder","words":["even","though","had","she","practiced","for","months","she","was","so","nervous","that","forgot","she","her","lines"],"subSkill":"concession_clauses","explanation":"句子包含让步从句 'Even though she had practiced for months' 和结果从句 'so nervous that she forgot her lines'，注意两种从句的位置和结构。","instruction":"将以下单词重新排列，组成语法正确、逻辑清晰的复杂句。","correctSentence":"Even though she had practiced for months, she was so nervous that she forgot her lines."},{"type":"error","words":["When","I","will","arrive","tomorrow",",","I","will","call","you"],"subSkill":"time_clauses","correction":"arrive","errorIndex":2,"explanation":"时间状语从句中（when, as soon as, while 等引导），即使主句是将来时，从句也必须用一般现在时代替将来时。正确：'When I arrive tomorrow, I will call you.'","instruction":"找出句子中的语法或逻辑错误并改正。"},{"type":"choice","options":["Because","So that","Although","In order that"],"sentence":"___ he is the youngest on the team, he is the most experienced player.","subSkill":"concession_clauses","explanation":"句意为'尽管他是团队中最年轻的，他却是最有经验的球员'，表达让步关系，应使用 'Although'。'Because' 表原因，与句意相反。","instruction":"选择最准确的选项完成句子，注意语义细微差别。","correctIndex":2},{"type":"fill","sentence":"___ it was her first day at the new job, Sarah arrived early ___ she could make a good impression.","subSkill":"purpose_clauses","explanation":"第一空用 'Although' 引导让步从句（尽管是第一天），第二空用 'so that' 引导目的从句（为了给人留下好印象）。","instruction":"综合运用状语从句，填写合适的连接词完成段落。","acceptableAnswers":["Although","so that"]},{"type":"reorder","words":["since","he","missed","the","bus","he","was","so","late","that","his","boss","was","angry"],"subSkill":"result_clauses","explanation":"句子包含原因从句 'Since he missed the bus' 和结果从句 'so late that his boss was angry'，注意 'so + 形容词 + that' 的结果从句结构。","instruction":"将以下单词重排，组成含有两个状语从句的复杂句。","correctSentence":"Since he missed the bus, he was so late that his boss was angry."},{"type":"error","words":["She","whispered","so","that","not","disturb","the","sleeping","baby"],"subSkill":"purpose_clauses","correction":"as","errorIndex":4,"explanation":"'so that' 后面应接完整的主谓结构从句，如 'so that she would not disturb...'。若后接不定式，应用 'so as not to disturb the sleeping baby'。此处需要完整从句结构。","instruction":"找出句子中的错误并改正。注意从句类型与连接词的匹配。"},{"type":"fill","sentence":"The concert was ___ amazing ___ the audience refused to leave ___ it had ended.","subSkill":"result_clauses","explanation":"第一、二空构成结果从句 'so amazing that'；第三空用 'even though' 引导让步从句，表示'即使音乐会已经结束，观众还是不愿离开'。","instruction":"根据句意，用最合适的连接词填空，综合考查五类状语从句。","acceptableAnswers":["so","that","even though"]}]},"mission":{"title":"Write About a Challenge You Overcame","scenario":"想一想你生活中曾经面对的挑战——可以是考试、比赛、学习新技能，或者克服恐惧。用状语从句来描述事情的前因后果、转折和你的目的，让读者真正理解你的经历和感受。","scaffolds":[{"hint":"用让步从句描述你面对的困难或不利条件，然后说明你仍然做了什么决定。","prefix":"Although","suffix":", I decided to","example":"Although I was very nervous about the competition, I decided to participate anyway.","grammarCheck":"concession_clauses"},{"hint":"用原因从句解释你努力的原因，再用目的从句说明你的目标。","prefix":"Because / Since","suffix":", I worked hard so that I could","example":"Since I had very little time to prepare, I worked hard every day so that I could be ready for the challenge.","grammarCheck":"purpose_clauses"},{"hint":"用时间从句描述你成功的那一刻，再用结果从句表达你的强烈感受。","prefix":"When I finally","suffix":", I felt so ... that","example":"When I finally finished the race, I felt so proud that I started crying with joy.","grammarCheck":"result_clauses"}],"description":"写一篇100-150字的短文，描述你曾经克服的一个挑战或困难经历。要求使用至少三种不同类型的状语从句（时间、原因、结果、让步或目的从句），让文章逻辑更清晰、表达更丰富。","grammarType":"concession_clauses"},"discover":{"tip":"状语从句共有五大类：时间（when, while, as soon as），原因（because, since, as），结果（so...that），让步（although, even though），目的（so that, in order that）。注意：让步从句虽然说明了不利条件，但主句的动作仍然发生；结果从句常用 'so + 形容词/副词 + that' 结构。","story":{"text":"Although the weather was cold and rainy, Maria decided to visit her grandmother in the countryside. She left early in the morning so that she could arrive before noon. Because the train was delayed, she had to wait at the station for almost an hour. While she was waiting, she read a book and drank hot coffee. When the train finally arrived, she felt relieved and quickly found her seat. The journey was so long that she fell asleep halfway through. However, as soon as she saw her grandmother's house, she forgot all her tiredness. Since it was the first time she had visited in months, her grandmother had prepared a huge meal. Even though Maria was exhausted from the journey, she stayed up late talking and laughing with her family. She was so happy that she promised to come back again soon.","title":"A Journey Worth Taking","highlights":["Although","so that","Because","While","When","so...that","as soon as","Since","Even though"]},"questions":[{"options":["Because the train was early.","So that she could arrive before noon.","Although she was tired.","When her grandmother called her."],"question":"Why did Maria leave early in the morning?","explanation":"文中使用了目的状语从句 'so that she could arrive before noon'，表示她早出发的目的是为了在中午前到达。","correctIndex":1},{"options":["Because the train was delayed, she had to wait.","When the train finally arrived, she felt relieved.","Although the weather was cold and rainy, Maria decided to visit.","Since it was the first time, her grandmother prepared a huge meal."],"question":"Which sentence shows a concession clause?","explanation":"'Although the weather was cold and rainy' 是让步状语从句，表示尽管天气恶劣，Maria 仍然决定出发，体现了让步关系。","correctIndex":2},{"options":["The reason she forgot her tiredness.","The result of the long journey.","The exact time when something happened.","The purpose of her visit."],"question":"What does 'as soon as she saw her grandmother's house' tell us?","explanation":"'as soon as' 引导时间状语从句，表示'一...就...'，说明两个动作发生的时间先后关系，属于时间从句。","correctIndex":2}]}},"10":{"levels":{"1":[{"type":"choice","options":["is","was","were","be"],"sentence":"Direct: \"I am tired.\" → She said that she ___ tired.","subSkill":"tense_backshift","explanation":"间接引语时态回移：is → was。","instruction":"选择正确的间接引语形式","correctIndex":1},{"type":"choice","options":["that","what","if","which"],"sentence":"Direct: \"Do you like coffee?\" → He asked me ___ I liked coffee.","subSkill":"reported_questions","explanation":"一般疑问句变为间接引语时，用 if 或 whether 引导。","instruction":"选择正确的引导词","correctIndex":2},{"type":"choice","options":["will","would","shall","can"],"sentence":"Direct: \"We will help you.\" → They said that they ___ help me.","subSkill":"tense_backshift","explanation":"时态回移：will → would。","instruction":"选择正确的间接引语形式","correctIndex":1},{"type":"choice","options":["close","closed","to close","closing"],"sentence":"Direct: \"Close the door.\" → The teacher told the student ___ the door.","subSkill":"reported_commands","explanation":"间接命令句型：tell sb to do sth，用动词不定式。","instruction":"选择正确的间接命令形式","correctIndex":2},{"type":"choice","options":["can","could","may","might"],"sentence":"Direct: \"I can swim.\" → She said she ___ swim.","subSkill":"tense_backshift","explanation":"时态回移：can → could。","instruction":"选择正确的间接引语形式","correctIndex":1},{"type":"choice","options":["if","that","where","whether"],"sentence":"Direct: \"Where do you live?\" → She asked me ___ I lived.","subSkill":"reported_questions","explanation":"特殊疑问句变间接引语时，保留原来的疑问词 where。","instruction":"选择正确的引导词","correctIndex":2},{"type":"choice","options":["has finished","had finished","finished","have finished"],"sentence":"Direct: \"I have finished my work.\" → He said he ___ his work.","subSkill":"tense_backshift","explanation":"时态回移：现在完成时 has finished → 过去完成时 had finished。","instruction":"选择正确的动词形式","correctIndex":1},{"type":"choice","options":["don't run","not to run","not running","no running"],"sentence":"Direct: \"Don't run in the corridor.\" → The teacher warned the students ___ in the corridor.","subSkill":"reported_commands","explanation":"warn sb not to do sth，否定间接命令用 not to do。","instruction":"选择正确的报告动词搭配","correctIndex":1}],"2":[{"type":"choice","options":["is studying","was studying","studied","has studied"],"sentence":"Direct: \"I am studying English.\" → She said she ___ English.","subSkill":"tense_backshift","explanation":"时态回移：现在进行时 is studying → 过去进行时 was studying。","instruction":"选择正确的间接引语形式","correctIndex":1},{"type":"fill","sentence":"Direct: \"I went to Beijing last year.\" → He told me that he (go) ___ to Beijing the previous year.","subSkill":"tense_backshift","explanation":"时态回移：一般过去时 went → 过去完成时 had gone。","instruction":"用括号中动词的正确形式填空，完成间接引语","acceptableAnswers":["had gone"]},{"type":"choice","options":["said","told","spoke","talked"],"sentence":"Direct: \"Please sit down.\" → The teacher ___ the students to sit down.","subSkill":"reporting_verbs","explanation":"tell sb to do sth 是固定搭配，said 后不能直接跟人称宾语。","instruction":"选择正确的报告动词","correctIndex":1},{"type":"fill","sentence":"Direct: \"Are you coming to the party?\" → She asked me ___ I was coming to the party.","subSkill":"reported_questions","explanation":"一般疑问句变间接引语用 if 或 whether 引导。","instruction":"用适当的引导词填空","acceptableAnswers":["if","whether"]},{"type":"choice","options":["starts","started","has started","will start"],"sentence":"Direct: \"The meeting starts at nine.\" → He said that the meeting ___ at nine.","subSkill":"reported_statements","explanation":"时态回移：一般现在时 starts → 一般过去时 started。","instruction":"选择正确的间接陈述形式","correctIndex":1},{"type":"fill","sentence":"Direct: \"I will call you tomorrow.\" → She said she (call) ___ me the next day.","subSkill":"tense_backshift","explanation":"时态回移：will call → would call；tomorrow → the next day。","instruction":"用括号中动词的正确形式填空","acceptableAnswers":["would call"]},{"type":"choice","options":["told","explained","said to","spoke"],"sentence":"She ___ that she had left her keys at home.","subSkill":"reporting_verbs","explanation":"explain that 是正确搭配；said 后不能跟 that 时通常不接人称宾语；tell 后必须接人称宾语。","instruction":"选择正确的报告动词搭配","correctIndex":1},{"type":"fill","sentence":"Direct: \"Be quiet!\" → The librarian told everyone ___ quiet.","subSkill":"reported_commands","explanation":"间接命令：tell sb to do sth，be quiet → to be quiet。","instruction":"完成间接命令句","acceptableAnswers":["to be"]}],"3":[{"type":"fill","sentence":"Direct: \"We have been waiting for two hours.\" → They complained that they (wait) ___ for two hours.","subSkill":"tense_backshift","explanation":"时态回移：现在完成进行时 have been waiting → 过去完成进行时 had been waiting。","instruction":"将括号中的动词变为正确形式，完成间接引语句","acceptableAnswers":["had been waiting"]},{"type":"reorder","words":["asked","She","he","where","lived"],"subSkill":"reported_questions","explanation":"特殊疑问句间接引语：疑问词 where 引导，语序变为陈述句语序（主语 + 动词）。","instruction":"将以下单词排列成正确的间接引语句","correctSentence":"She asked where he lived."},{"type":"fill","sentence":"Direct: \"You should see a doctor.\" → She ___ him to see a doctor.","subSkill":"reporting_verbs","explanation":"建议某人做某事用 advise sb to do sth，warned 通常用于警告危险，不适合此语境。","instruction":"选择正确的报告动词并填入空白处（从 advised / warned / reminded / suggested 中选择）","acceptableAnswers":["advised","urged"]},{"type":"reorder","words":["told","had","The","manager","the","report","finished","she","that"],"subSkill":"reported_statements","explanation":"间接陈述句：主句 + that 从句，时态回移 finished → had finished。正确语序为主语 + 谓语 + 宾语 + that 从句。","instruction":"将以下单词排列成正确的间接引语句","correctSentence":"The manager told the report that she had finished."},{"type":"fill","sentence":"Direct: \"What time does the train leave?\" → He asked what time the train ___ .","subSkill":"reported_questions","explanation":"间接疑问句语序变为陈述句语序：does the train leave → the train left（时态回移）。","instruction":"完成间接问句，注意语序变化","acceptableAnswers":["left"]},{"type":"reorder","words":["not","us","in","warned","the","The","to","sign","guide","ignore"],"subSkill":"reported_commands","explanation":"否定间接命令：warn sb not to do sth，not 放在 to 之前。","instruction":"将以下单词排列成正确的间接命令句","correctSentence":"The guide warned us not to ignore the sign."},{"type":"fill","sentence":"She said the weather (be) ___ terrible yesterday but (be) ___ much better today.","subSkill":"tense_backshift","explanation":"第一个空：yesterday 指过去，时态回移 was → had been；第二个空：today 仍然适用，be 回移为 was。","instruction":"用括号中的动词正确形式填写两个空白","acceptableAnswers":["had been","was"]},{"type":"reorder","words":["whether","could","he","me","use","asked","He","laptop","my"],"subSkill":"reported_questions","explanation":"一般疑问句间接引语：用 whether 引导，语序变为陈述句语序，can → could（时态回移）。","instruction":"将以下单词排列成正确的句子","correctSentence":"He asked me whether he could use my laptop."}],"4":[{"type":"error","words":["She","said","me","that","she","was","tired"],"subSkill":"reporting_verbs","correction":"told","errorIndex":2,"explanation":"say 后面不能直接跟人称宾语，需要改为 tell：She told me that...。","instruction":"找出句中的错误并改正"},{"type":"fill","sentence":"Direct: \"I may not attend the conference.\" → He said that he ___ not attend the conference.","subSkill":"tense_backshift","explanation":"时态回移：may → might。","instruction":"将直接引语改写为间接引语，填写正确形式","acceptableAnswers":["might"]},{"type":"choice","options":["said","promised","suggested","warned"],"sentence":"Direct: \"I promise I will return the book.\" → He ___ to return the book.","subSkill":"reporting_verbs","explanation":"promise to do sth 是固定搭配，与直接引语中 I promise 对应，是报告承诺的正确动词。","instruction":"选择最合适的报告动词完成句子","correctIndex":1},{"type":"error","words":["He","asked","where","did","she","work"],"subSkill":"reported_questions","correction":"she","errorIndex":3,"explanation":"间接疑问句中语序应为陈述句语序，不用倒装：where she worked，去掉 did，动词加过去式。","instruction":"找出句中的错误并改正"},{"type":"fill","sentence":"Direct: Tom said, \"I have lost my phone.\" → Tom said that he ___ his phone.","subSkill":"tense_backshift","explanation":"时态回移：have lost → had lost；代词 I → he，my → his。","instruction":"完成间接引语，注意时态和代词变化","acceptableAnswers":["had lost"]},{"type":"error","words":["The","doctor","advised","him","not","eating","sugar"],"subSkill":"reported_commands","correction":"to eat","errorIndex":5,"explanation":"advise sb not to do sth 是固定结构，not 后面应接 to do，不用 -ing 形式。","instruction":"找出句中的错误并改正"},{"type":"choice","options":["this is","that was","this was","that is"],"sentence":"Direct: \"This is the best film I have ever seen.\" → She said that ___ the best film she had ever seen.","subSkill":"reported_statements","explanation":"间接引语中，this → that，is → was（时态回移），所以正确答案是 that was。","instruction":"选择正确的间接引语形式","correctIndex":1},{"type":"error","words":["She","told","that","she","would","come","early"],"subSkill":"reporting_verbs","correction":"us","errorIndex":2,"explanation":"tell 必须接人称宾语（tell sb that...），此处缺少宾语，应在 told 后加 us 或 him/her 等。","instruction":"找出句中的错误并改正"}],"5":[{"type":"fill","sentence":"Direct: \"I will finish the project, but I need more time.\" → He promised that he ___ finish the project but explained that he ___ more time.","subSkill":"tense_backshift","explanation":"两个从句都需要时态回移：will → would，need → needed。","instruction":"将整段直接引语改写为间接引语，填写两个空白","acceptableAnswers":["would","needed"]},{"type":"reorder","words":["long","how","she","had","been","waiting","wanted","to","know","He"],"subSkill":"reported_questions","explanation":"间接疑问句：how long 引导，陈述句语序 she had been waiting（时态回移：has been waiting → had been waiting）。","instruction":"将以下单词排列成正确的句子，注意间接引语语序","correctSentence":"He wanted to know how long she had been waiting."},{"type":"error","words":["The","professor","reminded","students","to","not","forget","the","deadline"],"subSkill":"reported_commands","correction":"not to","errorIndex":5,"explanation":"否定不定式的正确形式是 not to do，not 必须放在 to 之前：remind students not to forget。","instruction":"找出句中的错误并改正"},{"type":"choice","options":["warned","refused","urged","denied"],"sentence":"Direct: \"You really must try the local food here!\" → She ___ us to try the local food.","subSkill":"reporting_verbs","explanation":"urge sb to do sth 表示强烈建议或敦促，符合原句中强调语气（must）的含义。","instruction":"选择最符合语境的报告动词","correctIndex":2},{"type":"fill","sentence":"Direct: \"Why didn't you submit your essay on time?\" the tutor demanded. → The tutor demanded to know why I ___ my essay on time.","subSkill":"reported_questions","explanation":"间接疑问句中时态回移：didn't submit → hadn't submitted（过去完成时）；语序变为陈述句语序。","instruction":"将直接引语完整改写为间接引语","acceptableAnswers":["hadn't submitted","had not submitted"]},{"type":"reorder","words":["said","had","She","finished","that","she","report","the","but","that","needed","revising","it"],"subSkill":"reported_statements","explanation":"两个并列的 that 从句：that she had finished...but that it needed...，时态均已回移。","instruction":"将以下单词排列成正确的包含多个从句的间接引语句","correctSentence":"She said that she had finished the report but that it needed revising."},{"type":"error","words":["He","asked","if","I","can","lend","him","the","notes"],"subSkill":"tense_backshift","correction":"could","errorIndex":4,"explanation":"间接引语中时态回移：can → could，即使主句是 asked（过去时），从句中也需要相应回移。","instruction":"找出句中的错误并改正"},{"type":"fill","sentence":"The manager announced that the new policy (take) ___ effect the following month and (affect) ___ all departments.","subSkill":"tense_backshift","explanation":"时态回移：will take → would take，will affect → would affect；the following month 对应直接引语中的 next month。","instruction":"综合运用间接引语，将括号中词语填入正确位置","acceptableAnswers":["would take","would affect"]}]},"mission":{"title":"The IELTS Listening Summary","scenario":"你参加了一场关于城市交通问题的学术讨论会。会后，你需要向没有参加的同学转述三位专家的观点：①交通专家李教授说城市交通拥堵的主要原因是私家车数量增加；②市政规划师王女士建议市民多使用公共交通；③环保研究员张博士警告说如果不采取措施，空气质量将继续恶化。请用间接引语转述以上三人的观点。","scaffolds":[{"hint":"转述李教授的观点：城市交通拥堵的主要原因是私家车数量增加（注意时态回移：is → was，are → were）","prefix":"Professor Li, a transport expert, stated that","suffix":"","example":"Professor Li, a transport expert, stated that the main cause of urban traffic congestion was the increasing number of private cars.","grammarCheck":"tense_backshift"},{"hint":"转述王女士的建议：建议市民多使用公共交通（使用 advise sb to do sth 结构）","prefix":"Ms Wang, a city planner, advised","suffix":"instead of driving.","example":"Ms Wang, a city planner, advised residents to use public transport more frequently instead of driving.","grammarCheck":"reported_commands"},{"hint":"转述张博士的警告：如果不采取措施，空气质量将继续恶化（注意 will → would，continues → would continue）","prefix":"Dr Zhang warned that","suffix":"if immediate measures were not taken.","example":"Dr Zhang warned that air quality would continue to deteriorate if immediate measures were not taken.","grammarCheck":"reported_statements"}],"description":"在雅思听力和学术阅读中，常常需要用间接引语转述他人观点或研究结论。请根据以下场景，写一段80-120字的短文，转述三位人物的观点，正确使用间接引语、时态回移和多种报告动词。","grammarType":"reported_statements"},"discover":{"tip":"间接引语核心规则：①陈述句用 that 引导（可省略）；②一般疑问句用 if/whether 引导；③特殊疑问句保留疑问词；④命令/建议用 tell/advise/warn + sb + to do；⑤时态回移：一般现在→一般过去，现在进行→过去进行，一般过去→过去完成，will→would，can→could。","story":{"text":"Last Monday, Professor Chen told her students that the final assignment was due on Friday. She said that anyone who missed the deadline would lose ten marks. One student, David, asked her whether he could submit it a day late because his laptop had broken down. The professor replied that she would consider his request if he showed her proof of the repair. Later, David's classmate Emma warned him not to leave it too late. She reminded him that the professor had always been strict about deadlines in the past. David told Emma that he had already contacted the repair shop and that they had promised to return his laptop by Wednesday. Emma advised him to back up his files on a USB drive so that he would not lose his work again. In the end, David submitted his assignment on Thursday, and Professor Chen said that she was pleased with his effort. She announced to the class that David had handled a difficult situation very responsibly.","title":"The Missing Assignment","highlights":["told","said","asked","replied","warned","reminded","advised","announced","had broken","would consider","had always been","had already contacted"]},"questions":[{"options":["She said the assignment was due on Monday.","She told them the assignment was due on Friday.","She said that anyone who missed the deadline would get extra time.","She announced the assignment had been cancelled."],"question":"What did Professor Chen tell the students about the deadline?","explanation":"故事中提到 Professor Chen told her students that the final assignment was due on Friday，间接引语中动词时态回移，due 保持不变，因为它本身是形容词。","correctIndex":1},{"options":["He asked her if she could cancel the assignment.","He told her that he had forgotten about the deadline.","He asked whether he could submit it late because his laptop had broken down.","He said that he would not submit the assignment at all."],"question":"How did David explain his situation to the professor?","explanation":"David 提出的是一个间接疑问句，用 whether 引导，动词 broke 回移为 had broken，体现了时态回移规则。","correctIndex":2},{"options":["She advised him to ask the professor for an extension.","She told him to buy a new laptop immediately.","She advised him to back up his files on a USB drive.","She warned him that the professor would fail him."],"question":"What did Emma advise David to do?","explanation":"间接命令/建议句型：advise sb to do sth，Emma advised him to back up his files，不需要时态回移，动词不定式形式保持不变。","correctIndex":2}]}},"11":{"levels":{"1":[{"type":"choice","options":["However","As a result","Nevertheless","Despite this"],"sentence":"Tom studied very hard for the exam. ___, he passed with a high score.","subSkill":"cause_effect_linkers","explanation":"句子描述的是：努力学习 → 取得高分，这是明显的因果关系。'As a result' 表示'因此、结果'，用于引出由前因导致的结果。","instruction":"选择最合适的连接词填入空白处，注意句子之间的逻辑关系。","correctIndex":1},{"type":"choice","options":["Furthermore","Therefore","Nevertheless","In addition"],"sentence":"The weather was terrible. ___, hundreds of fans came to watch the match.","subSkill":"contrast_linkers","explanation":"'Nevertheless' 表示'尽管如此'，用于在承认前面不利情况的同时，引出出乎意料的结果（天气很差，但球迷仍然来了），体现对比转折关系。","instruction":"选择最合适的连接词，注意两个句子之间表达的是对比关系。","correctIndex":2},{"type":"choice","options":["However","Moreover","Because","Yet"],"sentence":"The new library has a large reading room. ___, it offers free Wi-Fi to all visitors.","subSkill":"additive_linkers","explanation":"'Moreover' 表示'而且、此外'，用于在前文信息的基础上补充更多相关的积极信息，属于添加关系连接词。","instruction":"选择最合适的连接词，使句子在逻辑上表示'补充添加'的关系。","correctIndex":1},{"type":"choice","options":["The drug companies","The scientists","The findings","Last week"],"sentence":"The scientists published their findings last week. They showed that the new drug was effective.","subSkill":"reference_devices","explanation":"'They' 是人称代词，在这里指代句子的主语 'The scientists'（科学家们），因为是科学家们发表了研究，逻辑上也是他们展示了这些发现。","instruction":"选择句中画线代词所指代的内容。","correctIndex":1},{"type":"choice","options":["because","because of","therefore","however"],"sentence":"The flight was cancelled ___ the heavy snowstorm.","subSkill":"cause_effect_linkers","explanation":"'because of' 后面接名词短语（the heavy snowstorm），而 'because' 后面必须接完整的句子（主语+动词）。这里 'the heavy snowstorm' 是名词短语，所以用 'because of'。","instruction":"选择正确的连接词，注意 because 和 because of 的区别。","correctIndex":1},{"type":"choice","options":["he","she","they","it"],"sentence":"The committee reviewed the proposal, and ___ decided to approve it unanimously.","subSkill":"reference_devices","explanation":"'the committee' 指的是一个由多人组成的委员会，作为一个集体名词在英式英语中通常用复数代词 'they' 来指代，因为强调的是成员们共同做出的决定。","instruction":"选择正确的代词填空，注意它所指代的名词。","correctIndex":2},{"type":"choice","options":["furthermore","on the other hand","as a result","in addition"],"sentence":"James finds mathematics easy. His sister, ___, struggles with it greatly.","subSkill":"contrast_linkers","explanation":"'on the other hand' 是对比性语篇标记词，用于对比两个不同的人、事物或观点。这里对比 James 和他姐姐在数学方面的不同表现，逻辑清晰。","instruction":"选择最能表示'对比'关系的连接词。","correctIndex":1}],"2":[{"type":"choice","options":["Despite","Because of","As a result of","Furthermore"],"sentence":"The company had serious financial problems. ___ this, it continued to invest in research.","subSkill":"contrast_linkers","explanation":"'Despite' 是介词，后接名词或名词短语（this），表示'尽管'，引出与预期相反的结果。不可以写 'Despite of'，这是常见错误。","instruction":"选择最合适的连接词，注意句子之间的逻辑关系。","correctIndex":0},{"type":"choice","options":["Therefore","That said","Moreover","Consequently"],"sentence":"Learning a second language takes a lot of time. ___, the rewards are absolutely worth the effort.","subSkill":"discourse_markers","explanation":"'That said' 是语篇标记词，意为'话虽如此'，用于承认前文的观点（学语言很费时）之后，转入补充正面观点（但值得）。它比 'However' 更能体现说话者平衡两方的态度。","instruction":"选择最合适的语篇标记词，使段落过渡自然。","correctIndex":1},{"type":"fill","sentence":"She had not slept well the night before. She ___ managed to deliver an excellent presentation. (nevertheless)","subSkill":"contrast_linkers","explanation":"'Nevertheless' 放在第二个句子中，通常置于主语之后、动词之前（She nevertheless managed...），表示'尽管如此'，引出与前文预期相反的积极结果。","instruction":"用括号中给出的连接词填空，注意其在句中的正确位置和用法。","acceptableAnswers":["nevertheless"]},{"type":"fill","sentence":"Scientists have discovered a new species of butterfly. ___ was found in a remote rainforest in Brazil.","subSkill":"reference_devices","explanation":"'It' 用来指代前文提到的 'a new species of butterfly'（一种新蝴蝶），是单数不可数或单数可数名词的指代代词，避免了重复，使语篇更连贯。","instruction":"用适当的指代词填空，使句子连贯，避免重复名词。","acceptableAnswers":["It"]},{"type":"choice","options":["however","therefore","moreover","in contrast"],"sentence":"The test results were inconclusive. The researchers ___ decided to conduct a second experiment.","subSkill":"cause_effect_linkers","explanation":"'Therefore' 表示因果关系中的'结果'——因为测试结果不确定，研究人员因此决定再做一次实验。这是一个合理的逻辑推断，用 'therefore' 最准确。","instruction":"选择正确的连接词，注意 'therefore' 与 'however' 表达不同的逻辑关系。","correctIndex":1},{"type":"fill","sentence":"The new sports centre provides excellent gym facilities. ___, it includes an Olympic-sized swimming pool.","subSkill":"additive_linkers","explanation":"这三个连接词都表示'此外、而且'，用于补充额外的相关信息。它们在此处可以互换使用，但均需放在句首并加逗号。注意：不能用 'Also' 替代，因为正式书面语中 Also 通常不单独放句首。","instruction":"用适当的添加关系连接词（Furthermore / Moreover / In addition）填空，使段落意思完整。","acceptableAnswers":["Furthermore","Moreover","In addition"]},{"type":"fill","sentence":"She arrived two hours late. This annoyed everyone at the meeting. → She arrived two hours late, ___ annoyed everyone at the meeting.","subSkill":"reference_devices","explanation":"'which' 在非限制性定语从句中可以指代前面整个句子的内容（她迟到了两小时这件事），而不仅仅是一个名词。这是 'which' 和 'that' 的重要区别——'that' 不能用于指代整件事。","instruction":"将下面的句子改写，用 'which' 引导非限制性定语从句，替代第二个句子，保持意思不变。","acceptableAnswers":["which"]},{"type":"choice","options":["After all","Above all","In spite of","On the contrary"],"sentence":"___, the most important factor in language learning is consistent daily practice.","subSkill":"discourse_markers","explanation":"'Above all' 意为'最重要的是'，用于强调最关键的一点，是常见的语篇标记词，帮助读者明确作者认为最重要的信息。'After all' 表示'毕竟'，含义不同。","instruction":"选择最合适的语篇标记词，注意它在段落中引导读者理解作者逻辑的功能。","correctIndex":1}],"3":[{"type":"fill","sentence":"Although the hotel was expensive, they decided to book it. (Despite) → Despite ___ of the hotel, they decided to book it.","subSkill":"contrast_linkers","explanation":"'Despite' 是介词，后面必须接名词或名词短语，不能接从句。'Although' 引导让步从句（Although it was expensive），改为 'Despite' 时需要将从句转化为名词短语，例如 'the high cost' 或 'the expense'。","instruction":"用括号中的词语改写句子，使新句子意思与原句相同，注意连接词与句子结构的搭配。","acceptableAnswers":["the high cost","the expense"]},{"type":"fill","sentence":"The government introduced a new recycling policy last year. ___ was praised by environmental groups. ___, many residents found ___ confusing and difficult to follow.","subSkill":"reference_devices","explanation":"第一空：'It' 指代前文的 'a new recycling policy'（单数名词，用 it）。第二空：'However' 引入转折，前文是受到好评，后文是居民觉得困惑，形成对比。第三空：'it' 再次指代该政策（the policy），保持指代连贯性。","instruction":"在空白处填入适当的指代词或连接词，使段落连贯通顺（每空一个词）。","acceptableAnswers":["It","However","it"]},{"type":"fill","sentence":"She trained for months. She failed to qualify for the finals. (in spite of) → In spite of ___, she failed to qualify for the finals.","subSkill":"contrast_linkers","explanation":"'In spite of' 与 'despite' 用法相同，后接名词短语而非从句。将 'She trained for months' 转化为名词短语，可以写成 'months of training' 或 'her months of training'，表达让步关系。","instruction":"用适当的连接词改写句子，保持意思不变。","acceptableAnswers":["months of training","training for months","her months of training"]},{"type":"fill","sentence":"There are two possible solutions to this problem. The first is to increase government funding. ___, we could encourage private investment through tax incentives.","subSkill":"discourse_markers","explanation":"'Alternatively' 或 'On the other hand' 用于引出第二个可选方案，表示'或者、另一方面'。这类语篇标记词帮助读者理解作者正在列举并列选项，而非补充信息（不用 Furthermore）或表示因果（不用 Therefore）。","instruction":"用一个合适的语篇标记词填空，使段落的逻辑过渡自然（填写一个完整的短语或单词）。","acceptableAnswers":["Alternatively","On the other hand"]},{"type":"fill","sentence":"Urban cycling has grown significantly in recent years. ___, many cities have invested in dedicated cycle lanes. ___, some drivers remain frustrated by the reduced road space. ___, the overall evidence suggests that cycling infrastructure benefits the entire community.","subSkill":"discourse_markers","explanation":"第一空：前句说骑行增长，后句说城市投资建设自行车道，是因果关系，用 'As a result'。第二空：后面引出司机的不满，与前文的积极发展形成对比，用 'However'。第三空：尽管有人不满，总体来说仍然有益，表示让步后的总结，用 'Nevertheless'。","instruction":"阅读下面的段落，在三个空白处分别填入最合适的连接词，使段落逻辑连贯（每空一个词或短语）。","acceptableAnswers":["As a result","However","Nevertheless"]}],"4":[{"type":"choice","options":["however","furthermore","nevertheless","otherwise"],"sentence":"The new policy reduced costs significantly; ___, it also improved employee satisfaction.","subSkill":"additive_linkers","explanation":"furthermore 表示递进关系，用于补充说明另一个同向的正面结果，与前半句的正面信息方向一致。however 和 nevertheless 表示转折，otherwise 表示否则，均不符合语境。","instruction":"选择最合适的连接词，使句子逻辑通顺。","correctIndex":1},{"type":"choice","options":["Therefore","In addition","Nonetheless","Consequently"],"sentence":"The report was thorough and well-researched. ___, the committee rejected it due to budget constraints.","subSkill":"contrast_linkers","explanation":"Nonetheless 表示\"尽管如此\"，引出与前文预期相反的结果——报告质量很高，但委员会仍拒绝了它，体现让步转折关系。","instruction":"选择最合适的对比连接词，使句子逻辑通顺。","correctIndex":2},{"type":"choice","options":["despite","as a result of","owing to","as a consequence of"],"sentence":"The river flooded after three days of heavy rain, ___ which hundreds of families had to be evacuated.","subSkill":"cause_effect_linkers","explanation":"as a consequence of 后接名词短语，表示\"作为……的结果\"。句中 which 指代前面提到的洪水事件，因此 as a consequence of which 意为\"由此导致\"，逻辑最通顺。","instruction":"选择最合适的因果连接词，使句子逻辑通顺。","correctIndex":3},{"type":"choice","options":["This","That","Such","Which"],"sentence":"Scientists have discovered a new species of deep-sea fish. ___ creature was found at a depth of 3,000 metres.","subSkill":"reference_devices","explanation":"This 用于指代刚刚提到的事物，在书面语中 This creature 回指上文的 a new species of deep-sea fish，是最自然的指代方式，体现语篇衔接。","instruction":"选择最合适的指代词，使语篇衔接自然。","correctIndex":0},{"type":"choice","options":["In contrast","On the whole","By and large","In terms of advantages"],"sentence":"___, urban areas offer better job opportunities, higher salaries, and access to world-class education.","subSkill":"discourse_markers","explanation":"In terms of advantages 是明确的话语标记语，用于引出某一具体讨论维度（优势），与后面列举的三点内容逻辑衔接最紧密。On the whole 和 By and large 表示总体概括，不引出具体维度。","instruction":"选择最合适的话语标记语，使论述结构清晰。","correctIndex":3},{"type":"fill","sentence":"The construction project was delayed by six months. (be due to) This ___ a severe shortage of skilled workers in the region.","subSkill":"cause_effect_linkers","explanation":"was due to 是固定短语，意为\"是由……造成的\"，表示原因，主语 This 指代上文提到的工期延误，体现语篇指代与因果关系的结合。","instruction":"用括号内的连接词短语的正确形式填空，使句子逻辑通顺（每空一词或一个短语）。","acceptableAnswers":["was due to"]}],"5":[{"type":"fill","sentence":"Many governments have introduced stricter environmental regulations. ___, several major corporations have pledged to achieve carbon neutrality by 2040.","subSkill":"additive_linkers","explanation":"Similarly 是附加连接词，表示两件事在方向和性质上相似——政府和企业都在采取环保行动，构成并列递进关系。Furthermore 也可接受，但 Similarly 更强调两类主体行为的对应性。","instruction":"用适当的连接词或话语标记语填空，使语篇衔接连贯。每空填一个单词。","acceptableAnswers":["Similarly"]},{"type":"fill","sentence":"Although the medication had serious side effects, the doctor still recommended it. (Despite) Despite ___ serious side effects, the doctor still recommended the medication.","subSkill":"contrast_linkers","explanation":"Although 引导让步状语从句，改用 Despite 时需将从句转化为名词短语。the medication 的所有格形式是 its，所以写作 Despite its serious side effects，保持原句的让步含义不变。","instruction":"保持句意不变，用括号中的结构改写句子，将答案填入空白处。","acceptableAnswers":["its"]},{"type":"choice","options":["The former / the latter","This / that","One / another","Each / both"],"sentence":"Researchers have proposed two conflicting theories about the origin of language. ___ suggests that language evolved gradually, while ___ argues for a sudden cognitive leap.","subSkill":"reference_devices","explanation":"当上文明确提到两项内容时，the former（前者）和 the latter（后者）是书面语中最精确的指代方式，分别回指第一个理论和第二个理论，体现严谨的书面语指代。","instruction":"选择最合适的选项，使语篇的指代关系和逻辑衔接均正确。","correctIndex":0},{"type":"fill","sentence":"Because the data was incomplete, the analysts could not draw any firm conclusions. (owing to) Owing to ___ of the data, the analysts could not draw any firm conclusions.","subSkill":"cause_effect_linkers","explanation":"owing to 是介词短语，后接名词而非从句，所以需将形容词 incomplete 转化为名词 incompleteness，加上定冠词 the 构成名词短语，意义与原句等同。","instruction":"保持句意不变，用括号中的词语改写句子，将答案依次填入空白处。","acceptableAnswers":["the incompleteness"]}]},"mission":{"title":"Write a Balanced Opinion Paragraph","scenario":"你的英语老师要求全班就以下话题写一段意见段落（约80-100词）：'Should students be allowed to use smartphones in class?' 请运用本单元学习的连接词和语篇标记词，写出一段逻辑清晰、连贯的段落。","scaffolds":[{"hint":"用 'Furthermore' 或 'In addition' 补充一个额外的好处，例如访问学习资源或查找信息。","prefix":"There are clear benefits to allowing smartphones in class.","suffix":"","example":"Furthermore, students can access educational resources instantly, which saves valuable lesson time.","grammarCheck":"additive_linkers"},{"hint":"用 'Despite this' 或 'Nevertheless' 引出对这个反对意见的回应，表示即便如此，好处仍然存在。","prefix":"However, some teachers argue that smartphones are a major distraction.","suffix":"","example":"Despite this, research shows that clear usage guidelines can significantly reduce distraction, which makes the concern manageable.","grammarCheck":"contrast_linkers"},{"hint":"用 'therefore' 或 'consequently' 给出你的总结判断，注意用代词（it / this / they）指代前文提到的内容，避免重复。","prefix":"On balance,","suffix":".","example":"On balance, the benefits of smartphone use in class outweigh the drawbacks; therefore, schools should consider introducing a clear policy to manage it effectively.","grammarCheck":"cause_effect_linkers"}],"description":"在这个任务中，你将练习运用连接词、过渡语和指代词，写一段关于某个社会话题的平衡意见段落。你需要表达支持某一观点的理由，承认反对意见，并给出总结。","grammarType":"discourse_markers"},"discover":{"tip":"本单元的核心是连接词与指代词的正确使用，帮助写作更加连贯。重要区别如下：\n\n【添加关系】Furthermore / Moreover / In addition — 都表示'另外、而且'，用于补充信息。注意：这三个词后面必须跟逗号，且通常放在句首。\n\n【对比关系】However / Nevertheless / Yet / Despite this — 都表示转折，但用法略有不同。However 和 Nevertheless 是副词，放句首或句中；Yet 作为连接词连接两个独立分句（常不加逗号）；Despite this 后面不跟从句，而是指回上文的整体内容。\n\n【因果关系】Because 引导原因从句（because + 句子）；As a result / Therefore / Consequently 引导结果，通常放在句首或句中，后跟逗号。\n\n【指代关系】it / they / this / which — 指代前文中已出现的名词或整个句子的内容，避免重复。'which' 在非限制性定语从句中可以指代整件事情，例如：She won, which surprised everyone.\n\n【常见错误】\n1. 混用 because 和 because of：because 后接句子，because of 后接名词短语。例：She succeeded because she worked hard. / She succeeded because of her hard work.\n2. 在句首使用 Also 代替 Furthermore：Also 更口语化，正式写作中建议使用 Furthermore 或 In addition。","story":{"text":"Maria had always loved painting, yet she had never considered it a real career. However, after winning a local art competition, she began to think differently. Furthermore, her art teacher encouraged her to apply to a prestigious design school, which made her feel more confident. As a result, she spent the entire summer preparing her portfolio. Nevertheless, her parents were worried because they believed that artistic careers were unstable. In addition, they pointed out that she had already been accepted into a law programme. Despite this, Maria decided to follow her passion. She therefore wrote a long letter to her parents, explaining her reasons carefully. Consequently, they agreed to support her for one year. Moreover, they promised to attend her first exhibition. In the end, their support meant everything to her, and it gave her the courage to pursue her dream. This decision, after all, was not just about art — it was about who she truly was.","title":"A Difficult Decision","highlights":["yet","However","Furthermore","which","As a result","Nevertheless","because","In addition","Despite this","therefore","Consequently","Moreover","it","their","This decision"]},"questions":[{"options":["Maria's teacher","Maria","Maria's mother","A competition judge"],"question":"In the sentence 'after winning a local art competition, she began to think differently', what does 'she' refer to?","explanation":"'she' 是一个人称代词，用来指代前文已经提到的主语 Maria，这是英语写作中常见的指代关系（reference），避免重复使用同一名词。","correctIndex":1},{"options":["Furthermore","Consequently","Nevertheless","Moreover"],"question":"Which linker in the story introduces a CONTRAST to Maria's excitement about art?","explanation":"'Nevertheless' 是转折连接词，用于引出与前文相对的信息——尽管 Maria 变得自信，她的父母却依然担忧。这体现了对比关系。","correctIndex":2},{"options":["To add extra information to the previous idea","To show that one event caused another event","To contrast two opposite situations","To introduce a new topic unrelated to the previous one"],"question":"What is the function of 'As a result' in the story?","explanation":"'As a result' 是因果连接词，表示前面提到的事件（老师的鼓励和信心的增长）直接导致了后面的结果（她花了整个夏天准备作品集）。","correctIndex":1}]}},"12":{"levels":{"1":[{"type":"choice","options":["Describing","To describe","Having described","Described"],"sentence":"___ the graph accurately, students should focus on the overall trend first.","subSkill":"infinitive_phrases","explanation":"'To describe the graph accurately' 是目的不定式短语，置于句首表示目的，其逻辑主语与主句主语 'students' 一致，语法正确。","instruction":"选择正确的不定式短语完成句子，注意主语一致性。","correctIndex":1},{"type":"choice","options":["To study","Having studied","Being studied","Studies"],"sentence":"___ the pie chart carefully, the writer noticed a dramatic rise in urban populations.","subSkill":"participial_phrases","explanation":"'Having studied' 是完成分词，表示在主句动作（noticed）发生之前，研究图表的动作已经完成，符合逻辑时间顺序。","instruction":"选择正确的分词短语形式，注意动作的时间顺序。","correctIndex":1},{"type":"choice","options":["have","has","did","were"],"sentence":"Not only ___ carbon emissions increased, but air quality has also deteriorated.","subSkill":"inversion_for_emphasis","explanation":"'not only' 置于句首需要倒装。主语为 'carbon emissions'（复数），因此使用 'have'，形成 'Not only have carbon emissions increased...'","instruction":"找出倒装句中正确的语序。","correctIndex":0},{"type":"choice","options":["proves absolutely","suggests","confirms without doubt","guarantees"],"sentence":"The data ___ that urbanisation is the primary cause of the observed temperature rise.","subSkill":"hedging_language","explanation":"'suggests' 是典型的模糊限制语，表示数据提供了有力证据但不作绝对断言，符合雅思学术写作对结论表述的谨慎要求。","instruction":"选择合适的模糊限制语，使句子符合学术写作的谨慎语气。","correctIndex":1},{"type":"choice","options":["Rely","To rely","Relying","Relied"],"sentence":"___ on a single data source can lead to inaccurate conclusions in academic reports.","subSkill":"gerund_structures","explanation":"'Relying' 是动名词，在此句中作主语，表示一种普遍行为或习惯。动名词作主语在学术写作中比不定式更正式，也更常见。","instruction":"选择正确的动名词结构完成句子。","correctIndex":2},{"type":"choice","options":["has","have","did","does"],"sentence":"Rarely ___ such a significant drop in employment rates been recorded in peacetime.","subSkill":"inversion_for_emphasis","explanation":"'rarely' 置于句首触发倒装。'a significant drop'（单数名词）作主语，现在完成时倒装为 'has ... been recorded'，表示历史上极为罕见的现象。","instruction":"选择正确的倒装句形式。","correctIndex":0},{"type":"choice","options":["advocate","to advocate","advocating","advocated"],"sentence":"Rather than ___ a single solution, researchers recommend a multifaceted approach.","subSkill":"gerund_structures","explanation":"'rather than' 后接动名词（-ing形式），构成对比结构，是正式学术写作中的常见搭配。","instruction":"选择最恰当的不定式或动名词形式。","correctIndex":2},{"type":"choice","options":["is apparent","would seem","is certain","proves"],"sentence":"It ___ that further investment in infrastructure is needed to sustain economic growth.","subSkill":"hedging_language","explanation":"'It would seem' 使用了情态动词 'would' 加 'seem'，是双重模糊限制手段，体现了学术写作中对结论的高度谨慎，避免过度自信的表述。","instruction":"选择符合模糊限制语用法的选项。","correctIndex":1}],"2":[{"type":"choice","options":["To conduct","Having conducted","Being conducted","Conducted"],"sentence":"___ a thorough review of the literature, the research team proposed a new theoretical framework.","subSkill":"participial_phrases","explanation":"'Having conducted' 表示先于主句完成的动作（先完成文献综述，再提出框架），逻辑主语 'the research team' 与主句一致，是完成分词短语的标准用法。","instruction":"选择正确的完成分词短语，注意逻辑主语是否一致。","correctIndex":1},{"type":"fill","sentence":"(assess) ___ the long-term impact of the policy, economists have used a range of predictive models.","subSkill":"infinitive_phrases","explanation":"'To assess' 是目的不定式短语，置于句首表示经济学家使用预测模型的目的。注意不能用 'Having assessed'，因为逻辑顺序是：为了评估（目的）→使用模型（手段），而非先评估再使用。","instruction":"用括号中动词的正确不定式或分词形式填空，使句子符合学术写作规范。","acceptableAnswers":["To assess"]},{"type":"choice","options":["globalisation has","has globalisation","did globalisation","globalisation did"],"sentence":"Never before ___ globalisation spread so rapidly across developing economies as it has in the past two decades.","subSkill":"inversion_for_emphasis","explanation":"'Never before' 置于句首，需将助动词提前：'has globalisation spread'。使用现在完成时是因为 'in the past two decades' 表示一段延续到现在的时间段，与现在有关联。","instruction":"选择正确的倒装句式，注意否定副词与时态的配合。","correctIndex":1},{"type":"fill","sentence":"___ (interpret data selectively) can significantly distort the findings of an academic study.","subSkill":"gerund_structures","explanation":"动名词短语 'Interpreting data selectively' 作句子主语，整体等同于一个名词。这种结构在学术写作中非常正式，用于描述某类行为的普遍影响。","instruction":"将括号中的短语改写为动名词结构填入空白处。","acceptableAnswers":["Interpreting data selectively"]},{"type":"choice","options":["absolutely","appear to","definitely","certainly"],"sentence":"The results ___ indicate a correlation between screen time and reduced academic performance among adolescents.","subSkill":"hedging_language","explanation":"'appear to' 是情态性动词短语，作为模糊限制语弱化断言强度，表示这是基于数据的推断而非绝对结论，符合雅思学术写作的客观严谨要求。","instruction":"选择能正确表达模糊限制语的句子。","correctIndex":1},{"type":"fill","sentence":"Only when renewable energy becomes cost-competitive ___ (fossil fuels / be / likely to / phase out) at the scale required.","subSkill":"inversion_for_emphasis","explanation":"'Only when' 引导的从句置于句首时，主句需要倒装：'are fossil fuels likely to be phased out'。注意助动词 'are' 提前，主语 'fossil fuels' 随后，这是 'only + 状语' 倒装的标准结构。","instruction":"使用所给词语完成倒装句（句首词已给出）。","acceptableAnswers":["are fossil fuels likely to be phased out"]},{"type":"fill","sentence":"(compare) ___ the two bar charts, it becomes clear that the manufacturing sector experienced the steepest decline.","subSkill":"participial_phrases","explanation":"'Comparing' 是现在分词，表示与主句动作同时进行的伴随行为，逻辑主语是句子的隐含主语（分析者/读者），是 Task 1 描述图表的常见分词短语开头。","instruction":"用括号中动词的适当分词形式填空。","acceptableAnswers":["Comparing"]},{"type":"choice","options":["To reduce pollution, governments must invest in public transport.","To reduce pollution, new policies are needed.","Having reviewed the data, the analyst wrote a detailed report.","Using statistical software, researchers processed the results efficiently."],"sentence":"Which sentence contains a grammatical error in the non-finite phrase?","subSkill":"infinitive_phrases","explanation":"选项B中 'To reduce pollution' 的逻辑主语应该是人，但主句的主语是 'new policies'（政策无法主动减少污染），造成悬垂不定式错误。正确写法应为 'To reduce pollution, governments need new policies.'","instruction":"下列哪个句子中的不定式短语存在悬垂分词错误（dangling modifier）？","correctIndex":1}],"3":[{"type":"fill","sentence":"(examine) ___ trends over a thirty-year period, the authors were able to identify a consistent pattern of demographic change.","subSkill":"participial_phrases","explanation":"'Having examined' 是完成分词，表示在主句动作（were able to identify）之前，对趋势的考察已经完成。若用 'Examining'（现在分词），则表示同时进行，与 'thirty-year period' 暗示的完成性研究过程不符。","instruction":"用括号中动词的正确非谓语形式填空，并确保时间逻辑正确。","acceptableAnswers":["Having examined"]},{"type":"fill","sentence":"It appears that the government has underestimated the social costs. (使用 'would seem' 和不定式改写) The government ___ the social costs.","subSkill":"hedging_language","explanation":"'It appears that the government has underestimated' 可改写为 'The government would seem to have underestimated'。其中 'would seem to have + 过去分词' 结合了模糊限制语（would seem）和完成不定式（to have underestimated），表示对过去事件的谨慎推断，是高分学术写作的标志性结构。","instruction":"改写句子，保持原意不变，使用括号中指定的语法结构填入空白。（关键词转换）","acceptableAnswers":["would seem to have underestimated"]},{"type":"fill","sentence":"Rather than ___ (make sweeping generalisations), academic writers are encouraged to qualify their claims with appropriate evidence.","subSkill":"gerund_structures","explanation":"'rather than' 后接动名词（-ing形式），构成对比结构。注意 'rather than + 动名词' 是正式书面语的固定搭配，不能用 'rather than + 不定式'（虽有争议，但雅思学术写作推荐使用动名词形式保持风格一致性）。","instruction":"用括号中的词语构成正确的动名词或不定式短语填空，注意介词搭配。","acceptableAnswers":["making sweeping generalisations"]},{"type":"fill","sentence":"Researchers have rarely found such strong evidence for a direct causal link between diet and mental health. (以 'Seldom' 开头改写) Seldom ___.","subSkill":"inversion_for_emphasis","explanation":"以 'Seldom' 开头需倒装：助动词 'have' 提前置于主语 'researchers' 之前。改写后：'Seldom have researchers found such strong evidence...'。这种倒装句在雅思高分写作中用于强调某现象的稀有性，增强论证力度。","instruction":"构建完整的倒装句，将句首词 'Seldom' 与括号中的内容结合。（关键词转换）","acceptableAnswers":["have researchers found such strong evidence for a direct causal link between diet and mental health"]}],"4":[{"type":"choice","options":["To grow","Having grown","Being grown","Grow"],"sentence":"___ rapidly in the past decade, urban populations in Southeast Asia now face severe housing shortages.","subSkill":"participial_phrases","explanation":"此处需要完成时分词短语（Having grown），表示城市人口的增长发生在面临住房短缺之前，即先完成的动作用 having + 过去分词来表达时间上的先后关系。","instruction":"选择正确的非谓语动词形式完成句子。句子描述的是一个已完成的动作对另一件事的影响。","correctIndex":1},{"type":"choice","options":["If","Had","Should","Were"],"sentence":"___ the data been more clearly presented, the committee might have reached a different conclusion.","subSkill":"inversion_for_emphasis","explanation":"此句是含有虚拟语气的倒装条件句，省略 if 后将助动词 had 提前，构成 Had + 主语 + 过去分词的倒装结构，表示与过去事实相反的假设，语气更为正式。","instruction":"选择正确的倒装结构。这是一个强调否定副词的正式书面句子。","correctIndex":1},{"type":"choice","options":["will have","would have","may well have","must have"],"sentence":"The figures suggest that renewable energy consumption ___ doubled by 2030 if current trends continue.","subSkill":"hedging_language","explanation":"学术写作中需要使用对冲语言（hedging）来避免过于绝对的断言。may well have 表示有相当可能性但不确定，符合基于数据趋势进行预测的学术语境，比 will have（过于确定）或 must have（强烈推断已发生之事）更合适。","instruction":"选择最合适的对冲语言表达方式，使句子在学术写作中更客观、严谨。","correctIndex":2},{"type":"choice","options":["Include","To include","Included","Including"],"sentence":"___ comparative data alongside absolute figures is widely regarded as an effective strategy for IELTS Task 1 reports.","subSkill":"gerund_structures","explanation":"句子主语需要一个名词性成分，动名词 Including 作主语，表示一种行为或做法本身。不定式 To include 在正式学术写作中作主语时不如动名词常见，且与后接 is regarded 的搭配习惯上动名词更自然。","instruction":"选择正确的动名词结构。句子讨论的是报告写作中某一策略的效果。","correctIndex":3},{"type":"fill","sentence":"The report noted that, (decline) ___ steadily since 2010, the birth rate in several European nations had reached historic lows by 2020.","subSkill":"participial_phrases","explanation":"出生率下降的动作发生在报告指出的时间点（2020年）之前，因此使用完成时分词 having declined 来表示先于主句动作完成的背景信息，构成分词短语修饰主句主语。","instruction":"用括号中动词的正确非谓语形式填空，完成这个描述图表趋势的学术句子。","acceptableAnswers":["having declined"]}],"5":[{"type":"fill","sentence":"(consider) ___ the limitations of the dataset, the authors argue that the results should (treat) ___ with caution.","subSkill":"participial_phrases","explanation":"第一空：Considering 作独立分词短语，引出背景条件，意为考虑到；第二空：should be treated 表示被动语态与情态动词的结合，体现对冲语气（应当被谨慎对待），两者共同构成学术写作中严谨客观的表达。","instruction":"用括号内词语的正确形式填空（每个空填一个答案），完成这个综合运用分词短语与对冲语言的学术句子。","acceptableAnswers":["Considering","be treated"]},{"type":"fill","sentence":"原句：The government aims at reducing carbon emissions by 40% before 2035. 改写：The government aims ___ carbon emissions by 40% before 2035.","subSkill":"infinitive_phrases","explanation":"aim 作动词时，其后接不定式 to do，而非 aim at + 动名词（aim at 是名词短语 aim 的介词搭配用法）。在动词 aim 后应使用 to reduce，这是固定的不定式搭配，属于正式书面语的标准用法。","instruction":"用适当的不定式短语改写句子，保持原意，使其更适合雅思Task 2学术写作风格。将改写后的不定式短语填入空白处。","acceptableAnswers":["to reduce"]},{"type":"choice","options":["To establish conclusively","Establishing conclusively","Having established conclusively","Conclusively established"],"sentence":"___ a causal relationship between social media use and declining mental health remains difficult, as correlation does not necessarily imply causation.","subSkill":"gerund_structures","explanation":"此处需要动名词短语作主语，与谓语 remains 搭配；Establishing conclusively 作主语，描述建立因果关系这一行为的困难性。To establish 作主语在语法上可接受，但在此类强调行为过程困难性的学术句中，动名词是更地道、更自然的选择。","instruction":"选择最合适的选项，完成一个综合运用动名词与对冲语言的学术句子。","correctIndex":1},{"type":"fill","sentence":"Only when renewable infrastructure (receive) ___ adequate government funding (can / the transition / be accelerated) ___ significantly.","subSkill":"inversion_for_emphasis","explanation":"第一空：Only when 引导的时间状语从句中，主语 renewable infrastructure 为第三人称单数，谓语用一般现在时 receives 表示条件；第二空：Only when 置于句首时，主句需要倒装，即 can the transition be accelerated，将情态动词 can 提至主语前，被动语态保持不变。","instruction":"根据括号中的提示，用正确的倒装句式填写空白，完成这个强调副词短语的学术句子。","acceptableAnswers":["receives","can the transition be accelerated"]}]},"mission":{"title":"Academic Report: Technology and Education","scenario":"雅思Task 2题目：Some people believe that technology has had an overwhelmingly positive impact on education. To what extent do you agree? 请写一个正文段落（约100-130词），讨论技术对教育的至少一个具体影响，并给出有分析深度的论证。你的段落应包含：(1) 一个使用分词短语的开头句；(2) 一个倒装强调句；(3) 至少一处模糊限制语；(4) 一个动名词或不定式结构。","scaffolds":[{"hint":"用完成分词短语开头，然后用模糊限制语表述一个关于技术优势的观点（如：it would appear that / evidence suggests that）。","prefix":"Having examined recent studies on digital learning,","suffix":".","example":"Having examined recent studies on digital learning, it would appear that access to online resources has significantly broadened educational opportunities for students in remote areas.","grammarCheck":"participial_phrases"},{"hint":"使用 'not only...but also' 倒装结构列举两种教育影响。第一分句已给出倒装开头，注意第二分句不倒装，继续添加 'has it also' 或 'but it has also'。","prefix":"Not only has technology","suffix":", but it has also","example":"Not only has technology made educational content more accessible, but it has also transformed the way students collaborate across geographical boundaries.","grammarCheck":"inversion_for_emphasis"},{"hint":"用 'rather than + 动名词' 结构引出对立观点，然后用不定式短语说明更积极的做法（如：educators are encouraged to + 不定式，或 it seems more productive to...）。","prefix":"Rather than viewing technology as a threat to traditional pedagogy,","suffix":".","example":"Rather than viewing technology as a threat to traditional pedagogy, it seems more productive to integrate digital tools as a complement to conventional teaching methods, thereby enriching the overall learning experience.","grammarCheck":"gerund_structures"}],"description":"你将撰写一段雅思学术类写作Task 2的正文段落，讨论技术对现代教育的影响。你的段落必须展示本单元所学的高级语法结构，包括非谓语动词短语、倒装句和模糊限制语，以体现雅思高分写作的语言多样性与学术严谨性。","grammarType":"participial_phrases"},"discover":{"tip":"本单元涉及五种雅思高级语法结构，需注意区分和正确使用：\n\n1. 不定式短语 (Infinitive phrases)：'To understand X, one must...' — 用于表达目的或条件，置于句首时逗号后接主句。常见错误：主语不一致，如 'To improve scores, practice is needed'（应改为 'To improve scores, students need practice'）。\n\n2. 分词短语 (Participial phrases)：现在分词 'Using advanced techniques, scientists...' 表示伴随动作；完成分词 'Having analysed data, researchers...' 表示先于主句发生的动作。关键：分词短语的逻辑主语必须与主句主语一致，否则产生悬垂分词错误。\n\n3. 动名词结构 (Gerund structures)：'Rather than relying on one solution' / 'drawing firm conclusions would be premature' — 动名词作主语或介词宾语，语气比不定式更正式客观。\n\n4. 倒装句 (Inversion for emphasis)：当 'not only', 'rarely', 'never', 'seldom', 'only then' 等否定/限制性副词置于句首时，主句须倒装：'Rarely have scientists seen...' (not 'Rarely scientists have seen')。注意：if 省略的虚拟条件句也需倒装：'Were this true, ...'。\n\n5. 模糊限制语 (Hedging language)：使用 'appear to', 'seem to', 'would seem', 'may', 'might', 'it is likely that', 'suggests that' 等表达学术谨慎。区别：'proves' 表确定；'suggests/indicates' 表有据可查但不绝对；'would seem/appear' 表推测。","story":{"text":"Renewable energy has become one of the most debated topics in academic circles. To understand the scale of this shift, one need only examine global statistics from the past decade. Having analysed data from over 50 countries, researchers concluded that solar and wind power now account for a significant proportion of electricity generation. Not only has investment in fossil fuels declined sharply, but public support for clean energy has also grown considerably. It is worth noting that governments appear to be prioritising long-term sustainability over short-term economic gain. Using advanced modelling techniques, scientists have projected that renewable sources may supply up to 70% of global energy needs by 2050. Rarely have policymakers faced such urgent pressure to reform energy infrastructure. Some scholars suggest that, rather than relying on a single solution, diversifying energy portfolios seems to be the most prudent approach. It would seem that the transition is inevitable; however, the pace remains uncertain. Given the complexity of the issue, drawing firm conclusions at this stage would be premature. Nevertheless, the evidence strongly indicates that a sustainable future is not only desirable but also increasingly achievable.","title":"The Rise of Renewable Energy","highlights":["To understand","Having analysed","Not only has investment","Using advanced modelling techniques","Rarely have policymakers","rather than relying","drawing firm conclusions","It would seem","appears to be","may supply"]},"questions":[{"options":["The researchers and the analysis happened at the same time.","The analysis was completed before the researchers drew their conclusion.","The researchers were still analysing data when they concluded.","The analysis will be done in the future."],"question":"In the sentence 'Having analysed data from over 50 countries, researchers concluded...', what does the participial phrase 'Having analysed...' tell us?","explanation":"完成分词短语 'Having analysed' 表示该动作发生在主句动作（concluded）之前，即研究人员先完成了数据分析，然后才得出结论。这是学术写作中表示先后顺序的常见结构。","correctIndex":1},{"options":["Because 'not only' must always come at the start of a sentence.","Because placing 'not only' at the front and inverting the subject and auxiliary adds formal emphasis, typical in academic writing.","Because 'investment has not only declined' is grammatically incorrect.","Because inversion is required whenever a negative word appears anywhere in the sentence."],"question":"Why does the story use 'Not only has investment declined...' instead of 'Investment has not only declined...'?","explanation":"当 'not only' 置于句首时，需要进行主谓倒装（has investment），以形成强调效果。这种结构在雅思学术写作中体现正式语气，强调两个并列的重要事实，是倒装句的典型用法。","correctIndex":1},{"options":["'drawing firm conclusions'","'It would seem that the transition is inevitable'","'Rarely have policymakers faced'","'Having analysed data'"],"question":"Which phrase from the story is an example of hedging language, used to avoid making a claim sound too absolute?","explanation":"'It would seem that...' 是典型的模糊限制语（hedging language），使用情态动词 'would' 和 'seem' 来弱化断言的语气，表示这是一种推断而非确定事实。雅思学术写作中需要对结论保持谨慎态度，避免过度概括。","correctIndex":1}]}}}};
